		["Ardalan is inside {area:1438}."] = "阿達藍在{area:1438}裡面。",
		["Below ground"] = "地下",
		["Climb to the top of {area:249} and plant the head in the soft dirt mound."] = "爬上{area:249}頂端，把頭顱插在鬆軟的土堆上。",
