t.guides["forever/alliance/50-60/03-winterspring"] = (function() return {
		["Boat to {area:150}"] = "搭船前往{area:150}",
		["Fly to Theramore"] = "飛往塞拉摩",
		["Fly to {area:3197}"] = "飛往{area:3197}",
