		["Pureheart, Dumah, Valorfist and MacDonnell stand around the middle of the camp, by the flight master."] = "純心、杜瑪、瓦洛菲斯特和麥克唐奈站在營地中央附近，飛行管理員旁邊。",
		["Scare {npc:10978} with {item:12928}"] = "用{item:12928}嚇唬{npc:10978}",
		["The Deadwood cauldron in {zone:1448}: keep it"] = "{zone:1448}的死木大鍋：保留此任務",
		["The Winterfall furbolg village lies east of {area:2255}: Shaman (56-57), Den Watchers (55-56) and Ursa (57-58), all above you. Kill the Shaman first, they heal, and pull from the edge. {npc:10738} in the cave at the back is elite: stay out."] = "冬泉熊怪的村莊位於{area:2255}東邊：冬泉薩滿（56-57級）、冬泉巢穴守衛（55-56級）和冬泉巨熊怪（57-58級），都比你高。先殺薩滿，他們會治療，並從邊緣開始拉。後方洞穴裡的{npc:10738}是精英：不要進去。",
		["The next guide starts here and flies to {area:3197}."] = "下一份指南從這裡開始，然後飛往{area:3197}。",
		["The ruins lie around the frozen lake south of {area:2253}. Pick up the four relic fragments lying in the ruins and the Moontouched Feathers on the ground where the wildkin roam."] = "遺跡位於{area:2253}南邊結冰湖泊的周圍。拾取散落在遺跡中的四塊遺物碎片，以及梟獸遊蕩處地上的月光羽毛。",
		["The three pieces of the doll lie in the ruined houses of {area:2262}; picking one up can call out ghosts. Combine them into the doll."] = "洋娃娃的三個部分在{area:2262}的廢屋裡；撿起其中一個可能會引出鬼魂。把它們組合成洋娃娃。",
		["To {area:2101}"] = "前往{area:2101}",
		["Your Hearthstone is not set at {area:144} (the {zone:1425} guide binds there at 47, and this guide leaves {zone:1452} through it): bind at {area:2255} instead, for the trips back to town."] = "你的爐石沒有設定在{area:144}（{zone:1425}指南在47級時於那裡綁定，而本指南會透過爐石離開{zone:1452}）：改為綁定在{area:2255}，方便往返城鎮。",
		["Your Hearthstone is still set at {area:144}: from there the gryphon to {area:3197} is about ten minutes quicker than {area:2255}'s flight to Theramore and the boat."] = "你的爐石仍設定在{area:144}：從那裡搭乘獅鷲飛往{area:3197}，比從{area:2255}飛往塞拉摩再搭船快大約十分鐘。",
		["Zaeldarr is elite: grouping up is advised. He waits at the bottom of the {area:2261}, the crypt in the south-west of the zone."] = "塞達爾是精英：建議組隊。他在本區西南部的地穴{area:2261}最底層等著。",
		["{area:144} flight master"] = "{area:144}的飛行管理員",
		["{area:2255}'s inn"] = "{area:2255}的旅店",
		["{npc:10926}'s doll"] = "{npc:10926}的洋娃娃",
		["{npc:10978}: {npc:7583} and {npc:10977} come later"] = "{npc:10978}：{npc:7583}和{npc:10977}稍後再找",
		["{npc:11616}: the termites come later, in {area:2627}"] = "{npc:11616}：白蟻稍後在{area:2627}處理",
		["{quest:5152}, in the {zone:1422}: keep it"] = "{zone:1422}的{quest:5152}：保留此任務",
} end)()
t.guides["forever/alliance/50-60/04-western-plaguelands"] = (function() return {
		["Andorhal"] = "安多哈爾",
		["Back to {npc:7775}'s camp, just south-east of {npc:7765}: the {item:11242} buys three Videre Elixirs. Keep them: {npc:9298} takes one, and {npc:9299} in {area:976} shows himself only to someone who has drunk one."] = "回到{npc:7765}東南邊不遠的{npc:7775}營地：{item:11242}可換三瓶維迪爾藥劑。留著它們：{npc:9298}要一瓶，而{area:976}的{npc:9299}只會現身給喝過藥劑的人看。",
		["Below ground"] = "地下",
		["Cross the river east to the {area:2261}, the crypt in the south-west of the zone. The {object:177667} lies inside: its key is on {npc:12248} in the far north-east, done in the next guide."] = "向東渡河前往{area:2261}，也就是本區西南部的地穴。{object:177667}就在裡面：它的鑰匙在遠處東北方的{npc:12248}身上，在下一份指南完成。",
		["Cross the river west to {npc:1855}'s hut."] = "向西渡河前往{npc:1855}的小屋。",
		["Cross the south of the crater to {npc:9619} by the ramp."] = "穿越環形山南部，前往坡道旁的{npc:9619}。",
		["Diseased Grizzlies"] = "生病的灰熊",
		["Dredge Crushers dig further west; Stonelash Pincers, Flayers and Rock Stalkers hunt the same sands."] = "掘泥摧毀者在更西邊挖掘；石鞭巨鉗蠍、石鞭掠奪者和石行蜘蛛在同一片沙地上狩獵。",
		["Dredge Strikers dig in the dunes north-west of the hold; Stonelash Scorpids and Sand Skitterers roam all around."] = "掘泥打擊者在要塞西北方的沙丘中挖掘；石鞭蠍和掠沙蜘蛛在四周遊蕩。",
		["Ends with {npc:9298} in {zone:1452}: keep it"] = "在{zone:1452}的{npc:9298}處完成：保留此任務",
		["Escort {npc:9999}"] = "護送{npc:9999}",
		["Fly from {area:976} to {area:541}. {npc:8737} stands at the back of the refuge; {npc:9117} is in the cave behind him.\n{npc:9997}'s friend {npc:9999} has gone missing."] = "從{area:976}飛往{area:541}。{npc:8737}站在避難所後方；{npc:9117}在他身後的洞穴裡。\n{npc:9997}的朋友{npc:9999}失蹤了。",
		["Fly to Theramore"] = "飛往塞拉摩",
		["Fly to {area:2268}"] = "飛往{area:2268}",
		["Fly to {area:271}"] = "飛往{area:271}",
		["Fly to {area:976}"] = "飛往{area:976}",
		["For the druids of {zone:1457}: keep it"] = "給{zone:1457}的德魯伊：保留此任務",
		["For {area:3197}: keep it"] = "交給{area:3197}：保留此任務",
		["For {zone:1448}: keep it"] = "給{zone:1448}：保留此任務",
		["For {zone:1451}: keep it"] = "給{zone:1451}：保留此任務",
		["From {area:702}, fly to {area:1116}."] = "從{area:702}飛往{area:1116}。",
		["Horgus' skull lies at {area:2624} and Marduk's sword in the {area:2623}, each where ghosts fight; grown Plaguehounds hunt the plains between."] = "霍古斯的顱骨在{area:2624}，馬杜克的劍在{area:2623}，各自位於鬼魂交戰之處；成年的瘟疫犬在兩地之間的平原上獵食。",
		["Into {zone:1451}"] = "進入{zone:1451}",
		["Listen to his story"] = "聆聽他的故事",
		["Mark {npc:10902} with the {item:12815}"] = "用{item:12815}標記{npc:10902}",
		["Mark {npc:10903} with the {item:12815}"] = "用{item:12815}標記{npc:10903}",
		["Mark {npc:10904} with the {item:12815}"] = "用{item:12815}標記{npc:10904}",
		["Mark {npc:10905} with the {item:12815}"] = "用{item:12815}標記{npc:10905}",
		["More watches"] = "更多懷錶",
		["Northern Pylon"] = "北部水晶塔",
		["On {npc:7583}"] = "關於{npc:7583}",
		["Portal to {zone:1438}"] = "傳送門前往{zone:1438}",
		["Radley and Durgen"] = "萊德雷與杜爾根",
		["Ranshalla in {zone:1452}: keep it"] = "{zone:1452}的蘭莎爾拉：保留此任務",
		["Ride back south to the camp."] = "向南騎回營地。",
		["Ride back south-west to the {area:2742} tower in {area:2738}; climb it and kill the ambushers that rise for the encrusted object."] = "向西南騎回{area:2738}的{area:2742}高塔；爬上去，擊殺為了異種蠍粘液包裹的物體而出現的伏擊者。",
		["Ride east to the border river: {npc:1855} lives in a small hut on the bank."] = "向東騎往邊界河：{npc:1855}住在河岸的小屋裡。",
		["Ride east to {area:537}, climb it and use {npc:10541} at the lava vents near the top."] = "向東騎往{area:537}，爬上去，在山頂附近的熔岩噴口使用{npc:10541}。",
		["Ride north along the east side to the gorilla plateau. {npc:9622}, a level 55 gorilla, sits in its deepest cave: clear the gorillas at the cave mouth first."] = "沿東側向北騎往猩猩高地。55級的猩猩{npc:9622}在最深的洞穴裡：先清掉洞口的猩猩。",
		["Ride north to {area:2627}. {npc:12384} lives in the ruined hut, and his receipt book lies in the ruined inn nearby."] = "向北騎往{area:2627}。{npc:12384}住在廢棄的小屋裡，他的收據冊在附近的旅店廢墟中。",
		["Ride north up the road to the Northridge lumber mill; {npc:11610} hides at the camp's edge."] = "沿著道路向北騎往北山伐木場；{npc:11610}躲在營地邊緣。",
		["Ride north-west to the Dalson farm. The diary lies in the barn; a wandering skeleton carries the outhouse key, and {npc:10836} waits in the outhouse with the cabinet key."] = "向西北騎往達爾松的農場。日記在穀倉裡；一具遊蕩的骷髏帶著廁所的鑰匙，{npc:10836}在廁所裡等著，身上有櫃子的鑰匙。",
		["Ride north-west to {area:2276}, at the edge of the {area:2277}."] = "向西北騎往{area:2277}邊緣的{area:2276}。",
		["Ride south to {area:201}, where {npc:11078} guards the cauldron."] = "向南騎往{area:201}，{npc:11078}在那裡守護著瘟疫之鍋。",
		["Ride south-west to the camp."] = "向西南騎回營地。",
		["Ride south-west to {npc:7771}'s camp at the {area:1938}."] = "向西南騎往{area:1938}的{npc:7771}營地。",
		["Ride west along the road to the hot springs."] = "沿著道路向西騎往溫泉。",
		["Ride west into the Ravenwind Ruins: {npc:7774} hides in the small round building at the back. Open the chest beside her for {item:9189}: it lasts 15 minutes, like the quest."] = "向西騎進鴉風廢墟：{npc:7774}躲在後方的小圓形建築裡。打開她旁邊的箱子取得{item:9189}：效果持續15分鐘，和任務時限一樣。",
		["Ride west to {area:2627}. Plaguehound Runts, Plaguebats and Carrion Grubs roam its woods; fill the {item:15042} at the big termite mounds and kill the Frenzied Plaguehounds further north."] = "向西騎往{area:2627}。瘟疫幼犬、瘟疫蝙蝠和腐肉蟲在樹林中遊蕩；在大白蟻丘裝滿{item:15042}，並擊殺更北邊的狂怒的瘟疫犬。",
		["Scare {npc:7583} with {item:12928}"] = "用{item:12928}嚇唬{npc:7583}",
		["Take the boat to the mainland and ride north-east to {npc:14637}'s camp by the {area:1119}."] = "搭船前往大陸，向東北騎往{area:1119}旁{npc:14637}的營地。",
		["Ten {item:11040} from the {item:11020}"] = "從{item:11020}取得十個{item:11040}",
		["The Andorhal watchtowers"] = "安多哈爾哨塔",
		["The Scarlet Crusade"] = "血色十字軍",
		["The Scarlet Medics, Hunters, Knights and Mages patrol the lumber camp and the road toward {area:190}."] = "血色醫護員、血色獵人、血色騎士和血色法師在伐木場和通往{area:190}的道路上巡邏。",
		["The Tar Beasts and Tar Lords wallow in the {area:538}, south of the refuge on the way down into the crater."] = "焦油怪和焦油領主在{area:538}裡打滾，位於避難所南邊、往下進入環形山的路上。",
		["The cauldron sits at the {area:202}, by {npc:10739}' farm."] = "瘟疫之鍋位於{area:202}，在{npc:10739}的農場旁。",
		["The cauldron sits at {area:200}, north-east of Felstone; its Cauldron Lord stands beside it."] = "瘟疫之鍋位於費爾斯通東北方的{area:200}；它的護鍋者就站在旁邊。",
		["The crater"] = "環形山",
		["The gorillas live on {area:1943}, just east of the pylon: take the pelts for {npc:9619} now, while you are up here. Stay out of the deepest cave: {npc:9622} is level 55.\nCareful: Un'Goro Gorillas (level 50-51) call for help from allies within 20 yd once they drop to 25% health. There is a cave full of apes in the area, and fighting there brings many adds."] = "猩猩住在水晶塔東邊不遠的{area:1943}：趁你在上面時，現在就替{npc:9619}收集毛皮。別進最深的洞穴：{npc:9622}是55級。\n小心：安戈洛猩猩（50-51級）血量降到25%時會向20碼內的同伴求援。這一帶有個滿是猩猩的洞穴，在那裡戰鬥會引來大量怪物。",
		["The shrunken giants roam the {area:1119}; the sea elementals wade along the coast to the west."] = "被縮小的巨人在{area:1119}遊蕩；海元素沿著西邊的海岸涉水而行。",
		["The tortured druids and sentinels haunt the ruined village south-west of {npc:13220}."] = "被折磨的德魯伊和被折磨的哨兵在{npc:13220}西南方的廢墟村莊出沒。",
		["The wooden sign beside {npc:9997}"] = "{npc:9997}旁邊的木牌",
		["The {area:2742} tower"] = "{area:2742}高塔",
		["The {item:11242} grows inside a ruined building north of {npc:7765}: climb in through the break in its wall from the ledge beside it."] = "{item:11242}生長在{npc:7765}北邊一棟廢墟建築裡：從旁邊的岩架穿過牆上的破口爬進去。",
		["Umber in {zone:1450}: keep it"] = "{zone:1450}的阿姆伯爾：保留此任務",
		["Upstairs"] = "樓上",
		["Use the {item:12627} by the grain silos to draw out Temporal Parasites. {quest:5154} is one of the musty tomes in the town hall. Every skeleton in town drops {quest:5537}."] = "在穀倉旁使用{item:12627}引出時光寄生蟲。{quest:5154}是市政廳裡發霉的書籍之一。城裡的每具骷髏都會掉落{quest:5537}。",
		["Use the {item:12815} at the foot of each of the four watchtowers around the edge of Andorhal, north of the camp."] = "在營地北邊、安多哈爾周圍四座哨塔的塔底各使用一次{item:12815}。",
		["Walk into {area:1769} and take the {zone:1450} branch of the tunnel to {area:2361}."] = "走進{area:1769}，沿著隧道的{zone:1450}岔路前往{area:2361}。",
		["{area:190} overlook"] = "{area:190}瞭望點",
		["{area:1943}: kill these as you meet them"] = "{area:1943}：遇到時順手擊殺",
		["{area:200} cauldron"] = "{area:200}的瘟疫之鍋",
		["{area:201} cauldron"] = "{area:201}的瘟疫之鍋",
		["{area:202} cauldron"] = "{area:202}的瘟疫之鍋",
		["{item:12894}, at the monument"] = "{item:12894}，在紀念碑旁",
		["{item:12954} lies in the town hall of {area:190}, west of {npc:1855}: the Scarlet guards stand close together."] = "{item:12954}在{npc:1855}西邊{area:190}的市政廳裡：血色衛兵站得很密集。",
		["{item:12955} lies east of the barn at {area:201}."] = "{item:12955}在{area:201}穀倉的東邊。",
		["{npc:10667} waits in the ruined inn on the west side of Andorhal."] = "{npc:10667}在安多哈爾西側的旅店廢墟裡等候。",
		["{npc:10878} and {npc:7740} stand by the Temple of the Moon; fill {item:11682} at the moonwell inside."] = "{npc:10878}和{npc:7740}站在月神殿旁；在殿內的月井裝滿{item:11682}。",
		["{npc:10927}'s farmhouse stands on the hill east of the camp; {npc:10936}'s monument is just north of it."] = "{npc:10927}的農舍在營地東邊的山丘上；{npc:10936}的紀念碑就在它北邊。",
		["{npc:11886} is elite: grouping up is advised"] = "{npc:11886}是精英：建議組隊",
		["{npc:17082}, at the Alliance tents"] = "{npc:17082}，在聯盟帳篷旁",
		["{npc:1852} is a level 61 elite"] = "{npc:1852}是61級精英",
		["{npc:5411} in {area:976}: keep it"] = "{area:976}的{npc:5411}：保留此任務",
		["{npc:5901}, on the coast north of town"] = "{npc:5901}，在城鎮北邊的海岸",
		["{npc:7740}: keep it for {area:976}"] = "{npc:7740}：保留給{area:976}",
		["{npc:7775}'s camp lies north of the {area:1119}. He brews the {item:11243} from an {item:11242}: take his errand for one."] = "{npc:7775}的營地在{area:1119}北邊。他用{item:11242}釀製{item:11243}：接下他的差事來換一瓶。",
		["{npc:7900}: keep it for {zone:1446}"] = "{npc:7900}：保留給{zone:1446}",
		["{npc:9299} in {area:976}: keep it"] = "{area:976}的{npc:9299}：保留此任務",
		["{npc:9299} is a ghost at the graveyard just east of town: drink a {item:11243} there, which kills you, release your spirit and talk to him as a ghost. Then run back to your body to come back to life: the gravestone stands nearby."] = "{npc:9299}是鎮東邊不遠墓地裡的鬼魂：在那裡喝下{item:11243}，你會死亡，釋放靈魂後以鬼魂狀態和他交談。然後跑回屍體復活：墓碑就在附近。",
		["{npc:9684}'s lair lies in the jungle north of {npc:9619}, below the eastern cliffs: use {item:11568} there. {npc:9684} is level 56: start at full health."] = "{npc:9684}的巢穴位於{npc:9619}北邊的叢林，在東面懸崖下方：在那裡使用{item:11568}。{npc:9684}是56級：滿血再開打。",
		["{npc:9999} sits on the south-east slope of {area:537}, in the middle of the crater."] = "{npc:9999}坐在環形山中央{area:537}的東南坡上。",
		["{quest:3444} is in {area:392}"] = "{quest:3444}在{area:392}",
		["{quest:5210}, at {area:2268}: keep it"] = "{quest:5210}，在{area:2268}：保留此任務",
		["{quest:6762} in {zone:1450}: keep it"] = "{zone:1450}的{quest:6762}：保留此任務",
		["{zone:1455}, where the next guide trains, has no druid trainer"] = "下一份指南學習技能的{zone:1455}沒有德魯伊訓練師",
} end)()
t.guides["forever/alliance/50-60/05-silithus"] = (function() return {
		["Boat to {area:35}"] = "搭船前往{area:35}",
		["Chromie in Andorhal: keep it"] = "安多哈爾的克羅米：保留此任務",
		["Fly to {area:2268}"] = "飛往{area:2268}",
		["Fly to {zone:1453}"] = "飛往{zone:1453}",
		["For {npc:10778}: keep it"] = "交給{npc:10778}：保留此任務",
		["Its jars are filled on the next Un'Goro visit"] = "它的罐子會在下次造訪安戈洛時裝滿",
		["Scourge Champions"] = "天災勇士",
		["Scourge Champions (59) roam the {area:2270}, north of {area:2268}. Pass {npc:11063}'s {item:13156} over each one you kill: the skulls that resonate are the ones he wants. Pull them one at a time."] = "天災勇士（59級）在{area:2268}北邊的{area:2270}遊蕩。每殺一隻就用{npc:11063}的{item:13156}掃過牠：產生共鳴的頭骨才是他要的。一次只拉一隻。",
		["Take the boat from {area:392} to {area:35} and fly to {zone:1453}."] = "從{area:392}搭船前往{area:35}，然後飛往{zone:1453}。",
		["{item:13155}, from the Scourge Champions"] = "{item:13155}，來自天災勇士",
		["{item:14613}, from {npc:11886}"] = "{item:14613}，來自{npc:11886}",
		["{npc:14724}, by the tram"] = "{npc:14724}，在地鐵旁",
		["{npc:332}, in SI:7"] = "{npc:332}，在軍情七處",
		["{npc:3520}, who walks the canals"] = "{npc:3520}，在運河邊走動",
		["{quest:6184} at {area:3197}: keep it"] = "{area:3197}的{quest:6184}：保留此任務",
} end)()
t.guides["forever/alliance/50-60/06-silithus"] = (function() return {
		["Andorhal"] = "安多哈爾",
		["Angerclaw bears and Felpaw wolves"] = "怒爪熊和魔爪狼",
		["Araj is elite: grouping up is advised."] = "阿拉基是精英：建議組隊。",
		["Below ground"] = "地下",
		["Boat to {area:150}"] = "搭船前往{area:150}",
		["Bronzebeard's Encampment"] = "銅鬚營地",
		["Climb {area:537} in the middle of the crater and use the {item:14644} by the lava lake at the top, with two Thorium Bars in your bags. Fill {npc:9616}'s Empty Pure Sample Jars on the Primal Oozes in the pools around the ridge."] = "爬上環形山中央的{area:537}，背包裡帶著兩塊瑟銀錠，在山頂熔岩湖旁使用{item:14644}。在山脊周圍水池中的原生軟泥怪身上裝滿{npc:9616}的純淨樣本瓶。",
		["Fly to {area:271}"] = "飛往{area:271}",
		["Fly to {area:3137} in {zone:1447} and ride west along the road to {area:2358}, just over the {zone:1440} border."] = "飛往{zone:1447}的{area:3137}，沿著道路向西騎往剛越過{zone:1440}邊界的{area:2358}。",
		["Fly to {area:976}"] = "飛往{area:976}",
		["Fly to {area:976}."] = "飛往{area:976}。",
		["Fly to {zone:1453}"] = "飛往{zone:1453}",
		["Follow the road north to {area:1767}. The Irontree Stompers carry the heart; finish the claws on the Angerclaw Grizzlies and Felpaw Ravagers of the north."] = "沿著道路向北前往{area:1767}。鐵木踐踏者身上帶著心臟；在北邊的怒爪灰熊和魔爪掠奪者身上收集完爪子。",
		["Follow {npc:9298}'s directions to the mouth of {area:2256}, past the Frostmaul giants: pass them one at a time."] = "依照{npc:9298}的指示前往{area:2256}入口，途中經過霜槌巨人：一次通過一個。",
		["Hand him the ten texts you kept"] = "把你保留的十份文本交給他",
		["Havunth's camp sits just west of {area:3425}."] = "哈弗斯的營地就在{area:3425}西邊。",
		["Irontree Stompers"] = "鐵木踐踏者",
		["Keep the {item:11169}, the claws and the heart he hands back"] = "保留他還給你的{item:11169}、爪子和心臟",
		["Pick up the supplies around the wagon and take {npc:10301}'s amulet back from the owlbeasts nearby."] = "撿起馬車周圍的補給物資，並從附近的梟獸身上奪回{npc:10301}的護符。",
		["Portal to {zone:1438}"] = "傳送門前往{zone:1438}",
		["Ride back south along the road to the Sanctuary."] = "沿著道路向南騎回聖地。",
		["Ride back south-east to the hermit."] = "向東南騎回隱士處。",
		["Ride back south-west to {area:3197}."] = "向西南騎回{area:3197}。",
		["Ride east into the hills. Use the {item:11169} to summon {quest:4005}, then defeat him for the totem."] = "向東騎進山丘。使用{item:11169}召喚{quest:4005}，然後擊敗他取得圖騰。",
		["Ride east to the ruins of {area:2738}. The {object:179565} lies among the ruined buildings, watched by Tortured Sentinels."] = "向東騎往{area:2738}的廢墟。{object:179565}在毀壞的建築之間，由被折磨的哨兵看守。",
		["Ride north along the west side to Mayna's small camp."] = "沿著西側向北騎往瑪恩納的小營地。",
		["Ride north to the Deadwood furbolgs' village by the {area:1769} cave mouth."] = "向北騎往{area:1769}洞口旁的死木熊怪村莊。",
		["Ride north to {area:541}. Use {npc:10980} beside {npc:10977}."] = "向北騎往{area:541}。在{npc:10977}旁邊使用{npc:10980}。",
		["Ride north up the road to the lumber mill and set the termite barrel down in the middle of it."] = "沿著道路向北騎往伐木場，把白蟻桶放在伐木場中央。",
		["Ride south-west to the dwarves' camp near the southern mountains and question {npc:15171} and {npc:15170}. {npc:15190}'s satchel lies in the sand just south-east of the camp."] = "向西南騎往南部山脈附近的矮人營地，詢問{npc:15171}和{npc:15170}。{npc:15190}的背包就在營地東南方的沙地上。",
		["Ride south-west to {npc:7771}'s camp at the {area:1938}."] = "向西南騎往{area:1938}的{npc:7771}營地。",
		["Running {area:2057} ({area:2298}, south-east {zone:1422}) or {area:2279} instead of grinding gets you there faster in a group. Skip this step to grind solo."] = "組隊打{area:2057}（{zone:1422}東南部的{area:2298}）或{area:2279}代替練等能更快達到目標。若要單人練等，跳過此步驟。",
		["Running {area:2577} in {zone:1444} instead of grinding gets you there faster in a group. Skip this step to grind solo."] = "組隊打{zone:1444}的{area:2577}代替練等能更快達到目標。若要單人練等，跳過此步驟。",
		["Take the portal up to {zone:1457}."] = "走傳送門上到{zone:1457}。",
		["Take the road west down into the crater and ride to the {area:540}, the silithid cave in the south. The {npc:10041} waits in its deepest chamber."] = "沿著道路向西下到環形山中，騎往南部的異種蟲洞穴{area:540}。{npc:10041}在最深處的洞室等著。",
		["Take the {area:1769} tunnel from its {zone:1452} mouth, west of {npc:9298}, and follow the {area:493} branch to {area:2361}. {npc:11939} studies by the lake shore."] = "從{npc:9298}西邊位於{zone:1452}的入口進入{area:1769}隧道，沿著{area:493}的岔路前往{area:2361}。{npc:11939}在湖岸邊做研究。",
		["Ten more for {quest:8323}"] = "再十份給{quest:8323}",
		["The Twilight's Hammer dig fills the north-west corner: tablet fragments lie on the ground and the Dust Stormers and Desert Rumblers carry them too. Every cultist can drop an {item:20404}: keep twenty, ten for {npc:15306} and ten for {npc:15194} later."] = "暮光之錘的挖掘場佔據西北角：石碑碎片散落在地上，灰塵風暴和沙漠奔行者身上也帶著碎片。每個教徒都可能掉落{item:20404}：保留二十份，十份給{npc:15306}，十份稍後給{npc:15194}。",
		["The hermit hides among the rocks south-east of {area:2738}."] = "隱士躲在{area:2738}東南方的岩石間。",
		["The {area:2479}"] = "{area:2479}",
		["The {area:3098}"] = "{area:3098}",
		["Twilight Tablet Fragments"] = "暮光石碑碎片",
		["Twilight's Hammer cultists"] = "暮光之錘教徒",
		["Upstairs"] = "樓上",
		["Use the jars on slain oozes"] = "對被殺死的軟泥怪使用瓶子",
		["Wait a moment for {npc:9116}"] = "稍等一下{npc:9116}",
		["grind on {npc:14564} at {area:2627}, {zone:1423}"] = "在{zone:1423}的{area:2627}擊殺{npc:14564}練等",
		["{area:1770} braziers"] = "{area:1770}的火盆",
		["{area:2057} (optional)"] = "{area:2057}（可選）",
		["{area:2057} fits levels 58 to 60; {quest:5505} is handed in at {area:3197} below."] = "{area:2057}適合58到60級；{quest:5505}在下方的{area:3197}繳交。",
		["{area:2577} (optional)"] = "{area:2577}（可選）",
		["{area:541} flight master"] = "{area:541}飛行管理員",
		["{npc:10301}'s camp"] = "{npc:10301}的營地",
		["{npc:10301}'s supplies"] = "{npc:10301}的補給物資",
		["{npc:10667} waits in the ruined inn on the west side of Andorhal, the ruined city north of the camp. {npc:1852} guards his phylactery in the middle of the town."] = "{npc:10667}在安多哈爾西側的旅店廢墟裡等候，安多哈爾是營地北邊的廢墟城市。{npc:1852}在城鎮中央守著他的護符匣。",
		["{npc:10778}'s ghost wanders by the farmhouse of {area:199}, west of Andorhal. The Jabbering Ghouls in the field carry the other half of the charm: combine the two halves."] = "{npc:10778}的鬼魂在{area:199}的農舍旁徘徊，位於安多哈爾西邊。田裡喋喋不休的食屍鬼身上帶著護符的另一半：把兩半合起來。",
		["{npc:11801}'s house stands in {area:2361}, east of {npc:11939}."] = "{npc:11801}的房子在{area:2361}，位於{npc:11939}東邊。",
		["{npc:11803} holds the cultists' camp in the far south-west."] = "{npc:11803}佔據西南角落的教徒營地。",
		["{npc:14722}, in the {object:2096}"] = "{npc:14722}，在{object:2096}",
		["{npc:1852} is a level 61 elite"] = "{npc:1852}是61級精英",
		["{npc:1855} (optional)"] = "{npc:1855}（可選）",
		["{npc:1855} lives in a small hut on the border river, north-east of the lumber camp. Hand in {quest:5781} if you finished it."] = "{npc:1855}住在伐木場東北方、邊界河畔的小屋裡。如果你已完成{quest:5781}，就交給他。",
		["{npc:3516}, atop the {area:1658}"] = "{npc:3516}，在{area:1658}頂端",
		["{npc:4155}, in the bank"] = "{npc:4155}，在銀行裡",
		["{npc:7740} in {zone:1457}: keep it"] = "{zone:1457}的{npc:7740}：保留此任務",
		["{npc:7740}, in the Temple of the Moon"] = "{npc:7740}，在月神殿裡",
		["{npc:8737}, at the back of the refuge"] = "{npc:8737}，在避難營深處",
		["{quest:5085}: {npc:9298} in {zone:1452}, keep it"] = "{quest:5085}：{zone:1452}的{npc:9298}，保留此任務",
		["{zone:1451}, {zone:1448}, {zone:1452} & the Plaguelands"] = "{zone:1451}、{zone:1448}、{zone:1452}與瘟疫之地",
		["{zone:1453} has no shaman trainer"] = "{zone:1453}沒有薩滿訓練師",
} end)()
t.guides["forever/alliance/dwarf/01-dun-morogh"] = (function() return {
		["Back through the tunnel to {npc:257597}' cave above the farm."] = "穿過隧道回到農場上方{npc:257597}的洞穴。",
		["Back to {area:77}"] = "返回{area:77}",
		["Back to {npc:257446} in {area:77}. He gives you the {item:6635}: take the rubble-marked path that climbs west from the south of the valley to the Spirit Stone on the ridge, drink the Sapta beside it and speak to the {npc:5891}, then bring its {item:6656} back to Teo."] = "回到{area:77}的{npc:257446}處。他會給你{item:6635}：沿著山谷南邊有碎石標記、向西攀升的小路走到山脊上的靈石，在旁邊喝下靈契並與{npc:5891}交談，然後把牠的{item:6656}帶回給他。",
		["Back to {npc:257597}"] = "返回{npc:257597}",
		["Below ground"] = "地下",
		["Each of Grif Wildheart's quests hands you a {item:15908}: use it on the beast he names, then bring the rod back to him at the {area:131} smithy. Large Crag Boars, Snow Leopards and Ice Claw Bears all roam the fields just south and east of {area:131}."] = "格瑞夫的每個任務都會給你一根{item:15908}：對他指定的野獸使用，然後把馴獸棒帶回{area:131}鐵匠舖交給他。大峭壁野豬、雪豹和冰爪熊都在{area:131}南邊和東邊的原野上遊蕩。",
		["Farsen camps on the ridge overlooking the {area:134} from the west. Talk to him for his farsight."] = "法森在{area:134}西邊俯瞰採掘場的山脊上紮營。與他交談以獲得他的遠視。",
		["Feather Charms, from the Frostmane Novices"] = "羽毛符咒，來自霜鬃食人妖新兵",
		["Firewood"] = "木柴",
		["Follow the road east past the depot to {area:138}."] = "沿著道路向東經過補給站，前往{area:138}。",
		["Follow the road north-east from {area:131} to the depot below the {zone:1455} road."] = "沿著道路從{area:131}向東北前往{zone:1455}道路下方的補給站。",
		["From the {quest:2997} she gives you"] = "來自她給你的{quest:2997}",
		["Frostmane Troll Whelps fill the slopes south and east of {npc:786}'s camp."] = "小霜鬃食人妖遍布{npc:786}營地南邊和東邊的山坡。",
		["Heal and fortify {npc:12427}"] = "治療並強化{npc:12427}",
		["Iceclaw Bear Pendants, from the Frostmane Troll Whelps on the slopes above the camp"] = "冰爪熊墜飾，來自營地上方山坡上的小霜鬃食人妖",
		["Inside {area:77}"] = "{area:77}裡面",
		["Leave {zone:1453} by the main gate, go south to {area:87} and east along the road to the {area:62}. {npc:881} (level 9) stands by its farmhouse."] = "從正門離開{zone:1453}，向南前往{area:87}，再沿著道路向東前往{area:62}。{npc:881}（9級）站在農舍旁。",
		["Leper Gnomes around Brewnall and the {area:133} road carry the cogs and gears. Ice Claw Bears, Elder Crag Boars and Snow Leopards roam the hills around the lake."] = "烈酒村和{area:133}道路周圍的麻瘋地精身上帶著齒輪和零件。冰爪熊、老峭壁野豬和雪豹在湖周圍的山丘上遊蕩。",
		["Level 4 spells, before Gozwin's camp"] = "4級法術，在前往戈茲溫的營地之前學習",
		["Ragged Young Wolves roam the snow just south of {area:77}."] = "蓬毛幼狼在{area:77}南邊的雪地上遊蕩。",
		["Rockjaw Troggs and Burly Rockjaw Troggs dig all over the valley floor south of {area:77}."] = "石齶穴居人和壯實的石齶怪在{area:77}南邊的谷地各處挖掘。",
		["Sit by Eric's campfire (type /sit) and wait for the buff. With a profession learned, Eric also offers its Camping 101, which its trainer takes: blacksmithing with {npc:1241} and {skill:129} with {npc:2326} in {area:131}, mining and engineering at {area:189}."] = "坐在艾瑞克的營火旁（輸入 /sit）並等待增益效果。學會專業技能後，艾瑞克還會提供該專業的「露營入門」，交給該專業的訓練師：鍛造找{area:131}的{npc:1241}，{skill:129}找{npc:2326}，採礦和工程學則在{area:189}。",
		["Small Crag Boars graze around {npc:714}'s camp and along the west side of the valley."] = "小型峭壁野豬在{npc:714}的營地周圍和山谷西側覓食。",
		["Snow Leopards and boars roam the snow between the ranch and the quarry. Blacksmiths: Copper Bars come from smelting {item:2770} or the trade vendors."] = "雪豹和野豬在牧場與採掘場之間的雪地上遊蕩。鐵匠：銅錠可以熔煉{item:2770}取得，或向商業用品商人購買。",
		["South down the road to {area:144}, finishing the ears, meat and ichor on the way. {npc:1340} walks the road through town."] = "沿著道路向南前往{area:144}，途中收集完耳朵、肉和膿液。{npc:1340}在穿過城鎮的道路上巡邏。",
		["Stonesplinter Seers (level 13) stand among the troggs in the south of {area:923}, south of {npc:257808}; Tunnel Rat Geomancers (level 12) work the {area:149} at the north end of the loch. The troggs come in packs and some throw from range: pull one at a time."] = "碎石怪先知（13級）站在{npc:257808}營地南邊、{area:923}南部的穴居人之間；坑道鼠地卜師（12級）在湖北端的{area:149}工作。穴居人成群出現，有些會從遠處投擲：一次拉一隻。",
		["Subdue the voidwalker"] = "制服虛空行者",
		["The Fire Spirit Stone"] = "火焰靈石",
		["The Scalding Mornbrew lasts five minutes: go straight north to {npc:836} inside {area:77}."] = "熱酒只能維持五分鐘：直接向北前往{area:77}裡的{npc:836}。",
		["The boars"] = "野豬",
		["The firewood lies in the snow around the frozen lake by the refuge."] = "木柴散落在避難所旁結冰湖泊周圍的雪地上。",
		["The quarry troggs"] = "採掘場的穴居人",
		["The troggs"] = "穴居人",
		["The troll cave"] = "食人妖洞穴",
		["The tunnel"] = "隧道",
		["The {area:2257}"] = "{area:2257}",
		["The {object:269} in the basement"] = "地下室的{object:269}",
		["Upstairs"] = "樓上",
		["Use the {item:6866} on {npc:6177}"] = "對{npc:6177}使用{item:6866}",
		["You start in front of {area:77}, the stone hall at the north end of the valley. {npc:658} waits outside the door."] = "你從{area:77}前方開始，那是山谷北端的石廳。{npc:658}在門外等候。",
		["Young wolves"] = "幼狼",
		["talk to the trainer"] = "與訓練師交談",
		["{area:131} and the depot"] = "{area:131}與補給站",
		["{area:77} is on the way north from {npc:786}'s camp to the tunnel: {npc:837}, the priest trainer inside, sends priests of level 5 to {npc:1226} in {area:131}."] = "{area:77}位於從{npc:786}營地向北前往隧道的路上：裡面的牧師訓練師{npc:837}會派5級的牧師去找{area:131}的{npc:1226}。",
		["{item:13850}: the {object:176785}"] = "{item:13850}：{object:176785}",
		["{item:277976}, in the camp"] = "{item:277976}，在營地裡",
		["{item:286325} is by the frozen lake, among the ice elementals."] = "{item:286325}在結冰湖泊旁，位於冰元素之間。",
		["{item:3083}: Leper Gnomes"] = "{item:3083}：麻瘋地精",
		["{item:3084}: Leper Gnomes"] = "{item:3084}：麻瘋地精",
		["{item:5026} and the {item:6652}"] = "{item:5026}和{item:6652}",
		["{item:5026}: Tunnel Rat Geomancers"] = "{item:5026}：坑道鼠地卜師",
		["{item:6635}, beside the Spirit Stone"] = "{item:6635}，在靈石旁邊",
		["{item:6636}, beside the Spirit Stone"] = "{item:6636}，在靈石旁邊",
		["{item:6652}: Stonesplinter Seers"] = "{item:6652}：碎石怪先知",
		["{item:6847}: Dark Iron Spies"] = "{item:6847}：黑鐵間諜",
		["{npc:10090} in {zone:1455} takes it"] = "由{zone:1455}的{npc:10090}接收",
		["{npc:1126}: tame it with the {item:15908}"] = "{npc:1126}：用{item:15908}馴服牠",
		["{npc:1196}: tame it with the {item:15908}"] = "{npc:1196}：用{item:15908}馴服牠",
		["{npc:1201}: tame it with the {item:15908}"] = "{npc:1201}：用{item:15908}馴服牠",
		["{npc:1226}, upstairs: {item:16605}"] = "{npc:1226}，在樓上：{item:16605}",
		["{npc:1226}: heal {npc:12427} south of {area:131}"] = "{npc:1226}：治療{area:131}南邊的{npc:12427}",
		["{npc:1231}, at the smithy"] = "{npc:1231}，在鐵匠舖",
		["{npc:12427} kneels wounded on the ridge between two low walls just south of {area:131}, across the road from the hunter pet trainer, on the walk back from Rumbleshot's camp. Cast {spell:613} (Rank 2) on him, then {spell:1243}: Rank 1 of {spell:613} does not count."] = "{npc:12427}受傷跪在{area:131}正南方兩道矮牆之間的山脊上，與獵人寵物訓練師隔著道路相對，就在從朗伯希特的營地返回的路上。對他施放{spell:613}（等級2），然後施放{spell:1243}：等級1的{spell:613}不算數。",
		["{npc:12738}, next to him"] = "{npc:12738}，在他旁邊",
		["{npc:12738}: timed, five minutes to reach {npc:836} in {area:77}"] = "{npc:12738}：限時任務，五分鐘內抵達{area:77}的{npc:836}處",
		["{npc:1698}: blacksmiths only"] = "{npc:1698}：僅限鐵匠",
		["{npc:1702}, beside {npc:5392}"] = "{npc:1702}，在{npc:5392}旁邊",
		["{npc:1965} guards the tunnel out of the valley, east of {area:77}; {npc:6782} stands beside him at its mouth."] = "{npc:1965}守衛著{area:77}東邊通往山谷外的隧道；{npc:6782}站在隧道口他的身旁。",
		["{npc:1977}, in the quarry"] = "{npc:1977}，在採掘場裡",
		["{npc:2326}, inside the distillery"] = "{npc:2326}，在釀酒廠裡面",
		["{npc:257446}, inside {area:77}"] = "{npc:257446}，在{area:77}裡面",
		["{npc:257446}: {npc:5873} and your {item:5175}"] = "{npc:257446}：{npc:5873}和你的{item:5175}",
		["{npc:257597} waits in a cave above the farm north-west of the {area:806}; the path up starts behind the farm."] = "{npc:257597}在{area:806}西北方農場上方的洞穴裡等候；上山的小路從農場後方開始。",
		["{npc:257597}: {npc:2523}, your {item:5176} and the {item:263412}"] = "{npc:257597}：{npc:2523}、你的{item:5176}和{item:263412}",
		["{npc:257808} gives you the {item:6636}. Climb to the peak above his camp, drink the Sapta beside the Spirit Stone and defeat the {npc:5893}, then place its {item:6655} in the {object:61934}, atop the Shrine of Eternal Flame."] = "{npc:257808}會給你{item:6636}。爬上營地上方的山峰，在靈石旁喝下靈契並擊敗{npc:5893}，然後把牠的{item:6655}放進永恆之火神殿頂端的{object:61934}。",
		["{npc:258113}: {npc:257597} by the South Gate takes it"] = "{npc:258113}：由南門旁的{npc:257597}接收",
		["{npc:265813}: for {npc:1241}, in the cellar west of the distillery"] = "{npc:265813}：交給{npc:1241}，在釀酒廠西邊的地窖裡",
		["{npc:265813}: for {npc:1702} at {area:189}"] = "{npc:265813}：交給{area:189}的{npc:1702}",
		["{npc:265813}: for {npc:2326} in the {area:2102}"] = "{npc:265813}：交給{area:2102}的{npc:2326}",
		["{npc:265813}: for {npc:5392} at {area:189}"] = "{npc:265813}：交給{area:189}的{npc:5392}",
		["{npc:2756} stands by {npc:8416} at the door of {area:77}. Gozwin's camp is in the hills just north-west; the {npc:269075} prowls around it."] = "{npc:2756}和{npc:8416}一起站在{area:77}門口。戈茲溫的營地就在西北方的山丘上；{npc:269075}在營地周圍徘徊。",
		["{npc:460}, inside {area:77}"] = "{npc:460}，在{area:77}裡面",
		["{npc:5392}, at the depot"] = "{npc:5392}，在補給站",
		["{npc:5480} trains warriors in {object:2100}, near Osric's shop; the tram from {zone:1455} arrives in the {object:28027}, north of it. {npc:6089} and {npc:6090} stand together by the {object:2152} there. {npc:6090} fights you for his mug. If {npc:5480} doesn't offer {quest:1638}, go straight to {npc:6089}: he gives {quest:1639} without it."] = "{npc:5480}在{object:2100}奧斯里克的商店附近訓練戰士；從{zone:1455}出發的地鐵抵達其北邊的{object:28027}。{npc:6089}和{npc:6090}一起站在那裡的{object:2152}旁。{npc:6090}會為了他的杯子和你打一架。如果{npc:5480}沒有提供{quest:1638}，直接去找{npc:6089}：即使沒有該任務，他也會給你{quest:1639}。",
		["{npc:6120}: {npc:6122} in {zone:1453} takes it"] = "{npc:6120}：由{zone:1453}的{npc:6122}接收",
		["{npc:6122} waits in the cellar of the {object:2164}, in the {object:2101}."] = "{npc:6122}在{object:2101}的{object:2164}地下室等候。",
		["{npc:6179}: Redemption"] = "{npc:6179}：救贖",
		["{npc:658}: a rune for {npc:895}"] = "{npc:658}：給{npc:895}的符文",
		["{npc:658}: read the {quest:98581}"] = "{npc:658}：閱讀{quest:98581}",
		["{npc:713}, next to {npc:658}"] = "{npc:713}，在{npc:658}旁邊",
		["{npc:714}'s camp is at the west end of the valley. {item:10438} lies in the snow south of it, his Chest by the troll cave and his Bucket of Bolts east of the cave: grab them as you pass."] = "{npc:714}的營地在山谷西端。{item:10438}在營地南邊的雪地上，他的箱子在食人妖洞穴旁，他的螺栓桶在洞穴東邊：經過時順手拿取。",
		["{npc:786} and {npc:12738} camp at the south-west edge of the valley, below the troll cave."] = "{npc:786}和{npc:12738}在山谷西南邊緣、食人妖洞穴下方紮營。",
		["{npc:808} is inside the troll cave east of {npc:786}'s camp, not on the hill above it: go in at the mouth and follow the tunnel to the back."] = "{npc:808}在{npc:786}營地東邊的食人妖洞穴裡，不在洞穴上方的山丘上：從洞口進去，沿著隧道走到最深處。",
		["{npc:837}, inside {area:77}"] = "{npc:837}，在{area:77}裡面",
		["{npc:837}, the priest trainer"] = "{npc:837}，牧師訓練師",
		["{npc:895}, the hunter trainer"] = "{npc:895}，獵人訓練師",
		["{npc:916}, the rogue trainer"] = "{npc:916}，盜賊訓練師",
		["{npc:926}, the paladin trainer"] = "{npc:926}，聖騎士訓練師",
		["{object:660964}, by the mailbox in {object:171524}"] = "{object:660964}，在{object:171524}的郵箱旁",
} end)()
t.guides["forever/alliance/gnome/01-dun-morogh"] = (function() return {
		["Back through the tunnel to {npc:257597}' cave above the farm."] = "穿過隧道回到農場上方{npc:257597}的洞穴。",
		["Back to {area:77}"] = "返回{area:77}",
		["Back to {npc:257446} in {area:77}. He gives you the {item:6635}: take the rubble-marked path that climbs west from the south of the valley to the Spirit Stone on the ridge, drink the Sapta beside it and speak to the {npc:5891}, then bring its {item:6656} back to Teo."] = "回到{area:77}的{npc:257446}處。他會給你{item:6635}：沿著山谷南邊有碎石標記、向西攀升的小路走到山脊上的靈石，在旁邊喝下靈契並與{npc:5891}交談，然後把牠的{item:6656}帶回給他。",
		["Back to {npc:257597}"] = "返回{npc:257597}",
		["Below ground"] = "地下",
		["Farsen camps on the ridge overlooking the {area:134} from the west. Talk to him for his farsight."] = "法森在{area:134}西邊俯瞰採掘場的山脊上紮營。與他交談以獲得他的遠視。",
		["Feather Charms, from the Frostmane Novices"] = "羽毛符咒，來自霜鬃食人妖新兵",
		["Firewood"] = "木柴",
		["Follow the road east past the depot to {area:138}."] = "沿著道路向東經過補給站，前往{area:138}。",
		["Follow the road north-east from {area:131} to the depot below the {zone:1455} road."] = "沿著道路從{area:131}向東北前往{zone:1455}道路下方的補給站。",
		["Frostmane Troll Whelps fill the slopes south and east of {npc:786}'s camp."] = "小霜鬃食人妖遍布{npc:786}營地南邊和東邊的山坡。",
		["Heal and fortify {npc:12427}"] = "治療並強化{npc:12427}",
		["Iceclaw Bear Pendants, from the Frostmane Troll Whelps on the slopes above the camp"] = "冰爪熊墜飾，來自營地上方山坡上的小霜鬃食人妖",
		["Inside {area:77}"] = "{area:77}裡面",
		["Leave {zone:1453} by the main gate, go south to {area:87} and east along the road to the {area:62}. {npc:881} (level 9) stands by its farmhouse."] = "從正門離開{zone:1453}，向南前往{area:87}，再沿著道路向東前往{area:62}。{npc:881}（9級）站在農舍旁。",
		["Leave {zone:1453} by the main gate. The {quest:1861} waterfall is south-west of the gates, on the way west to {zone:1436}: fill {item:7207} at its base."] = "從正門離開{zone:1453}。{quest:1861}瀑布在城門西南方，位於往西前往{zone:1436}的路上：在瀑布底部裝滿{item:7207}。",
		["Leper Gnomes around Brewnall and the {area:133} road carry the cogs and gears. Ice Claw Bears, Elder Crag Boars and Snow Leopards roam the hills around the lake."] = "烈酒村和{area:133}道路周圍的麻瘋地精身上帶著齒輪和零件。冰爪熊、老峭壁野豬和雪豹在湖周圍的山丘上遊蕩。",
		["Level 4 spells, before Gozwin's camp"] = "4級法術，在前往戈茲溫的營地之前學習",
		["Ragged Young Wolves roam the snow just south of {area:77}."] = "蓬毛幼狼在{area:77}南邊的雪地上遊蕩。",
		["Rockjaw Troggs and Burly Rockjaw Troggs dig all over the valley floor south of {area:77}."] = "石齶穴居人和壯實的石齶怪在{area:77}南邊的谷地各處挖掘。",
		["Sit by Eric's campfire (type /sit) and wait for the buff. With a profession learned, Eric also offers its Camping 101, which its trainer takes: blacksmithing with {npc:1241} and {skill:129} with {npc:2326} in {area:131}, mining and engineering at {area:189}."] = "坐在艾瑞克的營火旁（輸入 /sit）並等待增益效果。學會專業技能後，艾瑞克也會提供該專業的「露營入門」，由該專業的訓練師接收：鍛造交給{area:131}的{npc:1241}，{skill:129}交給{npc:2326}，採礦和工程學則在{area:189}。",
		["Small Crag Boars graze around {npc:714}'s camp and along the west side of the valley."] = "小型峭壁野豬在{npc:714}的營地周圍和山谷西側覓食。",
		["Snow Leopards and boars roam the snow between the ranch and the quarry. Blacksmiths: Copper Bars come from smelting {item:2770} or the trade vendors."] = "雪豹和野豬在牧場與採掘場之間的雪地上遊蕩。鐵匠：銅錠可以熔煉{item:2770}取得，或向商業用品商人購買。",
		["South down the road to {area:144}, finishing the ears, meat and ichor on the way. {npc:1340} walks the road through town."] = "沿著道路向南前往{area:144}，途中把耳朵、熊肉和蜘蛛膿液收集完。{npc:1340}在穿過城鎮的道路上巡邏。",
		["Stonesplinter Seers (level 13) stand among the troggs in the south of {area:923}, south of {npc:257808}; Tunnel Rat Geomancers (level 12) work the {area:149} at the north end of the loch. The troggs come in packs and some throw from range: pull one at a time."] = "碎石怪先知（13級）站在{npc:257808}營地南邊、{area:923}南部的穴居人之間；坑道鼠地卜師（12級）在湖北端的{area:149}工作。穴居人成群出現，有些會從遠處投擲：一次拉一隻。",
		["Subdue the voidwalker"] = "制服虛空行者",
		["The Fire Spirit Stone"] = "火焰靈石",
		["The Scalding Mornbrew lasts five minutes: go straight north to {npc:836} inside {area:77}."] = "熱酒只能維持五分鐘：直接向北前往{area:77}裡的{npc:836}。",
		["The boars"] = "野豬",
		["The firewood lies in the snow around the frozen lake by the refuge."] = "木柴散落在避難所旁結冰湖泊周圍的雪地上。",
		["The quarry troggs"] = "採掘場的穴居人",
		["The troggs"] = "穴居人",
		["The troll cave"] = "食人妖洞穴",
		["The tunnel"] = "隧道",
		["The {area:2257}"] = "{area:2257}",
		["The {object:269} in the basement"] = "地下室的{object:269}",
		["Upstairs"] = "樓上",
		["You start in front of {area:77}, the stone hall at the north end of the valley. {npc:658} waits outside the door."] = "你從{area:77}前方開始，那是山谷北端的石廳。{npc:658}在門外等候。",
		["Young wolves"] = "幼狼",
		["talk to the trainer"] = "與訓練師交談",
		["{area:131} and the depot"] = "{area:131}與補給站",
		["{area:77} is on the way north from {npc:786}'s camp to the tunnel: {npc:837}, the priest trainer inside, sends priests of level 5 to {npc:1226} in {area:131}."] = "{area:77}位於從{npc:786}的營地向北前往隧道的路上：裡面的牧師訓練師{npc:837}會把5級的牧師派往{area:131}的{npc:1226}處。",
		["{item:13850}: the {object:176785}"] = "{item:13850}：{object:176785}",
		["{item:277976}, in the camp"] = "{item:277976}，在營地裡",
		["{item:286325} is by the frozen lake, among the ice elementals."] = "{item:286325}在結冰湖泊旁，位於冰元素之間。",
		["{item:3083}: Leper Gnomes"] = "{item:3083}：麻瘋地精",
		["{item:3084}: Leper Gnomes"] = "{item:3084}：麻瘋地精",
		["{item:5026} and the {item:6652}"] = "{item:5026}和{item:6652}",
		["{item:5026}: Tunnel Rat Geomancers"] = "{item:5026}：坑道鼠地卜師",
		["{item:6635}, beside the Spirit Stone"] = "{item:6635}，在靈石旁邊",
		["{item:6636}, beside the Spirit Stone"] = "{item:6636}，在靈石旁邊",
		["{item:6652}: Stonesplinter Seers"] = "{item:6652}：碎石怪先知",
		["{npc:1226}, upstairs: {item:16605}"] = "{npc:1226}，在樓上：{item:16605}",
		["{npc:1226}: heal {npc:12427} south of {area:131}"] = "{npc:1226}：治療{area:131}南邊的{npc:12427}",
		["{npc:1226}: {npc:258785} in {zone:1455} takes it"] = "{npc:1226}：由{zone:1455}的{npc:258785}接收",
		["{npc:1241}, in the cellar west of the distillery"] = "{npc:1241}，在酒廠西邊的地窖裡",
		["{npc:12427} kneels wounded on the ridge between two low walls just south of {area:131}, across the road from the hunter pet trainer, on the walk back from Rumbleshot's camp. Cast {spell:613} (Rank 2) on him, then {spell:1243}: Rank 1 of {spell:613} does not count."] = "{npc:12427}受了傷，跪在{area:131}南邊兩道矮牆之間的山脊上，與獵人寵物訓練師隔著道路相對，就在從朗沙特的營地返回的路上。對他施放{spell:613}（等級2），然後施放{spell:1243}：等級1的{spell:613}不算數。",
		["{npc:12738}, next to him"] = "{npc:12738}，在他旁邊",
