		["{npc:714}'s camp is at the west end of the valley. {item:10438} lies in the snow south of it, his Chest by the troll cave and his Bucket of Bolts east of the cave: grab them as you pass."] = "{npc:714}的營地在山谷西端。{item:10438}在營地南邊的雪地上，他的箱子在食人妖洞穴旁，他的螺栓桶在洞穴東邊：經過時順手拿取。",
		["{npc:786} and {npc:12738} camp at the south-west edge of the valley, below the troll cave."] = "{npc:786}和{npc:12738}在山谷西南邊緣、食人妖洞穴下方紮營。",
		["{npc:808} is inside the troll cave east of {npc:786}'s camp, not on the hill above it: go in at the mouth and follow the tunnel to the back."] = "{npc:808}在{npc:786}營地東邊的食人妖洞穴裡，不在洞穴上方的山丘上：從洞口進去，沿著隧道走到最深處。",
		["{npc:837}, inside {area:77}"] = "{npc:837}，在{area:77}裡面",
		["{npc:837}, the priest trainer"] = "{npc:837}，牧師訓練師",
		["{npc:912}, the warrior trainer"] = "{npc:912}，戰士訓練師",
		["{npc:916}, the rogue trainer"] = "{npc:916}，盜賊訓練師",
		["{npc:944}, the mage trainer, inside {area:77}"] = "{npc:944}，法師訓練師，在{area:77}裡面",
		["{object:660964}, by the mailbox in {object:171524}"] = "{object:660964}，在{object:171524}的郵箱旁",
} end)()
t.guides["forever/alliance/human/01-elwynn-forest"] = (function() return {
		["\"Auntie\" Bernice Stonefield"] = "波尼斯·斯通菲爾德姑媽",
		["Back to {npc:6122}. Use the {item:6928} at the summoning circle in the {object:2164}'s cellar and defeat the voidwalker it calls."] = "回到{npc:6122}那裡。在{object:2164}地下室的召喚法陣使用{item:6928}，擊敗被召喚出的虛空行者。",
		["Billy plays in the {area:64}, east of the mine."] = "比利在礦坑東邊的{area:64}玩耍。",
		["Chunks of Boar Meat"] = "大塊野豬肉",
		["Class trainer"] = "職業訓練師",
		["Crystal Kelp Fronds"] = "水晶藻葉",
		["Defias Rogue Wizards camp on the shores of {area:86}; they drop the Red Linen Bandanas too. {object:56} lies in the murloc village on the north-east shore."] = "迪菲亞流浪巫師在{area:86}岸邊紮營；他們也會掉落紅色亞麻面罩。{object:56}在東北岸的魚人村裡。",
		["Defias Thugs camp in the clearing east of the Abbey and along the valley's east side."] = "迪菲亞暴徒在修道院東邊的空地及山谷東側紮營。",
		["Follow the hills south to the tower, on the road west."] = "沿著山丘向南走到塔，在往西的路上。",
		["Follow the hills south to the tower."] = "沿著山丘向南走到塔。",
		["Follow the path north to the mine. Kobold Workers swarm outside it; every kobold in the valley can drop the {object:83763}."] = "沿著小路向北前往礦坑。狗頭人勞工聚集在礦坑外；山谷中的每個狗頭人都可能掉落{object:83763}。",
		["Follow the road north from {area:87} into {zone:1453}. {npc:5497} stands in the Wizard's Sanctum, the tower of the {object:2101}; she gives you a flask for the {quest:1861} waterfall."] = "沿著道路從{area:87}向北進入{zone:1453}。{npc:5497}站在{object:2101}的高塔裡；她會給你一個瓶子，用於{quest:1861}瀑布。",
		["Follow the road north from {area:87} into {zone:1453}. {npc:6122} waits in the cellar of the {object:2164}, in the {object:2101}."] = "沿著道路從{area:87}向北進入{zone:1453}。{npc:6122}在{object:2101}的{object:2164}地下室等候。",
		["Follow the road south out of {area:87} to the {area:64}. {npc:251} waits by the house."] = "沿著道路向南離開{area:87}，前往{area:64}。{npc:251}在房子旁等候。",
		["Fun with Elementals: {npc:248464}"] = "快樂玩元素：{npc:248464}",
		["He stands by the river west of the farm."] = "他站在農場西邊的河邊。",
		["Head back out through {area:87} and east along the road to the {area:62}. {npc:881} (level 9) stands by its farmhouse."] = "穿過{area:87}返回，沿路向東到{area:62}。{npc:881}（9級）站在農舍旁。",
		["Heal and fortify {npc:12423}"] = "治療並強化{npc:12423}",
		["Inside {area:34}"] = "{area:34}內部",
		["It lies by the river north-west of the logging camp."] = "它躺在伐木場西北方的河邊。",
		["Kobold Laborers work the tunnels inside the mine. {npc:248362} waits down the second turn on the right."] = "狗頭人苦力在礦坑隧道裡工作。{npc:248362}在右邊第二個轉角深處等著。",
		["Large Candles"] = "大蠟燭",
		["Leave {zone:1453} by the main gate. The {quest:1861} waterfall is south-west of the gates, on the way west to {zone:1436}: fill {item:7207} at its base."] = "從正門離開{zone:1453}。{quest:1861}瀑布在城門西南方，位於往西前往{zone:1436}的路上：在瀑布底部裝滿{item:7207}。",
		["Lost Books: Kobold Miners and Tunnelers"] = "遺失的書：狗頭人礦工和狗頭人隧道工",
		["Murlocs and Murloc Streamrunners hold the east shore; the Junk Piles lie in their camp. Careful: the murlocs stand close together, so a fight easily pulls two or three at once: pull them one at a time from the edge of the camp, and don't chase one into the next group."] = "魚人和魚人士兵佔據東岸；垃圾堆在牠們的營地裡。小心：魚人站得很近，一場戰鬥很容易同時引來兩三隻：從營地邊緣一次拉一隻，也不要追著一隻跑進下一群。",
		["North-east of the logging camp. Defias Rogue Wizards camp on the shores of the lake."] = "在伐木場東北方。迪菲亞流浪巫師在湖岸邊紮營。",
		["Painted Gnoll Armbands"] = "彩色豺狼人臂章",
		["Red Burlap Bandanas"] = "紅色粗麻面罩",
		["Red Linen Bandanas"] = "紅色亞麻面罩",
		["Riverpaw gnolls camp in the hills west of {area:86}; the {quest:91725} lie in their camps."] = "河爪豺狼人在{area:86}西邊的山丘紮營；{quest:91725}就在他們的營地裡。",
		["She stands by her cart at the vineyard east of the Abbey."] = "她站在修道院東邊葡萄園的推車旁。",
		["She stands outside the mine entrance. {npc:248362}, inside, is elite: grouping up is advised."] = "她站在礦坑入口外。裡面的{npc:248362}是精英：建議組隊。",
		["Shiny Red Apples, from {npc:894}, for the {quest:91736}"] = "新鮮的紅蘋果，向{npc:894}取得，用於{quest:91736}",
		["Sit (/sit) by his campfire until you have {spell:1229451}"] = "在他的營火旁坐下（/sit），直到獲得{spell:1229451}",
		["South down the road to the {area:64}."] = "沿著道路向南前往{area:64}。",
		["Subdue the voidwalker"] = "制服虛空行者",
		["The Defias camp"] = "迪菲亞營地",
		["The Fishing Traps sit along the west shore of the lake."] = "捕魚陷阱沿著湖的西岸分布。",
		["The bridge"] = "橋",
		["The camp is north-east of the bridge. Bundles of Wood lie around the camp and in the woods north of it."] = "營地在橋的東北方。一捆木柴散落在營地周圍及其北邊的樹林裡。",
		["The crates of grapes lie in the vineyards behind the Defias. {npc:103} waits by the cabin at the east end of the valley."] = "裝葡萄的箱子在迪菲亞後方的葡萄園裡。{npc:103}在山谷東端的小屋旁等候。",
		["The gnoll camps"] = "豺狼人營地",
		["The kobold camp"] = "狗頭人營地",
		["The lake shore"] = "湖岸",
		["The mine is south-west of the gnoll camps. {item:247816} lie near the entrance; Kobold Geomancers hold the tunnels."] = "礦坑在豺狼人營地西南方。{item:247816}在入口附近；狗頭人地卜師佔據隧道。",
		["The mine is west of the vineyards. Kobold Miners and Tunnelers fill both levels; {npc:248464}, a named kobold, holds the picture book in the lower tunnels. {npc:248464} is elite: grouping up is advised."] = "礦坑在葡萄園西邊。狗頭人礦工和狗頭人隧道工遍布上下兩層；有名字的狗頭人{npc:248464}拿著圖畫書，在下層隧道裡。{npc:248464}是精英：建議組隊。",
		["The murlocs on the east shore drop the kelp. Skinners: Gray Forest Wolves roam the woods between the lake and the {area:91}; Prowlers further east give pelts too."] = "東岸的魚人會掉落海藻。剝皮者：森林灰狼在湖與{area:91}之間的樹林遊蕩；更東邊的覓食的灰狼也能剝下毛皮。",
		["The vineyards and {npc:103}"] = "葡萄園與{npc:103}",
		["The {area:88}"] = "{area:88}",
		["The {area:91}"] = "{area:91}",
		["The {quest:91736}"] = "{quest:91736}",
		["Walk into the mine"] = "走進礦坑",
		["Walk through the mine"] = "穿過礦坑",
		["Wolves"] = "狼",
		["You start in front of the Abbey. {npc:823} stands at the foot of the steps, {npc:197} inside the hall, {npc:951} and {npc:247229} in the library to the right, {npc:196} outside the north-west corner."] = "你從修道院前開始。{npc:823}站在台階下，{npc:197}在大廳裡，{npc:951}和{npc:247229}在右側的圖書室，{npc:196}在修道院西北角外。",
		["Young Wolves and Timber Wolves roam the fields right around the Abbey."] = "幼狼和森林狼在修道院周圍的田野遊蕩。",
		["his kobold tracker shows the kobolds to click on the road to {area:87}"] = "他的狗頭人追蹤器會標出通往{area:87}路上可點擊的狗頭人",
		["talk to the trainer"] = "與訓練師交談",
		["{item:247824}, from the still"] = "{item:247824}，來自蒸餾器",
		["{item:286215}: Stonetusk Boars"] = "{item:286215}：石牙野豬",
		["{item:6785}: the {object:83763} in the Defias camp"] = "{item:6785}：迪菲亞營地裡的{object:83763}",
		["{npc:12423} kneels wounded by a tree on the west shore of {area:18}, among the Fishing Traps. Cast {spell:613} (Rank 2) on him, then {spell:1243}: Rank 1 of {spell:613} does not count. He walks off once both land and is back in about 3 minutes."] = "{npc:12423}受傷跪在{area:18}西岸的一棵樹旁，就在捕魚陷阱之間。對他施放{spell:613}（等級2），然後施放{spell:1243}：等級1的{spell:613}不算數。兩個法術都生效後他會離開，大約3分鐘後回來。",
		["{npc:1632}, beside {npc:6306}"] = "{npc:1632}，在{npc:6306}旁邊",
		["{npc:1922}: tame it with the {item:15908}"] = "{npc:1922}：用{item:15908}馴服牠",
		["{npc:198}, the mage trainer, inside the Abbey"] = "{npc:198}，法師訓練師，在修道院內",
		["{npc:2329}, in the Lion's Pride Inn"] = "{npc:2329}，在獅王之傲旅店裡",
		["{npc:248242} and {npc:248248} stand at the foot of the tower."] = "{npc:248242}和{npc:248248}站在塔底。",
		["{npc:248415}, by the Abbey"] = "{npc:248415}，在修道院旁",
		["{npc:251507} stands with the {area:87} trainers. Each of her quests hands you a {item:15908}: use it on the beast she names, then bring the rod back to her. Rockhide Boars and Young Forest Bears roam the hills south of the {area:64}, Gray Forest Wolves the woods east of {area:18}."] = "{npc:251507}和{area:87}的訓練師們站在一起。她的每個任務都會給你一根{item:15908}：對她指定的野獸使用，然後把馴獸棒帶回給她。石皮野豬和小森林熊在{area:64}南邊的山丘遊蕩，森林灰狼在{area:18}東邊的樹林裡。",
		["{npc:253}, back in the inn"] = "{npc:253}，回到旅店裡",
		["{npc:258930}, beside her: {spell:5149}"] = "{npc:258930}，在她旁邊：{spell:5149}",
		["{npc:261} guards the bridge on the road east; {npc:248265} stands just across it."] = "{npc:261}守衛東邊道路上的橋；{npc:248265}就站在橋的另一頭。",
		["{npc:263399} camps north-east of the inn. With a profession learned, he also offers its Camping 101, which its trainer takes: skinning, leatherworking and fishing on the lake shore, {skill:129} and blacksmithing in {area:87}."] = "{npc:263399}在旅店東北方紮營。學會專業技能後，他也會提供該專業的「露營入門」，由該專業的訓練師接收：剝皮、製皮和釣魚在湖岸邊，{skill:129}和鍛造在{area:87}。",
		["{npc:263399}: for {npc:1632} on the lake shore"] = "{npc:263399}：給湖岸邊的{npc:1632}",
		["{npc:263399}: for {npc:1651} on the lake shore"] = "{npc:263399}：給湖岸邊的{npc:1651}",
		["{npc:263399}: for {npc:2329} in the Lion's Pride Inn"] = "{npc:263399}：給獅王之傲旅店裡的{npc:2329}",
		["{npc:263399}: for {npc:514} at the {area:87} smithy"] = "{npc:263399}：給{area:87}鐵匠鋪的{npc:514}",
		["{npc:263399}: for {npc:6306} on the lake shore"] = "{npc:263399}：給湖岸邊的{npc:6306}",
		["{npc:279} in {zone:1453} takes it (02-westfall)"] = "{zone:1453}的{npc:279}接收此任務（02-westfall）",
		["{npc:328}: {npc:5497} in {zone:1453} takes it"] = "{npc:328}：由{zone:1453}的{npc:5497}接收",
		["{npc:375}, the priest trainer"] = "{npc:375}，牧師訓練師",
		["{npc:375}, the priest trainer: {npc:377} in {area:87} takes it"] = "{npc:375}，牧師訓練師：由{area:87}的{npc:377}接收",
		["{npc:377}, upstairs"] = "{npc:377}，在樓上",
		["{npc:377}, upstairs: {item:16605}"] = "{npc:377}，在樓上：{item:16605}",
		["{npc:377}: heal {npc:12423} at {area:18}"] = "{npc:377}：在{area:18}治療{npc:12423}",
		["{npc:459}, outside the Abbey"] = "{npc:459}，在修道院外",
		["{npc:514}, at the smithy across the road"] = "{npc:514}，在路對面的鐵匠鋪",
		["{npc:514}, at the smithy beside Dughan: {npc:1416} in {zone:1453} takes it (02-westfall)"] = "{npc:514}，在杜漢旁邊的鐵匠鋪：由{zone:1453}的{npc:1416}接收（02-westfall）",
		["{npc:524}: tame it with the {item:15908}"] = "{npc:524}：用{item:15908}馴服牠",
		["{npc:6121}: {npc:6122} in {zone:1453} takes it"] = "{npc:6121}：由{zone:1453}的{npc:6122}接收",
		["{npc:6306}, on the lake shore east of town; inside"] = "{npc:6306}，在鎮東的湖岸邊；在室內",
		["{npc:6306}, {npc:383} and {npc:1651} stand on the shore of {area:18} east of town."] = "{npc:6306}、{npc:383}和{npc:1651}站在鎮東{area:18}的岸邊。",
		["{npc:6774}, by the stables south of the Abbey"] = "{npc:6774}，在修道院南邊的馬廄旁",
		["{npc:6} dig in the vineyards north-east of the Abbey. Now and then one drops a {quest:91741}: right-click it."] = "{npc:6}在修道院東北方的葡萄園挖掘。偶爾會掉落{quest:91741}：右鍵點擊它。",
		["{npc:822}: tame it with the {item:15908}"] = "{npc:822}：用{item:15908}馴服牠",
		["{npc:823}, back at the Abbey steps"] = "{npc:823}，回到修道院台階",
		["{npc:915}, the rogue trainer"] = "{npc:915}，盜賊訓練師",
		["{npc:925}, the paladin trainer"] = "{npc:925}，聖騎士訓練師",
		["{npc:952}, upstairs"] = "{npc:952}，在樓上",
		["{npc:963}: for {npc:234} at {area:108}"] = "{npc:963}：給{area:108}的{npc:234}",
		["{quest:76}'s entrance"] = "{quest:76}入口",
		["{quest:87} is inside the {area:57}, not on the hill above it: go in at the mouth and keep left to the back of the mine floor; don't take the stairs up. Defias Bandits around the vineyards drop a {item:1972} now and then: right-click it."] = "{quest:87}在{area:57}裡面，不在上方的山丘上：從入口進去，靠左走到礦坑底層的最深處；不要走樓梯上去。葡萄園周圍的迪菲亞強盜偶爾會掉落{item:1972}：右鍵點擊它。",
		["{quest:91733} and {npc:330}"] = "{quest:91733}與{npc:330}",
} end)()
t.guides["forever/alliance/nightelf/01-teldrassil"] = (function() return {
		["/sit by {npc:265811}'s campfire until you get {spell:1229451}"] = "在{npc:265811}的營火旁/sit，直到獲得{spell:1229451}",
		["Back at {area:256}"] = "回到{area:256}",
		["Back to the moonwell."] = "回到月井。",
		["Back to the top of {area:256}. The {object:654846} lies beside him."] = "回到{area:256}頂端。{object:654846}就在他旁邊。",
		["Back upstairs to {npc:3567} with the webwoods done and {npc:272116}'s moss."] = "完成蜘蛛任務並帶著{npc:272116}的苔蘚，回到樓上找{npc:3567}。",
		["Befouled Webwoods"] = "被污染的樹林蜘蛛",
		["Below ground"] = "地下",
		["Bloodfeather harpies"] = "血羽鷹身人",
		["Each of Dazalar's quests hands you a {item:15908}: use it on the beast he names, then bring the rod back to him in {area:186}. Webwood Lurkers creep around the village, Nightsaber Stalkers and Strigid Screechers roam the woods south of it."] = "達札拉的每個任務都會給你一根{item:15908}：對他指定的野獸使用，然後把馴獸棒帶回{area:186}給他。樹林潛伏者在村莊周圍潛行，夜刃捕食者和巨翼惡梟在村莊南邊的樹林遊蕩。",
		["Escort {npc:275744} out of the barrow; {npc:2081} in {area:186} takes the report."] = "護送{npc:275744}離開古墓；由{area:186}的{npc:2081}接收報告。",
		["Fandral in {zone:1457} takes it"] = "由{zone:1457}的范達爾接收",
		["Follow the road south-west out of {area:188}. {npc:2150} sits beside it just east of {area:186}."] = "沿著道路向西南離開{area:188}。{npc:2150}就坐在路旁，在{area:186}東邊不遠處。",
		["Gnarlpine Ambushers hide along the road west of {area:258}."] = "瘤背伏擊者埋伏在{area:258}西邊的道路沿線。",
		["Gnarlpine Shamans"] = "瘤背薩滿",
		["Go back down to {area:702} and fly to {area:442}. The {object:177525} stands in the hills just east of the village: use the {item:15208} there, defeat Lunaclaw and speak to the {npc:12144}."] = "回到{area:702}，飛往{area:442}。{object:177525}在村莊東邊的山丘上：在那裡使用{item:15208}，擊敗月爪梟獸，然後與{npc:12144}交談。",
		["Heal and fortify {npc:12429}"] = "治療{npc:12429}並施放耐力",
		["Leave {area:188} by the path south-east of {area:256}: {npc:6780} stands beside it, where it goes down towards the road to {area:186}."] = "從{area:256}東南方的小路離開{area:188}：{npc:6780}站在路旁，就在小路往下通往{area:186}道路的地方。",
		["Nightsabers"] = "夜刃豹",
		["North to {area:257}"] = "向北前往{area:257}",
		["North-east from Ursal's den, back to {area:186}."] = "從大槌烏薩爾的巢穴向東北走，回到{area:186}。",
		["North-west of Dolanaar, on the way to the {area:264}, Befouled Webwoods creep through the woods; {npc:272116} prowls at their east edge and carries the {item:281023}.\n{npc:272116} is elite (level 12): grouping up is advised. Clear the webwoods around him first and pull him on his own."] = "在多蘭納爾西北方、前往{area:264}的路上，被污染的樹林蜘蛛在樹林裡爬行；{npc:272116}在牠們的東緣徘徊，身上帶著{item:281023}。\n{npc:272116}是精英怪（12級）：建議組隊。先清掉他周圍的蜘蛛，再單獨把他拉出來。",
		["Sentinel Arynia again"] = "再次找哨兵阿瑞尼亞",
		["South from the glade toward Ursal: Shayla walks the road west of {area:186}, from where the path down from the glade meets it south-west to the bend at about 38,54 and back."] = "從林地向南朝大槌烏薩爾前進：夏伊拉在{area:186}西邊的道路上來回巡邏，從林地下來的小路與道路交會處往西南走到約38,54的彎道再折返。",
		["South-east of Dolanaar, to {npc:2080}. Lasher Sproutlings wander around him on the shore."] = "從多蘭納爾向東南前往{npc:2080}那裡。鞭笞者幼苗在岸邊他的周圍遊蕩。",
		["South-west of the barrow. The moonwell sits by the pools."] = "在古墓西南方。月井就在池塘旁。",
		["Speak with the {quest:5929}"] = "與{quest:5929}交談",
		["Take the road north-west from {area:186} again; she still lies beside it, on the way to {zone:1457}."] = "再次沿著道路從{area:186}向西北走；她仍躺在路旁，在前往{zone:1457}的路上。",
		["The WANTED poster outside the inn"] = "旅店外的通緝海報",
		["The moonwell"] = "月井",
		["The moonwell is in the middle of the glade. The {object:6752} grows at its north end."] = "月井在林地中央。{object:6752}生長在林地北端。",
		["The named harpies"] = "有名字的鷹身人",
		["The road to {zone:1457}"] = "前往{zone:1457}的道路",
		["The {area:478}"] = "{area:478}",
		["The {object:177525}"] = "{object:177525}",
		["The {object:4406} lie at the back of {area:257}: take the central path, then left where it splits, up to the high ledge. Hyacinth Mushrooms drop from Grells, Moonpetal Lilies grow by the ponds north of {area:256}."] = "{object:4406}在{area:257}深處：走中間的路，分岔處往左，一路上到高處的岩架。紫藍色蘑菇由小劣魔掉落，月牙百合花生長在{area:256}北邊的池塘旁。",
		["Tide Crawlers scuttle along the shore below the village; {quest:983} stands on the beach just south of the docks. Darkshore Threshers swim in the shallows. The {object:175207} lies on the shore just south of the village."] = "潮行蟹在村子下方的海岸爬行；{quest:983}站在碼頭南邊不遠的海灘上。黑海岸蛇頸龍在淺水中游動。{object:175207}在村子南邊不遠的岸上。",
		["Upstairs"] = "樓上",
		["Use the {item:18152} at the moonwell"] = "在月井使用{item:18152}",
		["Use the {item:5185} at the moonwell"] = "在月井使用{item:5185}",
		["Use the {item:5619} at the moonwell"] = "在月井使用{item:5619}",
		["Use the {item:5621} at the moonwell"] = "在月井使用{item:5621}",
		["Walk Lynessa out and keep her alive"] = "護送哨兵離開，並保住她的性命",
		["Webwood Lurkers"] = "樹林潛伏者",
		["West along the road toward the city. Shayla walks this stretch of road, from the arrow south-west to the bend at about 38,54 and back: if she isn't at the arrow, follow the road south-west. Every Gnarlpine furbolg drops fangs: the ambushers on this road, the barrow's and {area:261}'s all count."] = "沿著道路向西朝城市前進。夏伊拉在這段路上來回巡邏，從箭頭處往西南走到約38,54的彎道再折返：如果她不在箭頭處，沿著道路往西南走。每個瘤背熊怪都會掉落牙齒：這條路上的伏擊者、古墓裡的以及{area:261}的都算數。",
		["West from the webwoods to the {area:265}, then north along it to the glade: the timberlings along its banks drop the Mossy Tumors."] = "從蜘蛛所在的樹林向西前往{area:265}，然後沿著河向北走到林地：河岸邊的林精會掉落苔蘚腫瘤。",
		["With a profession learned, {npc:265811} also offers its Camping 101, which its trainer takes: alchemy and herbalism beside {npc:6286}, {skill:129} with {npc:6094} in the inn, skinning and leatherworking at the Maneweavers' camp on the road west."] = "學會一項專業技能後，{npc:265811}還會提供該專業的露營入門，由該專業的訓練師接收：煉金術和草藥學在{npc:6286}旁邊，{skill:129}找旅店裡的{npc:6094}，剝皮和製皮在往西道路上的鬃紡家族營地。",
		["You start at the foot of {area:256}, the great tree of {area:188}."] = "你從{area:188}的巨樹{area:256}底下開始。",
		["Young Nightsabers and Young Thistle Boars roam around {area:256}. Grells carry {item:3297} in the woods west of the tree, where the Gnarlpine Totems stand."] = "小夜刃豹和小草刺野豬在{area:256}周圍遊蕩。小劣魔帶著{item:3297}，在樹西邊瘤背圖騰矗立的樹林裡。",
		["talk to the trainer"] = "與訓練師交談",
		["{area:186} again"] = "再次回到{area:186}",
		["{area:258}'s mouth"] = "{area:258}入口",
		["{area:736}, outside the barrow"] = "{area:736}，在古墓外",
		["{item:159} from {npc:6736}, for {npc:6094}"] = "向{npc:6736}購買{item:159}，給{npc:6094}",
		["{item:3371} from {npc:3614}, beside {npc:6094}"] = "向{npc:6094}旁邊的{npc:3614}購買{item:3371}",
		["{npc:11401}, in the Temple of the Moon: Starshards"] = "{npc:11401}，在月神殿裡：星辰碎片",
		["{npc:12429} kneels wounded on the rocks at the north edge of {area:259}, on the walk back to {area:186}, with no quest mark over her. Cast {spell:613} (Rank 2) on her, then {spell:1243}: Rank 1 of {spell:613} does not count. She runs off once both land and is back in about 5 minutes."] = "{npc:12429}受傷跪在{area:259}北緣的岩石上，就在走回{area:186}的路上，她頭上沒有任務標記。對她施放{spell:613}（等級2），然後施放{spell:1243}：等級1的{spell:613}不算數。兩個法術都生效後她就會跑開，約5分鐘後回來。",
		["{npc:1992}, south of the tree"] = "{npc:1992}，在樹的南邊",
		["{npc:1996}: tame it with the {item:15908}"] = "{npc:1996}：用{item:15908}馴服牠",
		["{npc:1998}: tame it with the {item:15908}"] = "{npc:1998}：用{item:15908}馴服牠",
		["{npc:2038} waits inside the cave, at the bottom or up on the ledge; keep to the right."] = "{npc:2038}在洞穴裡等候，在底部或上方的岩架上；靠右走。",
		["{npc:2043}: tame it with the {item:15908}"] = "{npc:2043}：用{item:15908}馴服牠",
		["{npc:2077}, by the path"] = "{npc:2077}，在小路旁",
		["{npc:2079}: a sigil for {npc:3596}"] = "{npc:2079}：給{npc:3596}的印記",
		["{npc:2080}: {quest:922} in {zone:1457} takes it"] = "{npc:2080}：由{zone:1457}的{quest:922}接收",
		["{npc:2082}, on the tree's ramp"] = "{npc:2082}，在樹的坡道上",
		["{npc:2151} patrols the road west of the village: if she isn't at the arrow, follow the road until you meet her."] = "{npc:2151}在村莊西邊的道路上巡邏：如果她不在箭頭處，沿著道路走直到遇見她。",
		["{npc:2151}, on the road west of the village"] = "{npc:2151}，在村莊西邊的路上",
