t.guides["forever/alliance/nightelf/02-darkshore"] = (function() return {
		["Back north-east into the mountains to the crystal."] = "向東北回到山中的水晶那裡。",
		["Bears and the Blackwood camp"] = "熊與黑木營地",
		["Blackwood Pathfinders and Windtalkers hold the camp south-east of {area:442}."] = "黑木探路者和黑木風語者佔據{area:442}東南方的營地。",
		["Blackwood furbolgs"] = "黑木熊怪",
		["Class trainer"] = "職業訓練師",
		["Climb the eastern mountains east of {area:447}; the {object:175524} sits on a ledge."] = "爬上{area:447}東邊的山脈；{object:175524}在一處岩架上。",
		["Fill the tube at the moonwell in the village"] = "在村子的月井裝滿試管",
		["Follow the coast south past {area:447}: one {quest:4728} lies on the shore west of the Grove, another further south near {area:450}. Three more remains lie further south-west among Greymist Oracles and Tidehunters (18-20): the guide leaves them for the last loop, when you are closer to their level."] = "沿海岸向南經過{area:447}：一個{quest:4728}在古樹之林西邊的岸上，另一個在更南邊的{area:450}附近。更西南方的灰霧智者和灰霧潮行者（18-20級）之間還有三具骨骸：指南把它們留到最後一輪，那時你的等級更接近牠們。",
		["Grell Earrings"] = "劣魔耳環",
		["Highborne Relics"] = "精靈貴族的聖物",
		["Read the {object:17188}"] = "閱讀{object:17188}",
		["Read the {object:17189}"] = "閱讀{object:17189}",
		["The WANTED poster outside the inn"] = "旅店外的通緝海報",
		["The beach"] = "海灘",
		["The boat docks west of the village. The flight master stands on the hill south of the inn; the quest givers are spread along the main street."] = "船停靠在村子西邊。飛行管理員站在旅店南邊的山丘上；任務給予者分布在主街沿線。",
		["The red crystal"] = "紅色水晶",
		["The skeletal turtle"] = "海龜骨骸",
		["The southern beaches"] = "南部海灘",
		["Tide Crawlers scuttle along the shore below the village; {quest:983} stands on the beach just south of the docks. Darkshore Threshers swim in the shallows. The {object:175207} lies on the shore just south of the village."] = "潮行蟹在村子下方的海岸爬行；{quest:983}站在碼頭南邊不遠的海灘上。黑海岸蛇頸龍在淺水中游動。{object:175207}在村子南邊不遠的岸上。",
		["{item:5338}: Deth'ryll Satyrs"] = "{item:5338}：戴瑟雷薩特",
		["{npc:3639} stands at the north edge of the ruins. Cursed, Writhing and {npc:2178} haunt them; {npc:3667}'s ghost walks among them, {npc:270196} the owl circles east of them. The two tablets lie in the ruins; a {quest:4722} lies on the shore west of them."] = "{npc:3639}站在廢墟北緣。被詛咒的精靈貴族、悲苦的精靈貴族和{npc:2178}在廢墟中出沒；{npc:3667}的鬼魂在它們之間走動，貓頭鷹{npc:270196}在它們東邊盤旋。兩塊石板在廢墟中；一個{quest:4722}在廢墟西邊的岸上。",
		["{npc:3649}, north end of the village"] = "{npc:3649}，在村子北端",
} end)()
t.guides["forever/alliance/skyborne/01-zephras-isle"] = (function() return {
		["/sit by {npc:263664}'s campfire until you get {spell:1229451}"] = "在{npc:263664}的營火旁 /sit，直到獲得{spell:1229451}",
		["Al'Aketh Stormchasers and Footsoldiers camp just north of {npc:257944} and drop the heirloom; the Shrieklings west of her drop the feathers and talons; the {item:265105} grows along the stream west of her."] = "奧拉凱斯追風者和步行兵就在{npc:257944}北邊紮營，會掉落傳家寶；她西邊的始祖鳥會掉落羽毛和利爪；{item:265105}沿著她西邊的溪流生長。",
		["Back in {quest:92529}: Stormcallers and {npc:251662} fill the village, the Stormcallers carry the stolen supplies, and {npc:251966} stands at its south end."] = "回到{quest:92529}：奧拉凱斯風暴召喚者和{npc:251662}遍布村中，風暴召喚者身上帶著被偷的補給品，{npc:251966}站在村子南端。",
		["Back to the Hermit"] = "返回隱士處",
		["Back to {area:16622}"] = "返回{area:16622}",
		["Bandit Highwaymen"] = "強盜路霸",
		["Below ground"] = "地下",
		["Bolvar Fordragon stands in the throne room of {object:2117}, at the north end of the city. Then leave by the main gate for {zone:1436}."] = "伯瓦爾·弗塔根公爵站在城市北端{object:2117}的王座廳裡。然後從正門離開，前往{zone:1436}。",
		["Cast {spell:1259705} at the {object:460002}"] = "對{object:460002}施放{spell:1259705}",
		["Class trainer"] = "職業訓練師",
		["Desperate times"] = "危急時刻",
		["Fight north to the {area:16629}. Guardians, Spiritcallers and Blademasters hold the approach; {npc:253576} waits at the shrine's door, {npc:253590} inside the inner sanctum."] = "一路向北殺到{area:16629}。奧拉凱斯守護者、招魂師和大劍師守著通道；{npc:253576}在聖殿門口等候，{npc:253590}在內殿裡。",
		["Find {npc:258130}"] = "找到{npc:258130}",
		["Follow the road south to {area:16624}. {npc:263664} camps by the fire west of the village; {npc:251523} and {npc:251903} stand in its middle."] = "沿著道路向南前往{area:16624}。{npc:263664}在村子西邊的火堆旁紮營；{npc:251523}和{npc:251903}站在村子中央。",
		["For {npc:234} at {area:108}"] = "交給{area:108}的{npc:234}",
		["Head north into {area:16631}. {npc:257944} camps in its east."] = "向北進入{area:16631}。{npc:257944}在森林東部紮營。",
		["Heal the injured druids in the Nightfang Den"] = "在Nightfang Den治療受傷的德魯伊",
		["Leave {zone:1453} by the main gate. The {quest:1861} waterfall is south-west of the gates, on the way west to {zone:1436}: fill {item:7207} at its base."] = "從正門離開{zone:1453}。{quest:1861}瀑布在城門西南方，位於向西前往{zone:1436}的路上：在瀑布底下裝滿{item:7207}。",
		["Level 4 spells"] = "4級法術",
