		["The skyboat leaves the cliffs south of {area:17045}, north of {zone:1456} (another flies from {area:279})."] = "天空船從{zone:1456}北邊、{area:17045}南側的懸崖出發（另一艘從{area:279}起飛）。",
		["The skyboat leaves the north side of {area:279} in the {zone:1416} (another flies from north of {zone:1456})."] = "天空船從{zone:1416}的{area:279}北側出發（另一艘從{zone:1456}北邊起飛）。",
		["any one of these names counts"] = "以下任一名稱皆算",
} end)()
t.guides["forever/horde/02-the-barrens"] = (function() return {
		["Assist {npc:261366}: stay by him when {npc:261367} and the {area:21} marines come up the ridge"] = "協助{npc:261366}：{npc:261367}和{area:21}水兵爬上山脊時，待在他身邊",
		["At the {area:2362}"] = "在{area:2362}",
		["Back to the Razormane camp. Geomancers and Defenders hold its eastern half; {npc:3438} walks among them."] = "回到鋼鬃營地。鋼鬃地卜師和鋼鬃防禦者佔據營地東半部；{npc:3438}在他們之間走動。",
		["Bristleback camps"] = "刺背營地",
		["Burning Blade Cultists hold {area:1898} in northern {zone:1411}; they drop the {item:6652}. The {item:5026} comes from the Razormane on your next visit to their camp."] = "火刃祭司佔據{zone:1411}北部的{area:1898}；他們會掉落{item:6652}。{item:5026}在你下次去鋼鬃營地時從鋼鬃野豬人身上取得。",
		["Dogran is chained up in the quilboar camp west of the road."] = "步兵多格蘭被鎖在道路西邊的野豬人營地裡。",
		["Down the {area:458} to {area:378} again."] = "再次沿{area:458}往南前往{area:378}。",
		["Fill the {item:7766} at the quilboar watering hole"] = "在野豬人的水源裝滿{item:7766}",
		["Fly to {area:1637}"] = "飛往{area:1637}",
		["Fly to {area:1638} to train: {npc:3033} is on {area:1639}."] = "飛往{area:1638}訓練：{npc:3033}在{area:1639}。",
		["Fly to {area:392}"] = "飛往{area:392}",
		["Follow the road east to the outpost above the {area:814}."] = "沿道路向東前往{area:814}上方的哨站。",
		["Follow the road south-east to {area:392} on the coast."] = "沿道路向東南前往海岸的{area:392}。",
		["Follow the {area:458} south to {area:378}."] = "沿{area:458}向南前往{area:378}。",
		["Grimtotem camp"] = "恐怖圖騰營地",
		["He gives you the {item:15826}"] = "他會給你{item:15826}",
		["He offers {quest:1838} next (1838, level 30): it needs {area:1717} and sends you all over Kalimdor and the Eastern Kingdoms. The Warrior class guide {quest:1838} covers it."] = "他接著提供{quest:1838}（1838，30級）：需要{area:1717}，並會讓你跑遍卡林多和東部王國。戰士職業指南{quest:1838}涵蓋此任務。",
		["Keep it: {npc:12696} in {zone:1440}, next guide"] = "先留著：下一份指南中{zone:1440}的{npc:12696}",
		["North to the {area:383}. {npc:3682} camps below the hills; {npc:261366}, the hermit on the ridge behind him, has work for you only once {npc:3682} sends you up."] = "向北前往{area:383}。{npc:3682}在丘陵下紮營；他身後山脊上的隱士{npc:261366}，要等{npc:3682}派你上去後才會有工作給你。",
		["North up the {area:458} to the Crossroads: {npc:3448} at the south gate, {npc:3432} by the inn, {npc:3428} west of the north gate. Keep the {item:5075}: {npc:3430} takes it on the next stop in {area:378}."] = "沿{area:458}向北前往十字路口：{npc:3448}在南門，{npc:3432}在旅店旁，{npc:3428}在北門西邊。先留著{item:5075}：下次到{area:378}時交給{npc:3430}。",
		["On the way back down the {area:1076}, {npc:11856} is held in {npc:11858}'s hut at the bend in the road. Once you take her quest she walks straight off south-east to {area:2538}, the burned village, without waiting: stay close, or the quest fails.\nCareful: Three Grimtotems ambush her at the burned village and go for her, not you: pull them off her and kill their caster quickly."] = "沿{area:1076}往回下山時，{npc:11856}被關在道路轉彎處{npc:11858}的小屋裡。接下她的任務後，她會直接往東南走向被燒毀的村莊{area:2538}，不會等你：緊跟著她，否則任務會失敗。\n小心：三個恐怖圖騰成員會在被燒毀的村莊伏擊她，並且攻擊她而不是你：把他們從她身上拉開，並迅速擊殺他們的施法者。",
		["Over the {area:814} bridge below {area:379} and south along the {zone:1411} bank to where a narrow trail climbs the mountain: {npc:5900} keeps the shrine at the top. Mind the edges on the way up, and come back down the same trail."] = "經過{area:379}下方的{area:814}橋，沿{zone:1411}岸邊往南走，直到一條窄路爬上山：{npc:5900}看守山頂的神殿。上山時小心邊緣，並沿同一條路下山。",
		["Raptor nests"] = "迅猛龍巢",
		["Razormane camp"] = "鋼鬃營地",
		["South-east of the Crossroads. Test the seeds at the bubbling fissure on the oasis' east bank; {npc:3448} takes the result on the next Crossroads stop, so carry on north-west to the {area:383} from here."] = "在十字路口東南方。在綠洲東岸冒泡的裂縫測試種子；{npc:3448}會在下次回到十字路口時收下結果，所以從這裡繼續往西北前往{area:383}。",
		["South-west from {area:392} across the plains to the {area:1697}: the three nests sit together south-west of the oasis, and Sunscale Scytheclaws guard them. Each nest needs a {item:5165}: kill Sunscale raptors (most drop one) until you have three, then use a feather at each nest."] = "從{area:392}往西南穿過平原前往{area:1697}：三個巢一起位於綠洲西南方，由赤鱗鐮爪龍守護。每個巢都需要一根{item:5165}：擊殺赤鱗迅猛龍（大多會掉落一根）直到你有三根，然後在每個巢使用一根羽毛。",
		["Tauren: the {npc:11957} waits on the southern hill above the bridge. Skyborne: the {npc:272054} stands south of the twin bridges. Then the dens east of the lake: leave your form, click the statue at the entrance for five minutes of stealth, keep clear of the spirits inside and take one of each relic; the {item:280680} lies at the foot of the white cat statue."] = "牛頭人：{npc:11957}在橋上方的南邊山丘等著。天裔精靈：{npc:272054}站在雙橋南邊。然後前往湖東邊的獸穴：解除變形，點擊入口的雕像獲得五分鐘的潛行，避開裡面的靈魂，每種聖物各拿一個；{item:280680}在白貓雕像的腳下。",
		["The Venture Co. Overseers and Enforcers at the mine in the north-east corner of the zone drop the {item:5097}."] = "地區東北角礦坑的風險投資公司監工和風險投資公司執行者會掉落{item:5097}。",
		["The road climbs north as the {area:1076}. {quest:1483} has a hut where the road forks east to {area:461}."] = "道路以{area:1076}向北爬升。{quest:1483}的小屋在道路向東分岔通往{area:461}的地方。",
		["The {area:2363}"] = "{area:2363}",
		["The {object:172960} is the canyon under the {object:172982}."] = "{object:172960}是{object:172982}下方的峽谷。",
		["The {object:177792} lies at the north edge of the {area:382}, by the Venture Co. tower. It holds the {item:15883} for {quest:30}."] = "{object:177792}在{area:382}北緣，風險投資公司的塔旁。裡面有{quest:30}所需的{item:15883}。",
		["Thunder Lizards and Lightning Hides graze just across the bridge below {area:379}."] = "雷霆蜥蜴和閃電蜥蜴就在{area:379}下方的橋對面吃草。",
		["Thunder lizards across the river"] = "河對岸的雷霆蜥蜴",
		["Thunderhawk Cloudscrapers circle over the same plains south of the camp."] = "雷鷹破雲者在營地南邊同一片平原上空盤旋。",
		["Thunderheads graze on the plains just south of {area:378}. {quest:884}, a blue thunder lizard, roams among them: his Tailspike starts a quest."] = "電角蜥蜴在{area:378}南邊不遠的平原吃草。藍色雷霆蜥蜴{quest:884}在牠們之間遊蕩：牠的尾刺會開啟任務。",
		["Twitching Antennae"] = "抽動的觸鬚",
		["Twitching Antennae from the silithid"] = "從異種蠍身上取得顫抖的觸角",
		["Upstairs"] = "樓上",
		["West from the burned village to {area:2539}: {npc:12816} stands just outside it, before the village."] = "從被燒毀的村莊往西前往{area:2539}：{npc:12816}就站在村外，在進村之前。",
		["{area:1898} cultists"] = "{area:1898}的祭司",
		["{item:15877}, from a {object:177785} in the lake"] = "{item:15877}，從湖中的{object:177785}取得",
		["{item:2449} from {npc:3490}; herbalists pick it on the plains"] = "向{npc:3490}購買{item:2449}；草藥學家可在平原上採集",
		["{npc:11798} in {area:2361} flies druids there"] = "{area:2361}的{npc:11798}會載德魯伊飛到那裡",
		["{npc:11799}, at the {area:2362}"] = "{npc:11799}，在{area:2362}",
		["{npc:11802}: the welcome from {npc:3033}"] = "{npc:11802}：{npc:3033}的歡迎",
		["{npc:11856}, inside {npc:11858}'s hut"] = "{npc:11856}，在{npc:11858}的小屋裡",
		["{npc:11857}: keep it, {npc:11864} at {area:460} in the {zone:1413} & Stonetalon guide"] = "{npc:11857}：先留著，{zone:1413}與石爪山脈指南中{area:460}的{npc:11864}",
		["{npc:3391}, upstairs"] = "{npc:3391}，在樓上",
		["{npc:3395} walks among the Kolkar at the {area:388} south-east of the Crossroads. Oasis Snapjaws crawl in the water around it: their shells are for {npc:3448}."] = "{npc:3395}在十字路口東南方的{area:388}與科卡爾半人馬一起走動。綠洲鉗嘴龜在周圍的水中爬行：牠們的殼要交給{npc:3448}。",
		["{npc:3429}, at the top of the tower"] = "{npc:3429}，在塔頂",
		["{npc:3430}, in the cage"] = "{npc:3430}，在籠子裡",
		["{npc:3432} offers {quest:95774} once {quest:4921} is handed in"] = "繳交{quest:4921}後，{npc:3432}會提供{quest:95774}",
		["{npc:3442}: the console is in the {area:382}, later"] = "{npc:3442}：控制台之後在{area:382}",
		["{npc:3448}: the Oasis Snapjaws at the {area:388}, with {npc:3395}"] = "{npc:3448}：{area:388}的綠洲鉗嘴龜，以及{npc:3395}",
		["{npc:3449}: the harpies come later, in the {area:383}"] = "{npc:3449}：鷹身人之後在{area:383}",
		["{npc:3465} is chained inside the hold. Talk to him to start the escort and stay close: Theramore soldiers attack on the way out. He walks you back to {area:392}."] = "{npc:3465}被鎖在要塞內。和他交談開始護送並緊跟著他：出去的路上塞拉摩士兵會攻擊。他會和你一起走回{area:392}。",
		["{npc:4197} lives in {area:2539}, the troll village just inside Stonetalon at the end of the road west from {npc:3389}."] = "{npc:4197}住在{area:2539}，那是從{npc:3389}往西的道路盡頭、剛進入石爪山脈的食人妖村落。",
		["{npc:4201}: for {npc:3442}, beside {area:392}'s flight master at the end of the {zone:1413} & Stonetalon guide"] = "{npc:4201}：交給{npc:3442}，他在{area:392}的飛行管理員旁，於{zone:1413}與石爪山脈指南的最後",
		["{npc:5878} camps beside the road east toward {area:392}."] = "{npc:5878}在往東通往{area:392}的道路旁紮營。",
		["{npc:5900} makes {item:6636} from the tar and pouch. Use it by the brazier next to him to reveal the {npc:5893}, kill it for the {item:6655}, then place the ember in the brazier."] = "{npc:5900}用焦油和袋子製作{item:6636}。在他旁邊的火盆使用它以顯現{npc:5893}，擊殺它取得{item:6655}，然後把餘燼放進火盆。",
		["{npc:5901} waits on the hill south of {area:392}, on your way north."] = "{npc:5901}在{area:392}南邊的山丘上等著，就在你往北的路上。",
		["{npc:5907} stands on the ridge north of the Razormane camp."] = "{npc:5907}站在鋼鬃營地北邊的山脊上。",
		["{npc:5907}: {npc:2523}, your {item:5176} and the {item:263412}"] = "{npc:5907}：{npc:2523}、你的{item:5176}和{item:263412}",
		["{npc:5909}, a few steps away"] = "{npc:5909}，就在幾步之外",
		["{npc:6018} stands in the {object:172961} on the city's west side."] = "{npc:6018}站在城市西側的{object:172961}。",
		["{npc:6018} stands in the {object:172961}, on the city's west side."] = "{npc:6018}站在城市西側的{object:172961}。",
		["{npc:6018}: {npc:4606} in the {zone:1458}, two guides on"] = "{npc:6018}：兩份指南後{zone:1458}的{npc:4606}",
		["{object:3972} poster"] = "{object:3972}海報",
		["{quest:1492}, on the dock"] = "{quest:1492}，在碼頭上",
		["{quest:6127}: {area:384}, next guide"] = "{quest:6127}：{area:384}，下一份指南",
		["{zone:1454} class quests"] = "{zone:1454}的職業任務",
		["{zone:1454} flight master"] = "{zone:1454}的飛行管理員",
} end)()
t.guides["forever/horde/03-silverpine-forest"] = (function() return {
		["Class trainer"] = "職業訓練師",
		["Follow the road north-east to the Yoricks' house at {area:238}."] = "沿著道路向東北前往{area:238}的尤瑞克家。",
		["Follow the road south. The {object:1627} sits beside it, north of Pyrewood."] = "沿著道路向南走。{object:1627}在路旁，位於焚木村北邊。",
		["Mottled Worgs"] = "雜斑座狼",
		["Mottled Worgs prowl the hills around the house."] = "雜斑座狼在房子周圍的山丘徘徊。",
		["North again to the Yoricks' house."] = "再次向北前往尤瑞克家。",
		["North of the {area:228}. {npc:1983} haunts the {area:240}: kill it, then walk across the field."] = "在{area:228}北邊。{npc:1983}在{area:240}出沒：殺了它，然後走過整片田地。",
		["Speak with {npc:10181}, in the {object:36126}: {quest:93739}"] = "與{object:36126}的{npc:10181}交談：{quest:93739}",
		["Speak with {npc:10540}, in Grommash Hold"] = "與Grommash Hold裡的{npc:10540}交談",
		["Speak with {npc:3230}, in Grommash Hold"] = "與Grommash Hold裡的{npc:3230}交談",
		["Take the road north toward {zone:1420}: the Yoricks' house at {area:238} is on the way. {quest:425} lurks a short walk west of it."] = "沿道路向北朝{zone:1420}走：{area:238}的尤瑞克家就在路上。{quest:425}潛伏在房子西邊不遠處。",
		["The cattails and speargrass grow along the water in the {object:172958}, east of the Drag."] = "香蒲和長矛草沿著the Drag東邊{object:172958}的水邊生長。",
		["The {object:172960} is the canyon under the {object:172982}; {quest:829} stands at its far end."] = "{object:172960}是{object:172982}下方的峽谷；{quest:829}站在峽谷盡頭。",
		["Vile Fin murlocs"] = "邪鰭魚人",
		["Zeppelin to {zone:1454}"] = "搭飛艇前往{zone:1454}",
		["{area:228} is the Forsaken crypt-town in the middle of the forest. Everyone you need stands around the crypt entrance; {npc:2226}, the bat handler, is just east of it."] = "{area:228}是森林中央的被遺忘者墓穴城鎮。你需要找的人都站在墓穴入口周圍；蝙蝠管理員{npc:2226}就在入口東邊。",
		["{npc:11044}, in the Apothecarium"] = "{npc:11044}，在 Apothecarium",
		["{npc:11046}, the alchemy trainer, stands next door to {npc:3348}."] = "{npc:11046}是煉金術訓練師，站在{npc:3348}隔壁。",
		["{npc:11046}: Camping 101, from Brakk's campfire in {zone:1411}"] = "{npc:11046}：野營入門，來自{zone:1411}布拉克的營火",
		["{npc:11066}, the enchanting trainer, works in the Drag."] = "{npc:11066}是附魔訓練師，在the Drag工作。",
		["{npc:11066}: Camping 101, from Brakk's campfire in {zone:1411}"] = "{npc:11066}：野營入門，來自{zone:1411}布拉克的營火",
		["{npc:1937}: for Quinn, on the road north at the end"] = "{npc:1937}：為了奎恩，最後在北邊的路上",
		["{npc:1978} waits north-east of the house. Escort him back to {npc:1950}; worgs attack on the way."] = "{npc:1978}在房子東北方等候。護送他回到{npc:1950}那裡；途中會有座狼攻擊。",
		["{npc:2226}: {npc:4556} in the {zone:1458}, at the end of this guide; no need to buy the flight"] = "{npc:2226}：{zone:1458}的{npc:4556}，在本指南的最後；不需要購買飛行路線",
		["{npc:246152} trains Paladins in {area:159}, a short walk north up the road from the zeppelin towers. Come back down the same road for Silverpine."] = "{npc:246152}在{area:159}訓練聖騎士，從飛艇塔沿著道路往北走一小段就到。之後沿同一條路回來前往銀松森林。",
		["{npc:2855}, the tailoring trainer, is in the {object:172958}."] = "{npc:2855}是裁縫訓練師，在{object:172958}。",
		["{npc:2855}: Camping 101, from Brakk's campfire in {zone:1411}"] = "{npc:2855}：野營入門，來自{zone:1411}布拉克的營火",
		["{npc:3348} and {npc:3347} run the alchemy shop in the Drag; {npc:11046} is next door."] = "{npc:3348}和{npc:3347}在the Drag經營煉金店；{npc:11046}在隔壁。",
		["{npc:3365}, the leatherworking trainer, works in the {object:172958}."] = "{npc:3365}是製皮訓練師，在{object:172958}工作。",
		["{npc:3365}: Camping 101, from Brakk's campfire in {zone:1411}"] = "{npc:3365}：野營入門，來自{zone:1411}布拉克的營火",
		["{npc:3404}, the herbalism trainer, keeps her shop in the Drag."] = "{npc:3404}是草藥學訓練師，她的店在the Drag。",
		["{npc:3404}: Camping 101, from Brakk's campfire in {zone:1411}"] = "{npc:3404}：野營入門，來自{zone:1411}布拉克的營火",
		["{npc:4551}, the bat handler"] = "{npc:4551}，蝙蝠管理員",
		["{npc:4551}: keep {item:16210}, Podrig takes it on the next stop at the {area:228}, at 22"] = "{npc:4551}：保留{item:16210}，22級時在下一站{area:228}交給波崔格",
		["{npc:4556}, the weapon merchant beside the bat handler"] = "{npc:4556}，蝙蝠管理員旁邊的武器商人",
		["{npc:4586}, the engineering trainer, works in the {zone:1458}."] = "{npc:4586}是工程學訓練師，在{zone:1458}工作。",
		["{npc:4586}: Camping 101, from {npc:265812}'s campfire in Tirisfal"] = "{npc:4586}：野營入門，來自提里斯法{npc:265812}的營火",
		["{npc:4598}, the mining trainer, works in the {zone:1458}."] = "{npc:4598}是採礦訓練師，在{zone:1458}工作。",
		["{npc:4598}: Camping 101, from {npc:265812}'s campfire in Tirisfal"] = "{npc:4598}：野營入門，來自提里斯法{npc:265812}的營火",
		["{npc:4605}, the blacksmithing trainer, works in the {zone:1458}."] = "{npc:4605}是鍛造訓練師，在{zone:1458}工作。",
		["{npc:4605}: Camping 101, from {npc:265812}'s campfire in Tirisfal"] = "{npc:4605}：野營入門，來自提里斯法{npc:265812}的營火",
		["{npc:4949}, inside Grommash Hold"] = "{npc:4949}，在Grommash Hold裡",
		["{npc:4949}: {quest:93739}, a tour of the Horde's leaders"] = "{npc:4949}：{quest:93739}，拜訪部落各領袖",
		["{npc:7088}, the skinning trainer, stands in the {object:172958}."] = "{npc:7088}是剝皮訓練師，站在{object:172958}。",
		["{npc:7088}: Camping 101, from Brakk's campfire in {zone:1411}"] = "{npc:7088}：野營入門，來自{zone:1411}布拉克的營火",
		["{quest:264} is handed in at {object:24776}, a grave a few steps south of the crypt entrance, not to a person."] = "{quest:264}要在{object:24776}交，那是墓穴入口南邊幾步遠的一座墳墓，不是交給某個人。",
} end)()
t.guides["forever/horde/04-the-barrens"] = (function() return {
		["Bael'dun fortress"] = "巴爾丹要塞",
		["East along the road from {area:2539} to {npc:4049}'s camp, on the way to {area:378}."] = "從{area:2539}沿道路向東前往{npc:4049}的營地，就在前往{area:378}的路上。",
		["Fly to the Crossroads from the wind rider master: {npc:2995} on {zone:1456}'s central rise."] = "從雙足飛龍管理員飛往十字路口：{zone:1456}中央高台上的{npc:2995}。",
		["Fly to {area:1638}"] = "飛往{area:1638}",
		["Fly to {area:1638} first: two of its elders give quests worked on this guide's and the next guide's walks."] = "先飛往{area:1638}：那裡的兩位長者會給予在本指南和下一份指南路線中完成的任務。",
		["Fly to {area:378}"] = "飛往{area:378}",
		["Fly to {area:392}"] = "飛往{area:392}",
		["Follow the road north toward {area:467}. Antlered Coursers graze along the way; the Sap Beasts, Twilight Runners and Fey Dragons roam the woods below the Peak, and the Cenarion druids hold the grove there."] = "沿著道路向北前往{area:467}。巨角鹿在沿途覓食；腐蝕獸、夜行虎和靈龍在山峰下方的樹林中遊蕩，塞納里奧德魯伊則佔據那裡的樹林。",
		["Follow the road west past Regthar's bunkers and {npc:4049}'s camp into Stonetalon: {npc:3995} waits below ground in {area:2539}, at the foot of the {area:1076}."] = "沿道路向西經過雷戈薩的碉堡和{npc:4049}的營地進入石爪山脈：{npc:3995}在{area:2539}的地底下等著，位於{area:1076}腳下。",
		["Follow the road west past Regthar's bunkers: {npc:4049} camps beside it at the edge of Stonetalon."] = "沿道路向西經過雷戈薩的碉堡：{npc:4049}在石爪山脈邊緣的路旁紮營。",
		["From {area:2539} follow the road east to {npc:4049}'s camp, then south-east across the plains to {area:378}."] = "從{area:2539}沿道路向東前往{npc:4049}的營地，然後往東南穿過平原前往{area:378}。",
		["From {area:378} follow the road west through the gate into {zone:1412}, then north past {area:222} to {zone:1456}; a lift at the foot of the bluffs takes you up."] = "從{area:378}沿道路向西穿過大門進入{zone:1412}，然後往北經過{area:222}前往{zone:1456}；高崖腳下的升降梯會載你上去。",
		["Gaea Dirt Mounds"] = "蓋亞土堆",
		["Gaea Seeds"] = "蓋亞之種",
		["South-west of Sun Rock lies the burned {area:465}. Plant the Gaea Seeds in the dirt mounds on the valley floor; the fire elementals drop {item:16312}. Bloodfury Harpies and Ambushers nest on the north side, Slayers and Roguefeathers to the south."] = "烈日石居西南方是燒焦的{area:465}。把蓋亞之種種在谷底的土堆裡；火元素會掉落{item:16312}。血怒鷹身人和血怒伏擊者在北側築巢，血怒殺戮者和血怒遊蕩者在南側。",
		["The dwarves' flying machine sits on its platform inside the dig site. Use the {item:5021} that {npc:3341} gave you on it."] = "矮人的飛行器停在挖掘場內的平台上。對它使用{npc:3341}給你的{item:5021}。",
		["The flying machine"] = "飛行器",
		["The road west past {npc:4049}'s camp"] = "沿道路向西經過{npc:4049}的營地",
		["The {area:1718}"] = "{area:1718}",
		["The {object:667362} grows on the bottom of {area:464}, off the same southern shore: dive to the plants and the Dried Mirkweed Piles; both give pods. Watch your breath."] = "{object:667362}生長在{area:464}的湖底，就在同一片南岸外：潛到植物和乾燥的暗色草堆那裡；兩者都會給予豆莢。注意你的呼吸。",
		["To {zone:1456}"] = "前往{zone:1456}",
		["Up the {area:1076} past {npc:4201} and west to {area:460}; coming from {npc:4073}, back west past Ziz's hut."] = "沿{area:1076}上山經過{npc:4201}，再向西前往{area:460}；若從{npc:4073}那邊過來，就往西走回吉茲的小屋。",
		["Up the {area:1076} to {npc:4201}' hut, then east along the road toward {area:461}: {npc:4074} patrols the road just east of the fork, {npc:4073} the slopes further north-east below the crag. Both are lone shredder robots; they roam, so follow the road until you meet them."] = "沿{area:1076}上山到{npc:4201}的小屋，然後沿道路向東前往{area:461}：{npc:4074}在岔路口東邊不遠的道路上巡邏，{npc:4073}則在更東北方、山崖下方的山坡上。兩者都是落單的伐木機器人；牠們會四處移動，所以沿著道路走直到遇見牠們。",
		["{item:277936}, from any Bloodfury harpy"] = "{item:277936}，來自任何血怒鷹身人",
		["{npc:10079}, at the top of the lift"] = "{npc:10079}，在升降梯頂端",
		["{npc:11860}: Glittering Sunstones from the Bloodfury harpies"] = "{npc:11860}：從血怒鷹身人身上取得閃亮日長石",
		["{npc:11861}, beside {npc:11862}"] = "{npc:11861}，在{npc:11862}旁邊",
		["{npc:11862}, up on the ledge"] = "{npc:11862}，在上方的岩架上",
		["{npc:11864} stands by the bonfire inside Sun Rock: Makaba's news that Kaya is alive is for her."] = "{npc:11864}站在烈日石居內的營火旁：馬卡巴帶來的卡雅還活著的消息正是給她的。",
		["{npc:14242}, up in the tree just east of {npc:3341}"] = "{npc:14242}，在{npc:3341}東邊不遠的樹上",
		["{npc:2995}, the wind rider master, stands on the central rise: take his flight path if you don't have it. {npc:3024} and {npc:4721} stand a short walk east of him."] = "雙足飛龍管理員{npc:2995}站在中央高台上：如果還沒有他的飛行路線就先取得。{npc:3024}和{npc:4721}站在他東邊不遠處。",
		["{npc:3024}: the {object:667362} grows in {area:464}, by Sun Rock"] = "{npc:3024}：{object:667362}生長在烈日石居旁的{area:464}",
		["{npc:3429}, at the top of the tower"] = "{npc:3429}，在塔頂",
		["{npc:3430}, in the cage"] = "{npc:3430}，在籠子裡",
		["{npc:3433}, at the north edge of the camp"] = "{npc:3433}，在營地北緣",
		["{npc:3442} stands beside the flight master you land at."] = "{npc:3442}站在你降落處的飛行管理員旁邊。",
		["{npc:3442}: {quest:1094}, from {npc:4201}"] = "{npc:3442}：{quest:1094}，來自{npc:4201}",
		["{npc:4049}: {npc:4074} and {npc:4073} roam east of {npc:4201}, on the way up"] = "{npc:4049}：{npc:4074}和{npc:4073}在{npc:4201}東邊遊蕩，就在上山的路上",
		["{npc:4198}'s next quest, Ordanus, is on the Alliance side of {zone:1440}. Skip it."] = "{npc:4198}的下一個任務「奧達努斯」在{zone:1440}的聯盟那一側。跳過。",
		["{npc:4198}, outside the gate"] = "{npc:4198}，在大門外",
		["{npc:4721}: the phial comes from {zone:1440}, next guide"] = "{npc:4721}：藥瓶來自下一份指南的{zone:1440}",
		["{npc:5899}'s hut stands on the ridge above the quilboar watering hole, south of {area:378}, on the way to {area:359}."] = "{npc:5899}的小屋在{area:378}南邊、野豬人水坑上方的山脊上，在前往{area:359}的路上。",
		["{npc:5899}: the blue waterskin is filled in {zone:1440}, next guide"] = "{npc:5899}：藍色水袋在下一份指南的{zone:1440}裝滿",
		["{npc:5899}: the red waterskin from {area:272}"] = "{npc:5899}：來自{area:272}的紅色水袋",
		["{quest:873}, a big threshadon, swims in the shallows off the {area:391}, east of {npc:3388}."] = "{quest:873}是一隻巨大的長頸龍，在{area:391}外的淺水中游動，位於{npc:3388}東邊。",
		["{zone:1454} flight master"] = "{zone:1454}的飛行管理員",
		["{zone:1456} first: two of its elders give quests worked on this guide's and the next guide's walks. Fly to {area:378}; from there it is a walk west into {zone:1412} and north to the bluffs."] = "先去{zone:1456}：那裡的兩位長者會給予在本指南和下一份指南路線中完成的任務。飛往{area:378}；從那裡向西步行進入{zone:1412}，再往北走到高崖。",
		["{zone:1456}'s central rise"] = "{zone:1456}的中央高台",
} end)()
t.guides["forever/horde/05-stonetalon-mountains"] = (function() return {
		["Back on the road south. Where it turns east into {area:287}, {npc:2214} waits at {area:285}."] = "回到道路往南走。在道路轉向東進入{area:287}的地方，{npc:2214}在{area:285}等候。",
		["Below ground"] = "地下",
		["Down the road through Silverpine to the {area:228}: from the zeppelin towers, south through Tirisfal; from the {object:177790}, south-east from the coast to the road. {npc:2121} and {npc:1937} stand by the crypt entrance."] = "沿著道路穿過銀松森林前往{area:228}：從飛艇塔出發的話，往南穿過提里斯法；從{object:177790}出發的話，從海岸往東南走到道路上。{npc:2121}和{npc:1937}站在墓穴入口旁。",
		["Every Wrathtail naga along the strand north of the outpost drops heads."] = "前哨站北邊海岸上的每個怒尾納迦都會掉落頭顱。",
		["Fly to {area:1637}"] = "飛往{area:1637}",
		["From Seereth's camp head north-east across the {zone:1413} to the road north of the Crossroads; Rogues coming from Fizzule's tower head west to it. {npc:8582} stands on the watch tower of the {area:1703} where the road enters {zone:1440}."] = "從賽瑞斯的營地往東北穿過{zone:1413}，前往十字路口北邊的道路；從菲蘇勒的塔過來的盜賊則往西走到這條路。{npc:8582}站在道路進入{zone:1440}處的{area:1703}瞭望塔上。",
		["Naga brazier"] = "納迦火盆",
		["Naga heads"] = "納迦頭顱",
		["Steer {npc:267214}'s {npc:271181} out of the ravine to the main road within four minutes; if the channel breaks, ask {npc:267214} again."] = "在四分鐘內把{npc:267214}的{npc:271181}操控出峽谷到主要道路；如果引導中斷，再找{npc:267214}一次。",
		["Thistlefur Hold"] = "薊皮熊怪的巢穴",
		["{item:271343}, from a {npc:1973}"] = "{item:271343}，來自{npc:1973}",
		["{npc:2214}: Darthalia in {area:272}"] = "{npc:2214}：{area:272}的達薩利亞",
		["{npc:2391} in {area:272} teaches Poisons: keep it"] = "{area:272}的{npc:2391}教授毒藥：先留著",
		["{npc:246152} trains Paladins in {area:159}, a short walk north up the road from the zeppelin towers. Come back down the same road for Silverpine."] = "{npc:246152}在{area:159}訓練聖騎士，從飛艇塔沿著道路往北走一小段就到。之後沿同一條路回來前往銀松森林。",
		["{npc:271181}, on the road"] = "{npc:271181}，在道路上",
		["{npc:5875} stands in the {object:172960}. Use {item:6626} on the summoning circle there and defeat the succubus to bind her."] = "{npc:5875}站在{object:172960}。在那裡的召喚法陣使用{item:6626}，擊敗魅魔以束縛她。",
		["{npc:6389} stands just west of the crypt entrance: hand him {item:16210} from the {zone:1458}."] = "{npc:6389}站在墓穴入口西邊不遠處：把來自{zone:1458}的{item:16210}交給他。",
} end)()
t.guides["forever/horde/06-hillsbrad-foothills"] = (function() return {
		["Back to {area:272}"] = "返回{area:272}",
		["Bears, creepers and lions"] = "熊、食苔蛛和山地獅",
		["Drull and {npc:2238} are chained inside {area:275}'s courtyard buildings. Their locks need keys: {npc:2427} carries the {item:3467} and {npc:2428} the {item:3499}, both in the keep. Kill them, then open both locks.\nFrom {area:272} go south-east into the hills on the way to {area:275}. Rogues and Watchmen hold the camps along the way."] = "德盧爾和{npc:2238}被鎖在{area:275}庭院的建築裡。鎖需要鑰匙：{npc:2427}帶著{item:3467}，{npc:2428}帶著{item:3499}，兩人都在城堡裡。殺死他們，然後打開兩把鎖。\n從{area:272}向東南進入通往{area:275}途中的丘陵。辛迪加盜賊和辛迪加衛士佔據沿途的營地。",
		["Drull's ball and chain"] = "德盧爾的腳鐐",
		["Fill the {item:7768} at the {object:107045} beside the inn"] = "在旅店旁的{object:107045}裝滿{item:7768}",
		["Fly to the {area:1497}"] = "飛往{area:1497}",
		["Just south of Masoj, the {item:3502} grow on the hillsides above the river."] = "在馬索吉南邊不遠，{item:3502}生長在河流上方的山坡上。",
		["Keep it: the {area:287} coast, later on the route"] = "先留著：之後路線上的{area:287}海岸",
		["Masoj hides on the hillside above {area:290}, south-west of Durnholde, on the way down to the blossoms."] = "馬索吉躲在敦霍爾德城堡西南邊、{area:290}上方的山坡上，就在下山前往花叢的路上。",
		["Masoj wants an Apothecary Vial placed on three peaks. The southern one is the hilltop above {area:290}, south-east of the blossoms: use a vial at the top."] = "馬索吉要你在三座山峰上各放一瓶藥劑師瓶子。南邊那座是{area:290}上方、花叢東南邊的山頂：在山頂使用一瓶。",
		["The farms east of {area:287} town. {npc:232} works the field by the northern farmhouse, {npc:2403} the one further south-east; Farmhands and Farmers are everywhere. {npc:2451} tends the field south of the farms."] = "{area:287}鎮東邊的農場。{npc:232}在北邊農舍旁的田地工作，{npc:2403}在更東南邊的那塊；希爾斯布萊德雇農和希爾斯布萊德農夫到處都是。{npc:2451}照料農場南邊的田地。",
		["The smithy"] = "鐵匠鋪",
		["The smithy stands in the middle of {area:287} town. {npc:2404} and his apprentices work at the forge; the {object:1736} is stacked beside it. {npc:2449} walks the street north of it."] = "鐵匠鋪位於{area:287}鎮中央。{npc:2404}和他的學徒在熔爐邊工作；{object:1736}堆在旁邊。{npc:2449}在鐵匠鋪北邊的街上走動。",
		["The {object:556670} poster by the inn"] = "旅店旁的{object:556670}海報",
		["Train with {npc:3033}. Before you fly on, {npc:3024} and {npc:4721}, a short walk east of the wind rider master, give two quests worked on the next guides' walks; then fly on to the Crossroads, where the next guide starts."] = "在{npc:3033}那裡訓練。繼續飛行前，風騎士管理員東邊不遠處的{npc:3024}和{npc:4721}會給你兩個任務，在接下來幾份指南的路上完成；然後飛往十字路口，下一份指南從那裡開始。",
		["West of Tarren Mill, Gray Bears, Forest Moss Creepers and Starving Mountain Lions roam the hills on the way down to the farms. The creepers drop {item:3477} rarely; you need only one."] = "在塔倫米爾西邊，灰熊、森林食苔蛛和饑餓的山地獅在通往農場的山丘上遊蕩。食苔蛛很少掉落{item:3477}；你只需要一個。",
		["Zeppelin to {zone:1454}"] = "搭飛艇前往{zone:1454}",
		["{area:272} is your base for this guide: the hearth brings you back here twice. Everyone stands around the town square."] = "{area:272}是本指南的據點：爐石會兩次帶你回到這裡。所有人都站在鎮上廣場周圍。",
		["{item:15885}: use a half at the {area:2362}"] = "{item:15885}：在{area:2362}使用一半墜飾",
		["{item:3692}: the Peasants in the fields"] = "{item:3692}：田裡的希爾斯布萊德農民",
		["{npc:11798} in {area:2361} flies druids there"] = "{area:2361}的{npc:11798}會載德魯伊飛到那裡",
		["{npc:2055}, in the Apothecarium"] = "{npc:2055}，在皇家藥劑師協會",
		["{npc:2055}, in the {zone:1458}"] = "{npc:2055}，在{zone:1458}",
		["{npc:2215}: orders for {npc:270438}, on the way to Durnholde"] = "{npc:2215}：給{npc:270438}的命令，在前往敦霍爾德城堡的路上",
		["{npc:2238}'s ball and chain"] = "{npc:2238}的腳鐐",
		["{npc:2274} is {npc:232}'s dog, at the northern farmhouse in {area:286}."] = "{npc:2274}是{npc:232}的狗，在{area:286}北邊的農舍。",
		["{npc:2391}: Poisons"] = "{npc:2391}：毒藥",
		["{npc:3024}: {quest:97538}, the Mirkweed in {area:464} by Sun Rock"] = "{npc:3024}：{quest:97538}，太陽岩旁{area:464}的暗色水草",
		["{npc:4606} stands in the {object:36070}."] = "{npc:4606}站在{object:36070}。",
		["{npc:4721}: {quest:1195}, the phial from {zone:1440}'s Laughing Sisters"] = "{npc:4721}：{quest:1195}，從{zone:1440}的狂笑姐妹身上取得藥瓶",
} end)()
t.guides["forever/horde/07-ashenvale"] = (function() return {
		["A short walk north of the Galak camps, the cave of {area:1557} leads down to its deepest chamber, where the {object:20807} burns. Use the {item:5868} on it, then loot the {item:5869} at once: the flame only stays out briefly, and if it relights the phial is gone. Then east to {npc:2986}'s mesa.\nCareful: Two Galak Flame Guards (30) stand by the brazier and a centaur guard walks the cave: pull them away one at a time before you douse the flame."] = "在加拉克營地北邊不遠處，{area:1557}的洞穴通往最深處的洞室，{object:20807}就在那裡燃燒。對它使用{item:5868}，然後立刻拾取{item:5869}：火焰只會熄滅一小段時間，如果重新燃起，藥瓶就沒了。接著向東前往{npc:2986}的台地。\n小心：火盆旁站著兩個加拉克火焰守衛（30級），還有一個半人馬守衛在洞穴中巡邏：在熄滅火焰之前，先把他們一次一個拉開。",
		["Back south to the camp, then up into {zone:1456} for the flight to {area:378}."] = "向南回到營地，然後上到{zone:1456}搭乘飛往{area:378}的飛行路線。",
		["Class trainer"] = "職業訓練師",
		["Climb the path to the top of {area:2097}. {npc:10646} is held captive beside {npc:10896} (29): clear the guards and {npc:10896} first, then free her and protect her on the walk down; Grimtotem ambushers come at you on the way."] = "沿著小路爬到{area:2097}頂端。{npc:10646}被囚禁在{npc:10896}（29級）旁邊：先清掉守衛和{npc:10896}，再救出她，並在下山途中保護她；路上會有恐怖圖騰伏擊者來攻擊你。",
		["Felmusk satyrs"] = "魔草薩特",
		["Fly to {area:1638}"] = "飛往{area:1638}",
		["Fly to {area:1638} from Zoram'gar. If you don't know its flight path, fly to {area:378} and walk north through {zone:1412} instead."] = "從左拉姆加飛往{area:1638}。如果你不知道它的飛行路線，改飛往{area:378}，然後向北步行穿過{zone:1412}。",
		["Fly to {area:378}"] = "飛往{area:378}",
		["Follow the main road east past {area:415} (Alliance: keep to the road). {npc:12678}, a big grizzly, roams the {area:418} south of the road, west of {area:421}. His paw starts the next hunt quest."] = "沿著主要道路向東經過{area:415}（聯盟據點：沿著道路走）。{npc:12678}是一頭大灰熊，在道路南邊、{area:421}西邊的{area:418}遊蕩。牠的爪子會開始下一個狩獵任務。",
		["Galak centaurs"] = "加拉克半人馬",
		["Gazebo"] = "涼亭",
		["Gloomrise Toxin Samples, from the Gnawed Corpses"] = "鬱湧毒素樣本，來自{npc:264096}",
		["Keep east on the road. {npc:12858} waits south-west of the Warsong lumber camp. He and his grunts storm the {area:2360}: let them take aggro and stay with {npc:12858} until {npc:12860} is dead."] = "沿著道路繼續向東。{npc:12858}在戰歌伐木營地西南方等候。他和他的步兵會猛攻{area:2360}：讓他們吸引仇恨，跟著{npc:12858}直到{npc:12860}死亡。",
		["Kill the {npc:10720} that comes for {npc:10638}"] = "擊殺前來對付{npc:10638}的{npc:10720}",
		["Laughing Sisters"] = "歡笑姐妹",
		["North of the camp, spiders overrun the burial ground at {area:17044}. Use {npc:264074}'s {item:273015} on the Gnawed Corpses; the Spinners drop the {item:273181}. {npc:264082} sits at the north end: her {item:273658} starts {quest:96294}."] = "在營地北邊，蜘蛛佔據了{area:17044}的墓地。對{npc:264096}使用{npc:264074}的{item:273015}；紡絲蜘蛛會掉落{item:273181}。{npc:264082}在北端：她的{item:273658}會開始{quest:96294}。",
		["North-west of Splintertree, the Felmusk satyrs camp in the woods. Every satyr can drop horns."] = "在碎木崗哨西北方，魔草薩特在樹林中紮營。每個薩特都可能掉落角。",
		["On the way back north-east to Splintertree: {npc:12676} prowls the woods south-east of the Warsong lumber camp."] = "在往東北回碎木崗哨的路上：{npc:12676}在戰歌伐木營地東南方的樹林中徘徊。",
		["Only if the {npc:10617} dropped his plot for you: {npc:10638} stands at {area:2237}."] = "只有在{npc:10617}掉落他的陰謀給你時才做：{npc:10638}站在{area:2237}。",
		["Ride the lift down, then follow the road east through the canyons to {area:484}, a Tauren village on top of the mesas. Its lift is on the north side."] = "搭升降梯下去，然後沿著道路向東穿過峽谷前往{area:484}，這是一座位於台地頂端的牛頭人村莊。它的升降梯在北側。",
		["Sapphires of Aku'Mai"] = "阿庫麥爾藍寶石",
		["South from Raynewood, the moonwell sits in a hollow west of the river, hard to see from the road; {area:421} is west of it. Use the {item:5867} at the moonwell to fill it."] = "從雷恩林地往南，月井位於河流西邊的一處窪地中，從道路上很難看見；{area:421}在它西邊。在月井使用{item:5867}將它裝滿。",
		["Speak with {npc:3057}, in {area:1638}: {quest:93739}"] = "與{area:1638}的{npc:3057}交談：{quest:93739}",
		["Take the lift down. The egg lies in a nest on the canyon floor in one of three spots: south-east of the mesas (52.3,55.2), east (56.4,50.4) or south-west (37.6,56.1)."] = "搭升降梯下去。蛋在峽谷底部的巢裡，位於三處之一：台地東南方（52.3,55.2）、東方（56.4,50.4）或西南方（37.6,56.1）。",
		["The Earthen Ring"] = "陶土議會",
		["The Foulweald furbolgs hold the woods east of {area:421}, south of the road. Place {item:16972} on the {object:178206} and guard it: the furbolgs come to tear it down. {npc:12918} comes last; his totem drops in the basket."] = "汙林熊怪佔據{area:421}東邊、道路南邊的樹林。把{item:16972}放在{object:178206}上並守住它：熊怪會來把它拆掉。{npc:12918}最後出現；他的圖騰會掉在籃子裡。",
		["The Galak camps fill the canyon north of Freewind; Scouts, Wranglers and Windchasers share every camp. A lone {npc:10617} walks between the camps: kill him when you meet him, his note starts a quest for {area:2237}."] = "加拉克營地遍布亂風崗北邊的峽谷；每個營地都有加拉克斥候、加拉克爭鬥者和加拉克逐風者。有一個落單的{npc:10617}在營地之間走動：遇到就殺了他，他的信會開始一個交給{area:2237}的任務。",
		["The Laughing Sisters, dryads, wander {area:426} around {npc:12677}'s woods; one of them drops {npc:4721}'s {item:5867}, which can take several kills."] = "歡笑姐妹是樹妖，在{npc:12677}所在樹林周圍的{area:426}遊蕩；其中一隻會掉落{npc:4721}的{item:5867}，可能需要擊殺好幾隻。",
		["The Sapphires are blue crystals on the walls of the tunnels leading to the {area:2797} portal, underground and outside the instance: swim down from the pit, under the wall, into the cave. The satyrs and naga in the tunnels are elite: grouping up is advised. The crystals respawn quickly, so there is no need to go deep."] = "藍寶石是通往{area:2797}傳送門的隧道牆上的藍色水晶，位於地下、副本之外：從坑洞往下游，穿過牆下進入洞穴。隧道裡的薩特和納迦是精英：建議組隊。水晶重生得很快，不必深入。",
		["The Wanted poster beside {npc:10537}"] = "{npc:10537}旁的通緝告示",
		["The way to the Sapphires is through the sunken ruins at the north end of the strand: go down the stairs into the pit."] = "前往藍寶石的路要穿過海岸北端沉沒的遺跡：從階梯走下坑洞。",
		["West of Freewind, the Grimtotem camps below {area:2097}. The Secret Notes are in Document Chests at the south-east, south-west and north-west camps."] = "在亂風崗西邊，恐怖圖騰在{area:2097}下方紮營。密信放在東南、西南和西北營地的{object:176344}裡。",
		["West of Mystral Lake, {npc:12678}, a big grizzly, roams the {area:418}: his paw now drops for you."] = "在密斯特拉湖西邊，大灰熊{npc:12678}在{area:418}遊蕩：現在牠的爪子會為你掉落了。",
		["for {npc:5901}, south of {area:392}: next guide"] = "給{area:392}南邊的{npc:5901}：下一份指南",
		["{area:2797} ruins"] = "{area:2797}遺跡",
		["{area:418} fountain"] = "{area:418}的噴泉",
		["{item:273181}, from Gloomrise Spinners"] = "{item:273181}，來自{npc:264081}",
		["{item:5867}, at the {object:20806}"] = "{item:5867}，在{object:20806}",
		["{item:5867}, from a {npc:4054}"] = "{item:5867}，來自{npc:4054}",
		["{item:5868}, at the {object:20807}"] = "{item:5868}，在{object:20807}",
		["{item:5869}, from the {object:20807}"] = "{item:5869}，來自{object:20807}",
		["{npc:10377}, by the wind rider master"] = "{npc:10377}，在雙足飛龍管理員旁",
		["{npc:10428}'s next quest, Sacred Fire, ends in {zone:1456}, off this route. Skip it."] = "{npc:10428}的下一個任務「聖火」在{zone:1456}完成，不在這條路線上。跳過。",
		["{npc:10617}'s {quest:4881}, if you meet him"] = "{npc:10617}的{quest:4881}，如果你遇到他",
		["{npc:12677}, a shadow panther, stalks the woods around {area:426}, west of the Felmusk camp. Her head starts the next hunt quest."] = "{npc:12677}是一隻暗影豹，在魔草營地西邊的{area:426}周圍的樹林中潛行。她的頭顱會開始下一個狩獵任務。",
		["{npc:12696} keeps the hunt board at {area:428}, by the flight master: take {quest:6383} and hand it straight back. {npc:12678}, {npc:12676} and {npc:12677} drop their trophies only after it."] = "{npc:12696}在{area:428}的飛行管理員旁管理狩獵告示板：接下{quest:6383}並立刻交回。之後{npc:12678}、{npc:12676}和{npc:12677}才會掉落牠們的戰利品。",
		["{npc:12696}, once all three hunts are in"] = "{npc:12696}，三個狩獵任務都交完後",
		["{npc:12718}: only if you carry the manual pages"] = "{npc:12718}：只有在你帶著手冊書頁時",
		["{npc:12736} offers a {area:2797} quest next; leave it unless you have a group."] = "{npc:12736}接著會提供一個{area:2797}任務；除非你有小隊，否則先不要做。",
		["{npc:210995}, a Forever addition, stands on the west shore of {area:421} with three quick Dragonslayer quests."] = "{npc:210995}是 Forever 新增的角色，站在{area:421}西岸，有三個快速的屠龍者任務。",
		["{npc:2986} stands on a mesa top east of the Galak camps. For the {quest:1149}, walk off the end of the planks beside him: you land safely."] = "{npc:2986}站在加拉克營地東邊的台地頂上。為了{quest:1149}，從他旁邊的木板盡頭走下去：你會安全落地。",
		["{npc:3024} stands beside {npc:4721}, east of {npc:2995}."] = "{npc:3024}站在{npc:4721}旁邊，位於{npc:2995}東邊。",
		["{npc:4721} stands a short walk east of {npc:2995}."] = "{npc:4721}站在{npc:2995}東邊不遠處。",
		["{npc:4721}: {npc:4722} at {area:484}, later in this guide"] = "{npc:4721}：{area:484}的{npc:4722}，在本指南稍後",
		["{npc:4722} stands in {area:484}: {npc:4721}'s filled phial is for him."] = "{npc:4722}站在{area:484}：{npc:4721}裝滿的藥瓶是要給他的。",
		["{npc:4722}: the {object:20807} in {area:1557}, among the Galak camps"] = "{npc:4722}：{area:1557}裡的{object:20807}，在加拉克營地之間",
		["{object:176344}, north-west camp"] = "{object:176344}，西北營地",
		["{object:176344}, south-east camp"] = "{object:176344}，東南營地",
		["{object:176344}, south-west camp"] = "{object:176344}，西南營地",
		["{zone:1456}'s central rise"] = "{zone:1456}的中央高台",
} end)()
