} end)()
t.guides["forever/horde/40-50/03-feralas"] = (function() return {
		["Back east past {area:75}: the Atal'ai artifacts lie in the water and on the banks of the {quest:1424}."] = "向東經過{area:75}：阿塔萊的文物在{quest:1424}的水中和岸邊。",
		["Below ground"] = "地下",
		["Dragon caves"] = "龍穴",
		["Fly to {area:1099}"] = "飛往{area:1099}",
		["Fly to {area:75}"] = "飛往{area:75}",
		["Frayfeather hippogryphs"] = "亂羽角鷹獸",
		["Level 45.37"] = "等級45.37",
		["Murlocs of the Misty Reed"] = "蘆葦崗哨的魚人",
		["Northspring harpies"] = "北泉鷹身人",
		["Onyxia's eggs"] = "奧妮克希亞的蛋",
		["Rage Scar yetis"] = "狂暴的怒痕雪人",
		["Ride back north to Brackenwall."] = "向北騎回蕨牆村。",
		["Ride north-west to the {area:1108}; {npc:14637} waits on the dock."] = "向西北騎到{area:1108}；{npc:14637}在碼頭上等著。",
		["Ride west along the road; the scroll lies at the water's edge in the swamp's far west."] = "沿道路向西騎；卷軸在沼澤最西邊的水邊。",
		["Riding at 40"] = "40級騎術",
		["Rogue Vale screechers"] = "遊蕩的山谷尖嘯者",
		["Sawtooth crocolisks"] = "鹽齒鱷魚",
		["Sea elementals and sea sprays wash along the shore around the dock. Zap the giants with {item:18904} first: shrunken, they lose their elite strength. Shore striders wade in the water; the land walkers and cliff giants roam the hills further north."] = "海元素和巨型海元素在碼頭周圍的海岸邊漂流。先用{item:18904}電擊巨人：縮小後就失去精英的力量。海岸巨人在水中涉行；大地行者和峭壁巨人在更北邊的山丘遊蕩。",
		["Skeletal horses: {npc:4731}, beside {npc:4773} in {area:159}."] = "骸骨戰馬：{npc:4731}，在{area:159}的{npc:4773}旁邊。",
		["South of the vale the Frayfeather hippogryphs roost on the slopes; nearly every one drops sinew and metallic fragments."] = "山谷南邊，亂羽角鷹獸棲息在山坡上；幾乎每一隻都會掉落肌腱和金屬碎片。",
		["Sprite darters and forest walkers"] = "小精龍與森林漫遊者",
		["The Eggs of Onyxia lie in the dragon caves in the {area:511}'s south-east, guarded by the scalebanes; smash five."] = "奧妮克希亞的蛋在{area:511}東南部的龍穴中，由火鬃守衛看守；砸碎五個。",
		["The Marsh Murlocs live on the strand south of the post; the Inkspewers are along the shore east of it and the Flesheaters further west, around the huts on the western shore."] = "沼澤魚人住在哨站南邊的海灘；沼澤噴墨魚人在哨站東邊的岸邊，沼澤食腐魚人在更西邊、西岸的小屋周圍。",
		["The Northspring harpies nest on the ridges in the far north-west. They are 48-50, a few levels above you: the Windcallers heal, so kill them first and pull one at a time."] = "北泉鷹身人在最西北方的山脊上築巢。她們是48-50級，比你高幾級：北泉喚風者會治療，所以先殺她們，並一次只拉一隻。",
		["The sprite darters flit over the grove just west of the camp and carry the {item:9589}; the Wandering Forest Walkers, a little further west, carry the Splintered Logs."] = "小精龍在營地西邊不遠的樹林上空飛舞，身上帶著{item:9589}；再往西一點的森林漫遊者身上帶著斷裂的原木。",
		["Zeppelin to {object:3202}"] = "搭飛艇前往{object:3202}",
		["for the {npc:5598} in the {zone:1425}, around level 48"] = "之後給{zone:1425}的{npc:5598}，約48級",
		["for the {object:2555} in {zone:1445}, later in this guide"] = "之後在本指南中用於{zone:1445}的{object:2555}",
		["for the {zone:1425} owlbeasts, around level 48"] = "之後給{zone:1425}的梟獸，約48級",
		["the {object:2555}"] = "{object:2555}",
		["{npc:2934}, on the way back to Zinge"] = "{npc:2934}，在回去找辛吉的路上",
		["{npc:4500}'s challenge, back in Brackenwall, needs a group of three. Alone, grind the Firemane scouts here on the {area:511}'s northern edge to level 45.37 before you ride back north, so you don't come back down for it. Or, with a group, run the {area:978} dungeon or the {area:1517} dungeon instead."] = "回到蕨牆村後，{npc:4500}的挑戰需要三人隊伍。單人的話，在騎回北邊之前，先在{area:511}北緣這裡刷火鬃斥候到45.37級，這樣就不用再下來一趟。或者，有隊伍的話，改去打{area:978}地城或{area:1517}地城。",
		["{npc:4773}, riding trainer"] = "騎術訓練師{npc:4773}",
		["{npc:7825}, the {object:36126}"] = "{npc:7825}，{object:36126}",
		["{quest:7738}, a rare drop"] = "{quest:7738}，稀有掉落",
} end)()
t.guides["forever/horde/40-50/04-tanaris"] = (function() return {
		["Back north, just south of {area:976}, use the {item:8524} now: the two-hour timer starts. The Blisterpaw Hyenas, Glasshide Basilisks and Scorpid Hunters share the dunes here. Each can drop an untested sample: use it, and it either passes as an acceptable one or is lost. Keep killing until you have eight of each."] = "回到北邊，就在{area:976}南方，現在使用{item:8524}：兩小時的計時開始。水泡土狼、玻璃皮蜥蜴和蠍子獵手共同分布在這裡的沙丘上。每種都可能掉落未測試的樣本：使用它，它要麼通過成為合格的樣本，要麼就會損失。持續擊殺直到每種各有八個。",
		["Below ground"] = "地下",
		["Dark Iron Lookouts"] = "黑鐵哨兵",
		["Fly to {area:976}"] = "飛往{area:976}",
		["His next request needs the {item:10552} from elite cultists: leave it."] = "他的下一個請求需要精英教徒身上的{item:10552}：別管它。",
		["Keep the Model 4711-FTZ Power Source Bilgewhizzle gave you: it starts {quest:654}, a two-hour timer, so use it on the way back north from Scrimshank's hive."] = "保留比格維茲給你的4711-FTZ型能量源：它會開始{quest:654}，限時兩小時，所以在從謝申克的蟲巢往北回去的路上再使用。",
		["OOX-17/TN"] = "OOX-17/TN",
		["Only with the {item:11818}: back east to the {object:173265} at the dig site."] = "僅限持有{item:11818}時：向東回到挖掘場的{object:173265}。",
		["Ride north-west across the gorge; {area:1446} is the scaffolded camp in the north-west."] = "向西北騎過峽谷；{area:1446}是西北方搭著鷹架的營地。",
		["Scrimshank's gear"] = "謝申克的設備",
		["South of the {area:982} the Dunemaul ogres hold their compound, with {npc:12046} at its eastern end. Dig up {quest:3161} ornaments between the fights."] = "{area:982}南邊，砂槌巨魔佔據他們的營地，{npc:12046}在營地東端。在戰鬥之間挖出{quest:3161}飾品。",
		["The Dark Iron Lookouts stand on the ridges around the sentry towers south of the Cauldron; about one in ten carries the {item:18960}."] = "黑鐵哨兵站在大熔爐南邊哨塔周圍的山脊上；大約十分之一帶有{item:18960}。",
		["The Dark Iron Steamsmiths work the furnaces in the middle of the Cauldron; half of them carry a {item:10551}, one in ten the {item:18959}. Slaves, Slavers and Taskmasters carry daggers too."] = "黑鐵鍛造師在大熔爐中央操作熔爐；一半帶有{item:10551}，十分之一帶有{item:18959}。奴隸工、奴隸販子和工頭也帶著匕首。",
		["The Steamsmiths' furnaces"] = "鍛造師的熔爐",
		["The {area:247}"] = "{area:247}",
		["The {object:142071} machine, in the middle of town: the egg is in southern {zone:1444}, around level 50"] = "鎮中央的{object:142071}機器：蛋在{zone:1444}南部，大約50級",
		["The {object:179827} board"] = "{object:179827}告示板",
		["Use the {item:8524}"] = "使用{item:8524}",
		["West along the road south; {npc:7771} camps by the ruins at the {area:1938}. Put on his {item:9978}: it shows the buried ornaments, here and around the {area:983}."] = "沿著往南的道路向西走；{npc:7771}在{area:1938}的廢墟旁紮營。戴上他的{item:9978}：它會顯示埋在地下的飾品，在這裡和{area:983}周圍都有。",
		["West of Gadgetzan, use the {item:8584} beside the water hole in the troll camp."] = "在加基森西邊，於食人妖營地的水池旁使用{item:8584}。",
		["for {npc:7010} in {zone:1454}, around level 50"] = "交給{zone:1454}的{npc:7010}，大約50級",
		["the {item:8526} grows in the {zone:1425}, around level 48"] = "{item:8526}生長在{zone:1425}，大約48級",
		["the {object:173265}"] = "{object:173265}",
		["{item:11818}, a rare drop"] = "{item:11818}，稀有掉落",
		["{item:8623}, a rare drop"] = "{item:8623}，稀有掉落",
		["{npc:5955} waits in the valley. Walk him all the way to his wife {npc:6015} in {area:977}, north-east across the desert: stay close, slow down for him and fight off what attacks him. Do not mount or hearth out of his reach. {npc:8579} stands in the port too."] = "{npc:5955}在山谷裡等候。一路護送他向東北穿過沙漠，到{area:977}找他的妻子{npc:6015}：跟緊他，放慢速度配合他，擊退攻擊他的敵人。不要騎坐騎或用爐石離開他的範圍。{npc:8579}也在港口裡。",
		["{npc:5955}'s escort"] = "護送{npc:5955}",
		["{npc:7876}, beside the wind rider master"] = "{npc:7876}，在雙足飛龍管理員旁邊",
} end)()
t.guides["forever/horde/40-50/05-the-hinterlands"] = (function() return {
		["Back west to {area:350}; rangers and marksmen stay near the lodge, scouts and outrunners on the slopes south of it."] = "向西回到{area:350}；高原遊俠和高原神射手待在小屋附近，高原斥候和高原前鋒在小屋南邊的山坡上。",
		["East of the village, the violet flower grows in the hills."] = "村子東邊的丘陵上長著紫色水生菇。",
		["Fly to {area:272}"] = "飛往{area:272}",
		["Fly to {area:75}"] = "飛往{area:75}",
		["Follow the roads east across the {zone:1425} to the troll village on the eastern coast."] = "沿道路向東穿過{zone:1425}，前往東海岸的食人妖村落。",
		["Highvale"] = "高原精靈",
		["His next request, going on to the {area:355}, is for a group."] = "他的下一個要求是前往{area:355}，需要組隊。",
		["North along the coast, {npc:14731}'s picnic basket is on the small island; a {npc:14748} guards it."] = "沿海岸向北，{npc:14731}的野餐籃在小島上；由一個{npc:14748}看守。",
		["OOX-09/HL"] = "OOX-09/HL",
		["Ride all the way west to the Wildhammer town of {area:348} and place the message by the well in its centre. The town is full of Alliance guards: get in, place it and get out."] = "一路向西騎到蠻錘矮人的城鎮{area:348}，把訊息放在鎮中央的井邊。鎮上滿是聯盟守衛：進去、放下、離開。",
		["Ride back north to the bloodmages."] = "向北騎回血法師那裡。",
		["Ride north-east from {area:272} into the {zone:1425} and east along the road; {npc:7801} camps on the hill south of the elves' {area:350}."] = "從{area:272}向東北騎進{zone:1425}，再沿道路向東；{npc:7801}在精靈的{area:350}南邊的山丘上紮營。",
		["Ride west out of {area:75} and south through the canyon into the {zone:1419}; the two bloodmages stand by the road just inside."] = "從{area:75}向西騎出，再向南穿過峽谷進入{zone:1419}；兩名血法師就站在入口處的道路旁。",
		["South of the lodge the Witherbark trolls hold their villages. Every one of them carries a skull: with twenty, use {item:15002} to make the Laden Pike, then plant it inside the village."] = "小屋南邊，枯木食人妖佔據他們的村落。每一隻身上都帶著頭骨：收集二十個後，使用{item:15002}製作尼姆布亞的長矛，然後插在村子裡。",
		["South-west again, the exile hides by the ruins of {area:353}."] = "再往西南，流放者躲在{area:353}的廢墟旁。",
		["The bloodmages"] = "血法師",
		["The crates of {item:8684} lie around the abandoned Horde camp at {area:351}, among the oozes."] = "{item:8684}的箱子散落在{area:351}廢棄的部落營地周圍，在軟泥怪之間。",
		["The secret lies on the {area:307}, above the beach."] = "秘密在海灘上方的{area:307}。",
		["Their follow-ups ask for the same parts again for a buff item and pay no experience: leave them."] = "他們的後續任務要你再交一次同樣的材料換取增益物品，不給經驗值：不用理會。",
		["These are elite mobs: grouping up is encouraged, look for people to do it with. {npc:7977} is a level 48 elite: most classes solo it at level 50, but you may need help. Skip it if you are alone: the route has you grind the XP back.\n{npc:7977} walks the shore below the {area:307}, from the arrow south to about 75,66 and north to about 82,52: if she isn't at the arrow, follow the shore."] = "這些是精英怪：建議組隊，找人一起打。{npc:7977}是48級精英：大多數職業在50級時可以單刷，但你可能需要幫忙。如果你是獨自一人就跳過：本路線會讓你把經驗值刷回來。\n{npc:7977}沿著{area:307}下方的海岸行走，從箭頭處向南到約75,66，向北到約82,52：如果她不在箭頭處，就沿著海岸找。",
		["for {npc:6986} in {zone:1454}, around level 50"] = "之後給{zone:1454}的{npc:6986}，約50級",
		["for {npc:7825} in the {zone:1458}, around level 50"] = "之後給{zone:1458}的{npc:7825}，約50級",
		["{area:348} well"] = "{area:348}的井",
		["{item:8704}, a rare drop"] = "{item:8704}，稀有掉落",
		["{npc:14731}'s lunch"] = "{npc:14731}的午餐",
		["{npc:14757}, at the top of {area:354}"] = "{npc:14757}，在{area:354}頂端",
		["{npc:7801}'s camp"] = "{npc:7801}的營地",
} end)()
t.guides["forever/horde/40-50/06-azshara"] = (function() return {
		["Back north-east to {npc:8420}."] = "向東北回到{npc:8420}處。",
		["Back to {area:1099}"] = "返回{area:1099}",
		["Back to {npc:11548} at the shrine; stay west of the {area:3137} guards."] = "回到神殿的{npc:11548}處；待在{area:3137}守衛的西邊。",
		["Back to {object:3202}"] = "返回{object:3202}",
		["Below ground"] = "地下",
		["Class trainer"] = "職業訓練師",
		["Continue south to {area:35}. {npc:7406} has his workshop on the upper ring of the bay."] = "繼續向南前往{area:35}。{npc:7406}的工作室在海灣的上層環道。",
		["Fly to {area:1099}"] = "飛往{area:1099}",
		["Fly to {area:1637}"] = "飛往{area:1637}",
		["Fly to {area:1638}"] = "飛往{area:1638}",
		["Fly to {area:35}"] = "飛往{area:35}",
		["Fly to {area:976}"] = "飛往{area:976}",
		["Fly to {object:3202}"] = "飛往{object:3202}",
		["Fly to {zone:1456}; it is on the way to {area:1099}. No flight path there yet? Fly to {area:378} and ride west through {zone:1412}. Hamuul and {npc:4046} are on the {area:1639}; Druids and Paladins train here ({npc:3033}, {npc:246344})."] = "飛往{zone:1456}；它在前往{area:1099}的路上。還沒有那裡的飛行路線？飛往{area:378}，然後向西騎過{zone:1412}。哈繆爾和{npc:4046}在{area:1639}；德魯伊和聖騎士在這裡學習（{npc:3033}、{npc:246344}）。",
		["Follow the road north to {area:1237}, the Horde camp."] = "沿著道路向北前往部落營地{area:1237}。",
		["Frayfeather Hippogryphs"] = "亂羽角鷹獸",
		["Hippogryph nests"] = "角鷹獸巢穴",
		["Keep the deliveries for {npc:4046}, {npc:8659} and {npc:6522}: you pass {zone:1456}, {zone:1454} and the {zone:1458} later."] = "保留要交給{npc:4046}、{npc:8659}和{npc:6522}的貨物：你稍後會經過{zone:1456}、{zone:1454}和{zone:1458}。",
		["Keep {npc:8659}'s payment and Ag'tor's {quest:3504}: they go back to {area:1237} on a later visit."] = "保留{npc:8659}的報酬和阿格圖的{quest:3504}：下次造訪時帶回{area:1237}。",
		["Keep {quest:3444}: {npc:7771}'s chest is opened on a later visit."] = "保留{quest:3444}：{npc:7771}的箱子要在下次造訪時打開。",
		["On the way through {zone:1454} to the flight master, step into the Drag: {npc:7010} takes the insect report from {zone:1446}, and its experience shortens the top-up to 50 in {zone:1447}."] = "經過{zone:1454}前往飛行管理員的路上，順道進入暗巷區：{npc:7010}收下來自{zone:1446}的昆蟲報告，獲得的經驗能縮短在{zone:1447}補到50級的時間。",
		["Only once all three robots are home"] = "三個機器人都回家後才能做",
		["Ride east along the road out of Splintertree. {npc:11548} waits at the {area:1235} just off the road, a few steps west of the Alliance's {area:3137}: come in from the west and keep clear of the Azshara Sentinels and Jarrodenus (elite)."] = "沿著道路從碎木崗哨向東騎。{npc:11548}在路旁不遠的{area:1235}等候，位於聯盟{area:3137}西邊幾步遠：從西邊過去，避開艾薩拉哨兵和加羅迪努斯（精英）。",
		["Ride into {zone:1447}"] = "騎進{zone:1447}",
		["Ride north-east to the goblin's camp on the cliffs above the {area:1227}."] = "向東北騎往{area:1227}上方懸崖上的哥布林營地。",
		["Ride south along the road to the {area:1938}; {npc:7771} camps beside it. From here the road west leads down into {zone:1449}, where the next guide starts."] = "沿著道路向南前往{area:1938}；{npc:7771}在旁邊紮營。從這裡往西的道路會下到{zone:1449}，下一份指南從那裡開始。",
		["Ride south-west to the ruins. The four tablets lie among the ruins, guarded by Spitelash naga; any Siren or Myrmidon can carry {npc:8420}'s rune."] = "向西南騎往遺跡。四塊石板在遺跡之間，由惡鞭納迦看守；任何惡鞭海妖或惡鞭侍從都可能帶著{npc:8420}的符文。",
		["Ride west back to {area:1237}."] = "向西騎回{area:1237}。",
		["Sprite Darters"] = "小精龍",
		["The Bloodsail ships"] = "血帆海盜船",
		["The Droffers' shop is a few steps further into the Drag."] = "德羅佛斯的商店在暗巷區再往裡走幾步。",
		["The Highborne ghosts haunt the ruins just north of the shrine; the Haldarr satyrs camp a little further north."] = "精靈貴族的鬼魂在神殿北邊的遺跡中出沒；哈達爾薩特在更北邊一點紮營。",
		["The Thunderhead Hippogryphs fly over the hills just south of {area:1237}."] = "雷首角鷹獸在{area:1237}南邊的山丘上空飛翔。",
		["The blood elves' camp lies just south of {npc:8420}. His four pieces of equipment lie in the crates around the camp."] = "血精靈的營地就在{npc:8420}南邊。他的四件裝備在營地周圍的箱子裡。",
		["The faerie dragons flit around the woods just west of the camp. Use the vessel on each one you kill."] = "精靈龍在營地西邊的樹林中飛舞。對你殺死的每一隻使用容器。",
		["The hippogryph nests are on the hills to the south, around the {area:2522}; each holds an egg for the {object:142071}."] = "角鷹獸巢穴位於南邊的山丘上，在{area:2522}周圍；每個巢裡都有一顆要給{object:142071}的蛋。",
		["The hippogryphs nest on the hills south-west of the camp. Kill one, then use the Muisek Vessel on its body."] = "角鷹獸在營地西南方的山丘上築巢。殺一隻，然後對牠的屍體使用靈魂精華容器。",
		["The treants wander the forest roads between the camp and the middle of {zone:1444}; there are only a few, so look along the paths."] = "樹人在營地和{zone:1444}中部之間的林間道路上遊蕩；數量不多，沿著小路找找。",
		["The {object:142071}, in the middle of town"] = "{object:142071}，在城鎮中央",
		["To {object:3202}"] = "前往{object:3202}",
		["Undamaged Hippogryph Feathers"] = "完整的角鷹獸羽毛",
		["Upstairs"] = "樓上",
		["Wandering Forest Walkers"] = "森林漫遊者",
		["Xylem's tower stands on the cliff just north of {area:1237}; the path winds up its north side."] = "克希雷姆的塔位於{area:1237}北邊的懸崖上；小路沿著它的北側蜿蜒而上。",
		["Zeppelin to {zone:1454}"] = "搭飛艇前往{zone:1454}",
		["{npc:6986}, the Drag"] = "{npc:6986}，在城裡",
		["{npc:7010}, the Drag"] = "{npc:7010}，暗巷區",
		["{npc:7010}, the Drag: if you still carry it"] = "{npc:7010}，暗巷區：如果你還帶著它",
		["{npc:7776}: the bears are in {zone:1448}"] = "{npc:7776}：熊在{zone:1448}",
		["{npc:7876}'s tar and Pestlezugg's samples come from {zone:1449}."] = "{npc:7876}的焦油和匹斯特蘇格的樣本都來自{zone:1449}。",
		["{npc:7876}, beside the wind rider master"] = "{npc:7876}，在雙足飛龍管理員旁",
		["{npc:8395}, at the east edge of the camp: no experience, only a teleport to Azshara Tower"] = "{npc:8395}，在營地東緣：沒有經驗值，只能傳送到艾薩拉的高塔",
		["{npc:8659}, the {object:172960}"] = "{npc:8659}，{object:172960}",
		["{quest:3761} is gathered in the next guide; {npc:4046}'s payment goes back to {npc:8587} later."] = "{quest:3761}在下一份指南中收集；{npc:4046}的報酬稍後交回給{npc:8587}。",
		["{zone:1454} flight master"] = "{zone:1454}的飛行管理員",
} end)()
t.guides["forever/horde/50-60/01-un-goro-crater"] = (function() return {
		["Back a few steps west to Felstone Farm, the first farm along the road; {npc:10778} waits in the house."] = "往西回走幾步到費爾斯通農場，也就是沿路的第一座農場；{npc:10778}在屋裡等候。",
		["Back north-east to {area:251}."] = "向東北回到{area:251}。",
		["Below ground"] = "地下",
		["Bridge into {area:254}"] = "通往{area:254}的橋",
		["Cross the south of the crater to the pylon on the western cliffs."] = "穿過環形山南部，前往西邊懸崖上的水晶塔。",
		["Eastern Pylon"] = "東部水晶塔",
		["Fly to {area:272}"] = "飛往{area:272}",
		["Follow the cliffs south to {quest:3821}, the Firegut ogres' hill. {npc:9136}'s remains lie at its foot."] = "沿著懸崖向南前往火腹巨魔的山丘{quest:3821}。{npc:9136}的遺骸在山腳下。",
		["From here on pick up every Power Crystal (blue, green, red, yellow) and every {quest:3761} pile you pass: 25 soil in all, 20 for Hamuul and 5 for Pestlezugg."] = "從現在起，拾取沿途經過的每一個能量水晶（藍、綠、紅、黃）和每一堆{quest:3761}：共25份土壤，20份給哈繆爾，5份給匹斯特蘇格。",
		["From the {area:152}, follow the road east into the {zone:1422}. The Scarlet Crusade's tents stand just past Felstone Farm, between {area:199} and {area:200}. Torch the command tent with the {object:176092} and plant the Scourge banner."] = "從{area:152}沿著道路向東進入{zone:1422}。血色十字軍的帳篷就在費爾斯通農場過去一點，位於{area:199}和{area:200}之間。用{object:176092}燒掉指揮帳篷，並插上天災戰旗。",
		["From the {area:1938} ride west to the long ramp that winds down into {zone:1449}, then follow the crater's north wall to {area:541}, a camp in the cliff caves. Everyone here is neutral."] = "從{area:1938}向西騎到蜿蜒而下進入{zone:1449}的長坡道，然後沿著環形山北壁前往{area:541}，一個位於懸崖洞穴中的營地。這裡的所有人都是中立的。",
		["Gorillas"] = "猩猩",
		["Into the {zone:1427}"] = "進入{zone:1427}",
		["Into {zone:1449}"] = "進入{zone:1449}",
		["Keep the parcel: {npc:10781} is in the {zone:1458}. Keep {quest:5901}: its termite mounds are in {area:2627}, on the next guide's ride to Tirion. The next guide starts with {npc:10739} by the {area:202}, south-east of here."] = "保留包裹：{npc:10781}在{zone:1458}。保留{quest:5901}：它的白蟻丘在{area:2627}，位於下一份指南前往提里奧的路上。下一份指南從這裡東南方{area:202}旁的{npc:10739}開始。",
		["Keep {npc:10267}'s letter: {quest:4808} is in {area:2255}, {zone:1452}."] = "保留{npc:10267}的信：{quest:4808}在{zone:1452}的{area:2255}。",
		["Keep {npc:9118}'s {quest:4147} and {npc:8737}'s letter for later guides."] = "保留{npc:9118}的{quest:4147}和{npc:8737}的信，留給之後的指南。",
		["Lar'korwi Mates"] = "拉克維的配偶",
		["Lashers and Threshers"] = "血瓣花鞭笞者與猛擊者",
		["Leave the {zone:1458} and ride east along the road through {zone:1420} to the {area:152}, the Forsaken fort on the border."] = "離開{zone:1458}，沿著道路向東穿過{zone:1420}前往邊境上的被遺忘者要塞{area:152}。",
		["North of Torwa, a dead Threshadon lies by the water."] = "在托爾瓦北邊，一頭死去的蛇頸龍躺在水邊。",
		["Northern Pylon"] = "北部水晶塔",
		["Out of the refuge"] = "離開避難營",
		["Power Crystals and soil"] = "能量水晶與土壤",
		["Pterrordax"] = "翼手龍",
		["Ride down the east side of the crater to the pylon on the eastern cliffs."] = "沿著環形山東側往下騎到東邊懸崖上的水晶塔。",
		["Ride north along the east side. Bloodpetal Lashers and Threshers fill the jungle."] = "沿著東側向北騎。血瓣花鞭笞者和血瓣花猛擊者佈滿叢林。",
		["Ride north back to {area:541}."] = "向北騎回{area:541}。",
		["Scarlet forward camp"] = "血色十字軍前進營地",
		["Stegodons and ravasaurs"] = "劍龍與暴掠龍",
		["Take a {object:176092} from the crate next to Derrington for {quest:5096}, done on the way back. Equip the {quest:5401}: Scourgestones only drop while you wear it."] = "從德靈頓旁邊的箱子拿一個{object:176092}，用於{quest:5096}，在回程時完成。裝備{quest:5401}：只有穿戴時才會掉落天譴石。",
		["Take the pass out of {area:340}'s west side into the {zone:1427}, then ride south across the gorge to the long bridge into {area:254}. Inside, follow the chain walkways down and leave through the southern exit; stay off the paths to the dungeon portals."] = "從{area:340}西側的山口進入{zone:1427}，然後向南穿過峽谷，走長橋進入{area:254}。進去後沿著鐵鍊走道往下，從南側出口離開；不要走往地城傳送門的路。",
		["The Lar'korwi Mates prowl the jungle north-west of {npc:9619}."] = "拉克維的配偶在{npc:9619}西北方的叢林中徘徊。",
		["The crystal clusters stand all over the crater, many around {area:537}. Take a few extra of each colour for the pylons."] = "水晶簇遍布整個環形山，許多在{area:537}周圍。每種顏色多拿幾個給水晶塔用。",
		["The expedition's crate sits at an abandoned camp in the eastern jungle."] = "探險隊的箱子在東部叢林中一處廢棄的營地裡。",
		["The expedition's lost equipment lies in the south-west jungle."] = "探險隊遺失的設備在西南方的叢林裡。",
		["The gorillas live on the north-east plateau. Stay out of the deepest cave: {npc:9622} lives there."] = "猩猩住在東北方的高地上。不要進入最深的洞穴：{npc:9622}住在那裡。",
		["The mountain lets you out beside {area:252}, full of 55-57 orcs. Follow the road east along the northern cliffs to the Horde camp at {area:251}."] = "出了山就在{area:252}旁邊，那裡滿是55-57級的獸人。沿著道路向東，沿北側懸崖前往{area:251}的部落營地。",
		["The pylon stands on the slope east of the refuge."] = "水晶塔位於避難營東邊的山坡上。",
		["The raft lies on the shore of the south-eastern lake; the small pack sits in the water beside it."] = "木筏在東南方湖泊的岸邊；小包就在旁邊的水裡。",
		["The tar pits lie just south of the refuge. Tar Beasts, Lurkers and Creepers drop the {item:11834}."] = "焦油坑就在避難營南邊。焦油獸、焦油潛伏者和焦油爬行者會掉落{item:11834}。",
		["Theodora's next errand goes to Lotwil east of town and then into {area:1584}: skip it."] = "塞朵拉的下一個差事要去鎮東找魯特維爾，然後進入{area:1584}：跳過。",
		["Upstairs"] = "樓上",
		["Use the Mangled Journal to start it"] = "使用被撕破的日記開始任務",
		["Western Pylon"] = "西部水晶塔",
		["{item:11116}, a rare drop"] = "{item:11116}，稀有掉落",
		["{npc:10879}, the {object:36078}, beside the bat master"] = "{npc:10879}，{object:36078}，在蝙蝠管理員旁邊",
		["{npc:6522}, the {object:36073}"] = "{npc:6522}，{object:36073}",
		["{npc:7825} stands in the {object:36082}."] = "{npc:7825}站在{object:36082}。",
		["{npc:8390}, the Apothecarium: the vials fill in {zone:1447} later"] = "{npc:8390}，皇家藥劑師協會：瓶子稍後在{zone:1447}裝滿",
		["{npc:9618}, just outside"] = "{npc:9618}，就在外面",
		["{npc:9619} camps in the south-east corner of the crater."] = "{npc:9619}在環形山的東南角紮營。",
		["{npc:9623} then wants a {item:10561}, an {skill:202} item. Skip it unless you have one."] = "{npc:9623}接著會要一個{item:10561}，這是{skill:202}物品。除非你有，否則跳過。",
		["{npc:9998}, at the entrance"] = "{npc:9998}，在入口",
		["{npc:9998}, at the refuge entrance"] = "{npc:9998}，在避難營入口",
		["{quest:3822} walks the caves and mine tunnels of {quest:3821}; if he isn't home, clear the ogres around the entrances until he comes back."] = "{quest:3822}在{quest:3821}的洞穴和礦坑隧道中走動；如果他不在，就清掉入口周圍的巨魔，直到他回來。",
		["{zone:1454} flight master"] = "{zone:1454}的飛行管理員",
} end)()
t.guides["forever/horde/50-60/02-felwood"] = (function() return {
		["Back north to {area:1763}. Fill {npc:10922}'s canteen at the corrupted moonwell in the middle of the southern camp."] = "向北回到{area:1763}。在南方營地中央的腐化月井裝滿{npc:10922}的水壺。",
		["Below ground"] = "地下",
		["Class trainer"] = "職業訓練師",
		["Cross the river east into {area:2627}, the ruined town in the north-west of the {zone:1423}. {npc:12384} sits in a hut at its edge."] = "向東渡河進入{area:2627}，那是{zone:1423}西北部的廢墟城鎮。{npc:12384}坐在城鎮邊緣的一間小屋裡。",
		["Derrington's watchtowers, Vandis' cauldron and {npc:11615}'s barrel are done on a later visit: keep them."] = "德靈頓的瞭望塔、范蒂絲的大鍋和{npc:11615}的木桶會在之後造訪時完成：先保留。",
		["Diseased Grizzlies"] = "生病的灰熊",
		["Diseased Wolves"] = "生病的狼",
		["East of Bloodvenom Post, the cratered vale where the Entropic Beasts and Horrors roam. Kill two of each, then walk to each of the three fel-water craters."] = "在血毒崗哨東邊，熱能野獸和熱能恐獸遊蕩的坑窪山谷。各擊殺兩隻，然後走到三個魔化水坑的每一個。",
		["Follow the road north-west. The south of {area:1763}, around its corrupted moonwell, is held by Shadow Council cultists, adepts, guardsmen and their hounds."] = "沿著道路向西北走。{area:1763}南部的腐化月井周圍，由加德納爾祭司、加德納爾精兵、加德納爾守護者和加德納爾惡犬佔據。",
		["He camps by the {area:202}, south-east of {area:200}."] = "他在{area:200}東南方的{area:202}旁紮營。",
		["Keep the branch: {npc:5770} is in {zone:1456}."] = "保留樹枝：{npc:5770}在{zone:1456}。",
		["Keep {quest:5158}: {npc:5901} is in the {zone:1413}."] = "保留{quest:5158}：{npc:5901}在{zone:1413}。",
		["Keep {quest:6164}: {npc:12384} takes it back on the {zone:1423} guide's {area:2627} stop."] = "保留{quest:6164}：{npc:12384}會在{zone:1423}指南的{area:2627}站收回它。",
		["Keep {quest:8465} for {zone:1452}."] = "保留{quest:8465}，留到{zone:1452}。",
		["Knights and magi work the {area:192}; the medics and hunters camp south of it."] = "血色騎士和血色法師在{area:192}工作；血色醫護員和血色獵人在它南邊紮營。",
		["Northern crater"] = "北方坑洞",
		["Only with 5 Deadwood Headdress Feathers"] = "僅限擁有5根死木頭飾羽毛時",
		["Ride back south past {area:1763} to the corrupted moonwell of the Jadefire satyrs and fill {npc:9996}'s flasket there."] = "向南騎回去經過{area:1763}，前往碧火薩特的腐化月井，在那裡裝滿{npc:9996}的小瓶。",
		["Ride back west over the river and on to the {area:192}; {npc:11610} hides on the hill north-east of it."] = "向西騎回河對岸，繼續前往{area:192}；{npc:11610}躲在它東北方的山丘上。",
		["Ride north along the eastern hills; {npc:1855} lives in a small house by the {area:2619}, at the border with the {zone:1423}."] = "沿著東側山丘向北騎；{npc:1855}住在{area:2619}旁的一間小屋，位於與{zone:1423}的邊界。",
		["Ride north up the road again."] = "再次沿著道路向北騎。",
		["Ride south-west past Felstone Farm and follow the road west back to the {area:152}."] = "向西南騎過費爾斯通農場，沿著道路向西回到{area:152}。",
		["Ride the road south through {zone:1448} to the Sanctuary."] = "沿著道路向南穿過{zone:1448}前往聖地。",
		["Ror stands at the far south end of {area:1761}."] = "洛爾站在{area:1761}的最南端。",
		["Scarlet Crusade"] = "血色十字軍",
		["Southern crater"] = "南方坑洞",
		["Southern {area:1763}"] = "{area:1763}南部",
		["Take the kitten to the same moonwell and release it there with {item:12565}; once it has turned into a {npc:10042}, bring it back to {npc:9996} and click on it to hand it over."] = "把小貓帶到同一個月井，用{item:12565}在那裡放出牠；牠變成{npc:10042}後，把牠帶回給{npc:9996}，點擊牠來交給她。",
		["The Deadwood furbolg village just west of the tunnel. {npc:9462} (56) stands among them. {npc:11557}, a friendly furbolg, sits at the north end of the village."] = "就在隧道西邊的死木熊怪村莊。{npc:9462}（56級）站在牠們之中。友善的熊怪{npc:11557}坐在村莊北端。",
		["The Horde camp just north of {area:1763}."] = "{area:1763}北邊的部落營地。",
		["The Jadefire moonwell"] = "碧火月井",
		["The book lies in the ruined inn of {area:2627}; the undead in the town are 54-56, so pull them one at a time.\nThe Large Termite Mounds stand all over the hills east of {area:2627}. Use the {item:15042} on each mound you pass."] = "書在{area:2627}的廢墟旅店裡；鎮上的不死生物是54-56級，所以一次拉一隻。\n大型白蟻丘遍布{area:2627}東邊的山丘。對經過的每個白蟻丘使用{item:15042}。",
		["The diary lies in the farmhouse, the cabinet stands inside and the outhouse is behind it. A {npc:10816} carries the outhouse key; {npc:10836} comes out when you open the outhouse and carries the cabinet key."] = "日記在農舍裡，櫃子在屋內，廁所在屋後。一隻{npc:10816}帶著廁所鑰匙；打開廁所時{npc:10836}會出來，他身上帶著櫃子鑰匙。",
		["The druids' camp is just past the border."] = "德魯伊的營地就在邊界過去一點。",
		["The road ends at {npc:15395}, outside the {area:1769} tunnel in the far north-east."] = "道路盡頭是{npc:15395}，在東北角的{area:1769}隧道外。",
		["The wolves roam the fields between Andorhal, {area:200} and the {area:202}. Finish them on the ride back east."] = "狼群在安多哈爾、{area:200}和{area:202}之間的田野遊蕩。在往東騎回去的路上把牠們殺完。",
		["The {area:1763} moonwell"] = "{area:1763}月井",
		["Upstairs"] = "樓上",
		["Western crater"] = "西方坑洞",
		["Zeppelin to {zone:1454}"] = "搭飛艇前往{zone:1454}",
		["{area:200} farmhouse"] = "{area:200}農舍",
		["{area:2627}: kill these as you meet them"] = "{area:2627}：遇到就擊殺",
		["{item:12565}, at the Jadefire moonwell"] = "{item:12565}，在碧火月井",
		["{npc:10306}: the owlbeasts are in {zone:1452}"] = "{npc:10306}：梟獸在{zone:1452}",
		["{npc:11554}, at the south edge of the camp"] = "{npc:11554}，在營地南緣",
		["{npc:1855}'s hunts are in the {zone:1423}: keep them for later."] = "{npc:1855}的狩獵任務在{zone:1423}：先保留。",
		["{npc:8659} takes the ravasaur claws from Un'Goro; he stands in the {object:172960}, a short walk from the middle of the city."] = "{npc:8659}收下安戈洛的恐龍爪；他站在{object:172960}，從城市中央走一小段路就到。",
		["{npc:8659}, the {object:172960}"] = "{npc:8659}，{object:172960}",
		["{npc:9529}, on the west side of the Sanctuary"] = "{npc:9529}，在聖地西側",
		["{npc:9529}, on the west side of the camp"] = "{npc:9529}，在營地西側",
		["{npc:9996}'s kitten"] = "{npc:9996}的小貓",
		["{quest:5408}: the {area:2627} undead drop them while you wear the {item:12846}"] = "{quest:5408}：佩戴{item:12846}時，{area:2627}的不死生物會掉落",
		["{zone:1454} flight master"] = "{zone:1454}的飛行管理員",
} end)()
t.guides["forever/horde/50-60/03-winterspring"] = (function() return {
		["Back south to {npc:7775}. Keep the elixir and don't drink it yet: it kills you, and that is how you meet Gaeriyan by {area:976} later."] = "往南回到{npc:7775}那裡。留著藥劑，先別喝：喝了會死，而這正是之後在{area:976}附近見到蓋瑞恩的方法。",
		["Below ground"] = "地下",
		["Chillwind chimaeras"] = "冰風奇美拉",
		["Fly to {area:1099}"] = "飛往{area:1099}",
		["Fly to {area:1637}"] = "飛往{area:1637}",
		["Fly to {area:1638}"] = "飛往{area:1638}",
		["Gregor's quests lead to other zones: keep them."] = "格雷戈的任務會通往其他地區：保留它們。",
		["Ice Thistle yetis"] = "冰薊雪人",
		["In the {object:172958}."] = "在{object:172958}。",
		["Linken's letter"] = "林克的信",
		["Matriarchs and Patriarchs hit hard: pull them one at a time."] = "雪人女王和雪人王打得很痛：一次拉一隻。",
		["Pathfinders, Den Watchers and Totemics share the furbolg camps around the hot springs; Ragged Owlbeasts roam the slopes between them. Kill Totemics first. Save every {item:14047} you loot for Meilosh."] = "冬泉探路者、冬泉巢穴守衛和冬泉圖騰師共同佔據溫泉周圍的熊怪營地；蓬毛梟獸在營地之間的山坡上遊蕩。先殺圖騰師。把你拾取的每一份{item:14047}都留給梅羅什。",
		["Pristine Yeti Horns"] = "完美的雪人角",
		["Raging Owlbeasts"] = "狂怒的梟獸",
		["The chimaeras roam the snowfields south and west of {area:2255}. Stay clear of {area:2245}'s cave: its blue dragonkin are elite."] = "奇美拉在{area:2255}南邊和西邊的雪原上遊蕩。避開{area:2245}的洞穴：裡面的藍龍是精英。",
		["The furbolg village fills the valley north-east of {area:2255}. Kill Shamans first; they heal. {npc:10738} in the cave at the back is elite: stay out."] = "熊怪村莊佔據{area:2255}東北方的山谷。先殺冬泉薩滿；他們會治療。後方洞穴裡的{npc:10738}是精英：不要進去。",
		["The yeti hills start just south-east of {area:2255}. Every yeti drops fur; only Matriarchs and Patriarchs drop horns, so keep those for after the turn-in."] = "雪人山丘從{area:2255}東南方不遠處開始。每隻雪人都會掉落毛皮；只有冰薊雪人女王和冰薊雪人王會掉落角，所以把角留到繳交之後再收集。",
		["The {item:11242} grows inside a ruined building north of {npc:7775}'s camp, east of the harpies' {area:1114}: climb in through the broken part of its wall."] = "{item:11242}生長在{npc:7775}營地北邊、鷹身人的{area:1114}東邊一棟廢墟建築裡：從牆壁的破損處爬進去。",
		["Umi's third prank targets goblins in {area:976} and Un'Goro: keep it for later."] = "烏米的第三個惡作劇目標是{area:976}和安戈洛的哥布林：保留到稍後。",
		["{area:2408} flight master"] = "{area:2408}的飛行管理員",
		["{item:11243}, {npc:7775}'s reward"] = "{item:11243}，{npc:7775}的獎勵",
		["{npc:3033} on {area:1639}; {npc:246344}"] = "{area:1639}的{npc:3033}；{npc:246344}",
		["{npc:7775}, a dwarf, camps in the {area:1137} north-west of {area:1099}. He brews the {item:11243} only from an {item:11242} you bring him."] = "矮人{npc:7775}在{area:1099}西北方的{area:1137}紮營。他只會用你帶來的{item:11242}釀製{item:11243}。",
		["{quest:1123} waits in {zone:1450}: keep it for later."] = "{quest:1123}在{zone:1450}等著：保留到稍後。",
		["{quest:3909} comes from {npc:7775} in {zone:1444}, later in this guide."] = "{quest:3909}來自{zone:1444}的{npc:7775}，在本指南稍後。",
		["{quest:5084} is turned in at the {object:176091} in {zone:1448}, on a later trip."] = "{quest:5084}要在之後前往{zone:1448}時，到{object:176091}繳交。",
		["{quest:8471}, a rare drop from the Winterfall furbolgs"] = "{quest:8471}，冬泉熊怪的稀有掉落",
} end)()
t.guides["forever/horde/50-60/04-azshara"] = (function() return {
		["Cleansed Water goes to the {area:2479} in {zone:1448}: keep it for later."] = "淨化過的水要送到{zone:1448}的{area:2479}：保留到稍後。",
		["Fly to {area:1237}"] = "飛往{area:1237}",
		["Fly to {area:1637}"] = "飛往{area:1637}",
		["Fly to {area:392}"] = "飛往{area:392}",
		["Fly to {zone:1454}; {npc:4485} is in the {object:172958}."] = "飛往{zone:1454}；{npc:4485}在{object:172958}。",
		["Lady Sylvanas holds the {object:36126}."] = "希爾瓦娜斯女士在{object:36126}。",
		["Liv's workshop is at the north end of {area:392}'s docks; {object:149036} stands inside it."] = "莉芙的工作室在{area:392}碼頭北端；{object:149036}就在裡面。",
		["Ride back west to {area:1237}."] = "向西騎回{area:1237}。",
		["Ride east to the ruins on the coast. Fill Cuely's four vials at the tide pools along the shore; Spitelash naga patrol between them."] = "向東騎往海岸上的遺跡。在沿岸的潮池裝滿科雷的四個瓶子；惡鞭納迦在潮池之間巡邏。",
		["The blood elves camp on the cliffs in the north-east, by the {area:1227}."] = "血精靈在東北方{area:1227}旁的懸崖上紮營。",
		["Upstairs"] = "樓上",
		["{npc:15188}, {object:172957}: keep it for {zone:1451}"] = "{npc:15188}，{object:172957}：保留給{zone:1451}",
		["{npc:256386}'s crates"] = "{npc:256386}的箱子",
		["{npc:5901} camps on the shore just north of {area:392}."] = "{npc:5901}在{area:392}北邊不遠處的岸邊紮營。",
		["{npc:8393}, beside him"] = "{npc:8393}，在他旁邊",
		["{npc:8403}, nearby"] = "{npc:8403}，在附近",
		["{npc:8578}'s camp"] = "{npc:8578}的營地",
		["{npc:8659}, the {object:172960}"] = "{npc:8659}，{object:172960}",
		["{quest:5050} goes back to {npc:10778} in the {zone:1422}: keep it."] = "{quest:5050}要交回給{zone:1422}的{npc:10778}：保留此任務。",
		["{zone:1454} flight master"] = "{zone:1454}的飛行管理員",
} end)()
t.guides["forever/horde/50-60/05-eastern-plaguelands"] = (function() return {
		["Back through the tunnel and take the {zone:1452} exit, then ride south to {area:2246}."] = "回到隧道，走{zone:1452}出口，然後向南騎到{area:2246}。",
		["Back to {area:2268}"] = "返回{area:2268}",
		["Below ground"] = "地下",
		["Both quests lead to {zone:1451}: keep them."] = "兩個任務都通往{zone:1451}：先留著。",
		["Careful: {npc:10411} goes invisible when out of combat and calls Rockwing Gargoyles once a fight starts. Only 3 exist and they respawn every 15 min."] = "小心：{npc:10411}脫離戰鬥時會隱形，戰鬥一開始就會召喚石翼石像鬼。總共只有3隻，每15分鐘重生一次。",
		["Class trainer"] = "職業訓練師",
		["Drink the {item:11243} at the graveyard just east of {area:976}: it kills you, and only as a ghost can you see {npc:9299}, in a rocky crevice in the hills due north of it. Talk to him there, then run back to your body and resurrect: the Conspicuous Gravestone he sends you to stands in that graveyard."] = "在{area:976}東邊不遠的墓地喝下{item:11243}：你會死亡，只有變成鬼魂才看得到{npc:9299}，他在墓地正北方丘陵的岩縫裡。在那裡和他交談，然後跑回屍體復活：他要你去找的顯眼的墓碑就在那座墓地裡。",
		["Fly to {area:1638}"] = "飛往{area:1638}",
		["Fly to {area:2268}"] = "飛往{area:2268}",
		["Fly to {area:272}"] = "飛往{area:272}",
		["Fly to {area:976}"] = "飛往{area:976}",
		["Follow the road east from the {zone:1422}, over the river and across the whole {zone:1423}, to the {object:92525}'s chapel in the far east."] = "沿著道路從{zone:1422}向東走，過河並穿越整個{zone:1423}，抵達最東邊{object:92525}的禮拜堂。",
		["Free Darrowshire Spirits: talk to them"] = "解放達隆郡之魂：和它們交談",
		["Frenzied Plaguehounds and Monstrous Plaguebats share the fields around {area:2272} and {area:2271}, south of {area:2273}."] = "狂怒的瘟疫犬和巨型瘟疫蝙蝠共同分布在{area:2273}南邊、{area:2272}和{area:2271}周圍的田野。",
		["Go through {area:1769} and take the {zone:1450} branch of the tunnel. {npc:11801} is in {area:2361}."] = "穿過{area:1769}，走隧道通往{zone:1450}的支線。{npc:11801}在{area:2361}。",
		["Keep {quest:5152}: {npc:10927} lives at {area:197} in the {zone:1422}."] = "保留{quest:5152}：{npc:10927}住在{zone:1422}的{area:197}。",
		["Moontouched Owlbeasts"] = "月光梟獸",
		["Only if a {quest:8471} dropped for you: {npc:11558} waits at the {zone:1448} entrance of {area:1769}, and speaks to you only at Neutral with the Timbermaw."] = "只有在掉落了{quest:8471}時：{npc:11558}在{area:1769}的{zone:1448}入口等著，而且只有在你對木喉熊怪為中立時才會和你交談。",
		["Plaguehound Runts and Plaguebats roam the hills north of the {area:2260}, Carrion Grubs crawl among them; work north toward {area:2627}."] = "瘟疫幼犬和瘟疫蝙蝠在{area:2260}北邊的丘陵遊蕩，腐肉蟲在牠們之間爬行；一路向北往{area:2627}推進。",
		["Ride back south to {area:272} and fly to {area:2268}."] = "向南騎回{area:272}，再飛往{area:2268}。",
		["Ride east to {area:2255} and north out of it; the Moontouched Owlbeasts roam the hills of {area:2241}'s southern slopes. Pull them one at a time."] = "向東騎到{area:2255}再向北出城；月光梟獸在{area:2241}南坡的丘陵遊蕩。一次只拉一隻。",
		["Ride north up the road from {area:272}. {npc:10927}'s house stands by the road at {area:197}, and {npc:10936}'s monument is in the graveyard behind it."] = "從{area:272}沿道路向北騎。{npc:10927}的房子在{area:197}的路旁，{npc:10936}的紀念碑在房子後面的墓地裡。",
		["Ride north-west into Andorhal. {npc:10667} waits in the ruined inn on the west side of town; the skeletons inside are 54-57, so keep to the edges."] = "向西北騎進安多哈爾。{npc:10667}在城鎮西側的旅店廢墟裡等著；裡面的骷髏是54-57級，所以沿著邊緣走。",
		["Ride south from the lodge to {area:2264}, on the road. {item:15447} spoils within ten minutes: kill the town's Scourge quickly and grind the seven pieces with the {item:15454} at once.\nCareful: Unseen Servants call for help within 25 yd once they drop to 40% health. Out of combat they also turn invisible with {spell:10228}. If a call for help happens inside the town, a large number of mobs can join the fight. Fighting near the outskirts lowers this risk.\nWith {quest:5211} in your log (from {npc:11063} at the start of this guide), the Scourge around the town leave Darrowshire Spirits: talk to each one to free it. Free them before you start on the {item:15447}."] = "從小屋沿道路向南騎到{area:2264}。{item:15447}十分鐘內就會腐壞：快速擊殺鎮上的天譴軍團，並立刻用{item:15454}磨碎七份。\n小心：隱形僕從的生命值降到40%時，會向25碼內的同伴求救。脫離戰鬥時，牠們還會用{spell:10228}隱形。如果在鎮內發生求救，可能會有大量怪物加入戰鬥。在城鎮外圍戰鬥可以降低這個風險。\n如果任務日誌中有{quest:5211}（來自本指南開頭的{npc:11063}），鎮子周圍的天譴軍團會留下達隆郡之魂：和每一個交談來解放它們。在開始收集{item:15447}之前先解放它們。",
		["Ride west to the {area:2260}."] = "向西騎到{area:2260}。",
		["Scare {npc:7583} with {item:12928}"] = "用{item:12928}嚇唬{npc:7583}",
		["The Annals lie among the Musty Tomes in Andorhal's town hall; open them until you find the right one."] = "編年史在安多哈爾市政廳的發霉的書本之間；逐一打開直到找到正確的那本。",
		["The doll's head and its two sides lie in the houses around {npc:10926}; join them from your bags."] = "娃娃的頭和兩側身體散落在{npc:10926}周圍的房屋裡；在背包中把它們組合起來。",
		["The pass from Un'Goro comes out at {area:3077}, the graveyard in north-east {zone:1451}. {npc:13220} stands among the graves."] = "從安戈洛來的山道出口在{area:3077}，也就是{zone:1451}東北部的墓地。{npc:13220}站在墳墓之間。",
		["To {area:197}"] = "前往{area:197}",
		["Upstairs"] = "樓上",
		["Use {item:12928} on {npc:7583}, the goblin girl in {area:976}. {npc:10977} and {npc:10978} are scared later in the route."] = "對{area:976}的哥布林女孩{npc:7583}使用{item:12928}。{npc:10977}和{npc:10978}會在路線後段被嚇到。",
		["Zaeldarr lurks just west of {area:2262}."] = "被放逐者札爾達爾潛伏在{area:2262}西邊不遠處。",
		["Zeppelin to {zone:1454}"] = "搭飛艇前往{zone:1454}",
		["a message for {npc:11063} at {area:2268}"] = "給{area:2268}的{npc:11063}的口信",
		["{npc:10926}'s ghost stands in the ruins of {area:2262}, in the south-west."] = "{npc:10926}的鬼魂站在西南方{area:2262}的廢墟中。",
		["{npc:10927}, upstairs"] = "{npc:10927}，在樓上",
		["{npc:11140} the ghost stands by a hut in {area:2627}, in the north-west corner."] = "鬼魂{npc:11140}站在西北角{area:2627}的一間小屋旁。",
		["{npc:15193}'s champion holds the {area:2260} farmhouse, north of the {area:2261}."] = "{npc:15193}的勇士守在{area:2261}北邊的{area:2260}農舍。",
		["{npc:3033} on {area:1639}; {npc:246344}"] = "{area:1639}的{npc:3033}；{npc:246344}",
		["{npc:7771} camps by the {area:1336} road, south of {area:976}."] = "{npc:7771}在{area:976}南邊、通往{area:1336}的路旁紮營。",
		["{quest:3914} goes back to {npc:8737} in Un'Goro: keep it."] = "{quest:3914}要交回安戈洛環形山的{npc:8737}：先留著。",
		["{quest:5168}'s items lie in the later Plaguelands zones: keep it."] = "{quest:5168}的物品在之後的瘟疫之地區域：先留著。",
		["{quest:5211}'s spirits come with the {area:2264} stop later in this guide: keep it."] = "{quest:5211}的靈魂會在本指南稍後前往{area:2264}時處理：先留著。",
		["{zone:1454} flight master"] = "{zone:1454}的飛行管理員",
} end)()
t.guides["forever/horde/50-60/06-silithus"] = (function() return {
		["A torn scroll lies at the entrance of the {area:2261}, the crypt south of the {area:2260}."] = "一張撕破的卷軸在{area:2260}南邊的地穴{area:2261}入口。",
		["Andorhal watchtowers and silos"] = "安多哈爾的哨塔與穀倉",
		["Back to Southwind and climb the tower. Stirring the hive at the top brings out Hive'Ashi Ambushers; one carries the {item:17346}."] = "回到南風村並爬上塔。攪動塔頂的蟲巢會引出亞什伏擊者；其中一隻帶著{item:17346}。",
		["Back to {area:3425}"] = "回到{area:3425}",
		["Below ground"] = "地下",
		["Class trainer"] = "職業訓練師",
		["Dredge Crushers and Pincers"] = "掘泥摧毀者與巨鉗蠍",
		["Dredge Strikers, Stonelash Scorpids and Sand Skitterers share the sands just north of the hold."] = "掘泥打擊者、石鞭蠍和掠沙蜘蛛都在城堡北邊不遠的沙地上。",
		["East along the road, {npc:11077} guards the cauldron at {area:200}."] = "沿著道路往東，{npc:11077}守著{area:200}的大鍋。",
		["Escort {npc:9999}"] = "護送{npc:9999}",
		["Flayers and Rock Stalkers"] = "掠奪者與石行蜘蛛",
		["Fly to {area:1637}"] = "飛往{area:1637}",
		["Fly to {area:976}. Still carrying {quest:2741}? The machine stands in the middle of town."] = "飛往{area:976}。身上還有{quest:2741}嗎？機器就在鎮中央。",
		["Hameya's mound"] = "哈米亞的土堆",
		["Hameya's scroll"] = "哈米亞的卷軸",
		["Head north along the western dunes; Dredge Crushers and Stonelash Pincers range from here back toward the hold."] = "沿著西側沙丘往北走；從這裡到城堡一帶都有掘泥摧毀者和石鞭巨鉗蠍。",
		["Keep the bait: {npc:9684} is level 56, and the second loop passes his lair."] = "保留誘餌：{npc:9684}是56級，第二圈路線會經過牠的巢穴。",
		["Keep {quest:3942}: {npc:9116} is at the {area:2479}, on the next guide's way through {zone:1448}."] = "保留{quest:3942}：{npc:9116}在{area:2479}，下一份指南經過{zone:1448}時會路過。",
		["Mark {npc:10902} with the {item:12815}"] = "用{item:12815}標記{npc:10902}",
		["Mark {npc:10903} with the {item:12815}"] = "用{item:12815}標記{npc:10903}",
		["Mark {npc:10904} with the {item:12815}"] = "用{item:12815}標記{npc:10904}",
		["Mark {npc:10905} with the {item:12815}"] = "用{item:12815}標記{npc:10905}",
		["Radley and Durgen"] = "萊德雷與杜爾根",
		["Ride east to {area:537}, climb it and use {npc:10541} at the lava vent near the top, then ride back west to {npc:10302}."] = "向東騎往{area:537}，爬上去，在山頂附近的熔岩噴口使用{npc:10541}，然後騎回西邊找{npc:10302}。",
		["Ride east to {npc:1855}'s hut by the {area:2619} and hear him out."] = "往東騎到{area:2619}旁{npc:1855}的小屋，聽他把話說完。",
		["Ride north-east to {area:3077}; you leave {zone:1451} through the pass beside it."] = "往東北騎到{area:3077}；從旁邊的山道離開{zone:1451}。",
		["Ride north-east to {area:3447}."] = "往東北騎到{area:3447}。",
		["Ride north-west to {npc:1855}'s hut."] = "往西北騎到{npc:1855}的小屋。",
		["Ride south into Andorhal. {npc:10667} waits in the ruined inn on the west side of town. Stand in the doorway of each of the four towers with the {item:12815} to mark it; keep to the edges of town. Use the {item:12627} by the silos in the middle of town to bring out Temporal Parasites."] = "往南騎進安多哈爾。{npc:10667}在鎮西側的旅店廢墟裡等著。帶著{item:12815}站在四座哨塔各自的門口來標記；沿著鎮的外緣走。在鎮中央的穀倉旁使用{item:12627}，引出時光寄生蟲。",
		["Ride south-east to {area:3447} under the Un'Goro cliffs."] = "往東南騎到安戈洛懸崖下的{area:3447}。",
		["Ride south-west to {npc:10667} in Andorhal."] = "往西南騎到安多哈爾找{npc:10667}。",
		["Ride west to the Horde camp north of {area:2744}."] = "往西騎到{area:2744}北邊的部落營地。",
		["Scourge Champions"] = "天災勇士",
		["Scourge Champions roam the {area:2270}, north of the chapel. Pass {npc:11063}'s {item:13156} over each one you kill: the skulls that resonate are the ones he wants."] = "天災勇士在禮拜堂北邊的{area:2270}遊蕩。每殺一隻就用{npc:11063}的{item:13156}掃過屍體：產生共鳴的頭骨就是他要的。",
		["Silithyst geysers erupt across the southern desert. Walk into the Silithyst one leaves behind and carry it to the Horde's Silithyst Extractor at Kirika's camp; fighting or mounting drops it."] = "南部沙漠各處會有希利蘇斯之塵間歇泉噴發。走進噴發後留下的希利蘇斯之塵，把它帶到奇立卡營地的部落希利蘇斯之塵提取器；戰鬥或騎乘坐騎會讓它掉落。",
		["Stonelash Flayers and Rock Stalkers roam the dunes south-west of Kirika's camp."] = "石鞭掠奪者和石行蜘蛛在奇立卡營地西南的沙丘上遊蕩。",
		["The glowing tablet fragments lie around the Twilight camp in the far north-west; the Dust Stormers and Desert Rumblers there drop them too."] = "發光的石碑碎片散落在極西北的暮光營地周圍；那裡的灰塵風暴和沙漠奔行者也會掉落。",
		["The libram lies further north, on the way to {area:190}."] = "聖契在更北邊，前往{area:190}的路上。",
		["The satchel lies in the mountains of the far south, past Bronzebeard's Encampment. Deathclasp, an elite scorpid, patrols near it: grab it while he is away."] = "背包在極南方的山裡，過了銅鬚營地就是。精英蠍子死亡彎鉤在附近巡邏：趁牠離開時拿走。",
		["The shield lies at {area:201}, south of {npc:1855}'s hut."] = "盾牌在{npc:1855}小屋南邊的{area:201}。",
		["The spare texts from the cultists"] = "從信徒身上多拿的文件",
		["Twilight Vanguard"] = "暮光先鋒",
		["Upstairs"] = "樓上",
		["Use {npc:10980} on {npc:10977}"] = "對{npc:10977}使用{npc:10980}",
		["{npc:10302} sends you to {npc:9298} in {zone:1452}: keep it."] = "{npc:10302}要你去找{zone:1452}的{npc:9298}：保留此任務。",
		["{npc:10302} the goblin sits at {area:543}, just east of the pylon."] = "哥布林{npc:10302}坐在{area:543}，就在水晶塔東邊。",
		["{npc:10667}'s Battle of Darrowshire ends against elites. Skip it."] = "{npc:10667}的達隆郡之戰最後要對付精英。跳過。",
		["{npc:15200} holds the camp in the west."] = "{npc:15200}守在西邊的營地。",
		["{npc:15306}, on the west side of the Hold"] = "{npc:15306}，在城堡西側",
		["{npc:9619} now asks for {npc:9622}'s pelt, back in the north-east cave: skip it."] = "{npc:9619}現在要{npc:9622}的毛皮，在東北方的洞穴裡：跳過。",
		["{npc:9684}'s lair is just south of the pylon. Use {npc:9619}'s bait there; {npc:9684} is level 56 and hits hard, so start at full health."] = "{npc:9684}的巢穴就在水晶塔南邊。在那裡使用{npc:9619}的誘餌；{npc:9684}是56級且攻擊力強，滿血再開始。",
		["{npc:9999} sits on the ridge, lost and exhausted."] = "{npc:9999}坐在山脊上，迷路又筋疲力盡。",
} end)()
t.guides["forever/horde/50-60/07-felwood"] = (function() return {
		["Any Winterfall furbolg can carry the beads; the camps just south of {npc:11556} are the closest."] = "任何冬泉熊怪都可能帶著珠串；{npc:11556}南邊的營地最近。",
		["Back into the Timbermaw tunnel and take the {zone:1452} exit; {npc:9298} camps by the hot springs just outside."] = "回到木喉隧道，從{zone:1452}出口出去；{npc:9298}就在出口外的溫泉旁紮營。",
		["Back south to the Sanctuary, a short ride."] = "向南回到聖地，路程很短。",
		["Below ground"] = "地下",
		["Class trainer"] = "職業訓練師",
		["Corrupted Soul Shards from the cultists, {quest:5887}"] = "從教徒身上取得腐化的靈魂碎片，{quest:5887}",
		["Dungeon instead of grinding"] = "以地城代替練等",
		["Fly to {area:431} and ride north-west along the road out of {zone:1440} into {zone:1448}. The {area:2479} is the druids' camp just past the border."] = "飛往{area:431}，沿著道路向西北離開{zone:1440}進入{zone:1448}。{area:2479}就是過了邊界不遠的德魯伊營地。",
		["From Krakle in Un'Goro"] = "來自安戈洛的克拉蘭克",
		["Frostfire Winterfall camp"] = "冰火溫泉的冬泉營地",
		["Grind to 60"] = "練到60級",
		["In the {object:172961}."] = "在{object:172961}。",
		["In {zone:1454}: fly from {area:2255}"] = "在{zone:1454}：從{area:2255}飛過去",
		["In {zone:1456}: fly from {area:2255}"] = "在{zone:1456}：從{area:2255}飛過去",
		["On the way back south to {npc:10922}, {npc:9529} takes the shards on the west side of the Sanctuary."] = "在向南返回{npc:10922}的路上，到聖地西側把碎片交給{npc:9529}。",
		["Optional. Running {area:2279}, {area:2057}, Lower Blackrock Spire or {area:1584} with a group instead of grinding gets you there faster."] = "可選。和小隊打{area:2279}、{area:2057}、黑石塔下層或{area:1584}代替練等，能更快達到目標。",
		["Optional: with a group, a 55-60 dungeon replaces the grind below."] = "可選：有小隊的話，一個55-60級地城可以取代下面的練等。",
		["Ride back west to {area:2246}."] = "向西騎回{area:2246}。",
		["Ride east along the road to {area:2255}."] = "沿著道路向東騎往{area:2255}。",
		["Ride east, then south down {area:2249}. The Frostmaul giants there are elite level 59: keep to the middle and keep moving. The strange source is at the mouth of {area:2256}, at the south end."] = "向東騎，然後沿著{area:2249}向南走。那裡的霜槌巨人是59級精英：走在中間並持續移動。奇怪的來源在南端的{area:2256}入口。",
		["Ride north along the road, past {area:1763}, to {area:1997}."] = "沿著道路向北騎，經過{area:1763}，前往{area:1997}。",
		["South to the Sanctuary once more."] = "再次向南前往聖地。",
		["The quests run out here. Rabid Shardtooths prowl {area:2249} in southern {zone:1452}, south of the road from {area:2255}."] = "任務到這裡就沒了。瘋狂的碎齒熊在{zone:1452}南部、{area:2255}出來的道路南邊的{area:2249}徘徊。",
		["The {area:2479}"] = "{area:2479}",
		["Through the Timbermaw tunnel to {zone:1450}. {npc:11939} reads in a house in {area:2361}."] = "穿過木喉隧道前往{zone:1450}。{npc:11939}在{area:2361}的一間房子裡看書。",
		["Zeppelin to {zone:1454}"] = "搭飛艇前往{zone:1454}",
		["grind on {npc:7446} at {area:2249}, {zone:1452}"] = "在{zone:1452}的{area:2249}擊殺{npc:7446}練等",
		["{npc:10306}'s next {quest:4741} would bring you back here from {zone:1452}. Skip it."] = "{npc:10306}接下來的{quest:4741}會讓你從{zone:1452}跑回這裡。跳過。",
		["{npc:11801}'s Shards of the Felvine needs {area:2577}. Skip it."] = "{npc:11801}的「魔藤碎片」需要{area:2577}。跳過。",
		["{npc:9116}'s Silver Heart needs an {item:11173} from northern {zone:1448} and a ride back here. Skip it."] = "{npc:9116}的「銀爪鐵心」需要{zone:1448}北部的{item:11173}，還要騎回這裡。跳過。",
		["{npc:9298} next sends you after {npc:10738}, an elite in his cave. Skip it."] = "{npc:9298}接著會派你去對付洞穴裡的精英{npc:10738}。跳過。",
		["{npc:9529} stands on the west side of the Sanctuary, the way out to {area:1763}. With {quest:4102} done, her {quest:5887} asks for six Corrupted Soul Shards: the Shadow Council cultists in {area:1763} and {area:1770} drop them about one kill in three, and you fight dozens of them for {npc:10922}."] = "{npc:9529}站在聖地西側，也就是前往{area:1763}的出口。完成{quest:4102}後，她的{quest:5887}需要六個腐化的靈魂碎片：{area:1763}和{area:1770}的暗影議會教徒大約每殺三個掉落一個，而你為了{npc:10922}要打上幾十個。",
		["{zone:1454} flight master"] = "{zone:1454}的飛行管理員",
} end)()
t.guides["forever/horde/orc/01-durotar"] = (function() return {
		["Armored Scorpids crawl over the plains west of {area:362}. Tame one, then return to {npc:3171}."] = "硬甲蠍在{area:362}西邊的平原上爬行。馴服一隻，然後回到{npc:3171}那裡。",
		["Back to the Den"] = "回到大獸穴",
		["Back to {area:362}."] = "回到{area:362}。",
		["Below ground"] = "地下",
		["Burning Blade cultists hold the caves of {quest:827}; any of them drops a {item:4871}. {npc:3204}, a level 14 warlock, stands deep inside and drops the {item:4903}."] = "燃刃氏族的教徒佔據{quest:827}的洞穴；他們都會掉落{item:4871}。{npc:3204}是14級的術士，站在深處，會掉落{item:4903}。",
		["Class trainer"] = "職業訓練師",
		["Felstalkers roam the slope below the cave, on the valley's north side."] = "地獄捕獵者在洞穴下方的山坡上遊蕩，位於山谷北側。",
		["Free {npc:275811} and see her safely out of the crag"] = "釋放{npc:275811}，並護送她安全離開峭壁",
		["Head south through the isles. The Loa idols lie all over the southern isles; Voodoo and Hexed Trolls hold them and drop the Hexed Pendants. {quest:826} and Minshina's cage are on the southernmost isle."] = "向南穿過群島。洛阿神像遍布南部島嶼；巫毒食人妖和被施妖術的食人妖守著它們，並掉落妖術墜飾。{quest:826}和明希納的囚籠在最南端的島上。",
		["Inside the cave, go straight on at the first split, then right and follow the stream on your left to the waterfall: the pick glows by the water, behind a column of rock."] = "進入洞穴後，在第一個岔路直走，然後往右，沿著左手邊的溪流走到瀑布：鎬在水邊發光，在一根石柱後面。",
		["Inside the cave, keep to the right wall all the way round, over the stream: {npc:3183} waits at the end."] = "進入洞穴後，一路沿著右側牆壁繞行，越過溪流：{npc:3183}在盡頭等著。",
		["Misha's hut stands south of the lizards. The crocolisks along the {area:814} to the west carry {item:4891}."] = "米莎的小屋在蜥蜴的南邊。西邊{area:814}沿岸的鱷魚身上帶著{item:4891}。",
		["Prickly pears"] = "仙人掌果",
		["Quilboars and scouts hold the huts west of town; dustrunners and battleguards hold the camps farther west."] = "鋼鬃野豬人和鋼鬃斥候佔據城鎮西邊的小屋；鋼鬃傳令兵和鋼鬃衛兵佔據更西邊的營地。",
		["Spitelash naga"] = "惡鞭納迦",
		["Tame it with the {item:15908}"] = "用{item:15908}馴服牠",
		["The keep stands on the coast south-east of {area:362}. The raiders' axe, bow and shield lie on its outskirts. Sailors and marines drop the {item:4870}. {npc:3192} waits at the top of the keep; his key opens the chest beside him, which holds the {item:4881}."] = "城堡位於{area:362}東南方的海岸上。襲擊者的斧頭、弓和盾牌在城堡外圍。庫爾提拉斯水手和水兵會掉落{item:4870}。{npc:3192}在城堡頂端等候；他的鑰匙可以打開他旁邊的箱子，裡面有{item:4881}。",
		["The prickly pears grow among the quilboar huts just west of town."] = "仙人掌果生長在城鎮西邊的野豬人小屋之間。",
		["The weapons lie around the Den and the training grounds; the Mottled Boars roam the whole valley floor."] = "武器散落在大獸穴和訓練場周圍；雜斑野豬在整個谷底遊蕩。",
		["The {object:58595} stands in {area:817}, among the cultists you just fought."] = "{object:58595}在{area:817}裡，就在你剛才打過的教徒之間。",
		["To {zone:1454}"] = "前往{zone:1454}",
		["Training weapons and boars"] = "訓練武器與野豬",
		["Upstairs"] = "樓上",
		["Wade across to the northern Echo Isle. The Matriarch prowls among the raptors there.\nDurotar Tigers roam the isle as well as the shore south of Sen'jin, and the Taillasher eggs sit in nests on the isles and along the beach."] = "涉水到北邊的回音群島。女族長在那裡的迅猛龍之間徘徊。\n杜洛塔猛虎在島上以及森金村南邊的海岸遊蕩，鞭尾蜥蜴的蛋就在群島上和海灘沿岸的巢裡。",
		["Wake {quest:5441} with the {item:16114}"] = "用{item:16114}叫醒{quest:5441}",
		["the {object:654925} on the ground beside her"] = "她旁邊地上的{object:654925}",
		["{area:366} lies west of Sen'jin. The three attack plans sit on the ground among the centaur tents. {npc:275811} is held at the crag as well."] = "{area:366}在森金村西邊。三份進攻計畫放在半人馬帳篷之間的地上。{npc:275811}也被關在峭壁那裡。",
		["{area:817}'s mouth"] = "{area:817}入口",
		["{npc:10176}, where you start"] = "{npc:10176}，在你的出生點",
		["{npc:265809} camps just south of {area:362}. Sit by his campfire (/sit) until the {spell:1229451} buff appears. With a profession learned, {npc:265809} also offers its Camping 101, which its trainer takes: in {area:362} or in {zone:1454} at the start of the next guide."] = "{npc:265809}在{area:362}南邊紮營。坐在他的營火旁（/sit），直到出現{spell:1229451}增益效果。學會專業技能後，{npc:265809}也會提供他的露營入門，交給該專業的訓練師：在{area:362}，或在下一份指南開頭的{zone:1454}。",
		["{npc:265809}'s campfire"] = "{npc:265809}的營火",
		["{npc:265809}: for {npc:11025}"] = "{npc:265809}：交給{npc:11025}",
		["{npc:265809}: for {npc:11046}"] = "{npc:265809}：交給{npc:11046}",
		["{npc:265809}: for {npc:11066}"] = "{npc:265809}：交給{npc:11066}",
		["{npc:265809}: for {npc:2855}"] = "{npc:265809}：交給{npc:2855}",
		["{npc:265809}: for {npc:3175}"] = "{npc:265809}：交給{npc:3175}",
		["{npc:265809}: for {npc:3365}"] = "{npc:265809}：交給{npc:3365}",
		["{npc:265809}: for {npc:3404}"] = "{npc:265809}：交給{npc:3404}",
		["{npc:265809}: for {npc:5943}"] = "{npc:265809}：交給{npc:5943}",
		["{npc:265809}: for {npc:7088}"] = "{npc:265809}：交給{npc:7088}",
		["{npc:266881}: enchanters only, the residue is disenchanted from Hexed Pendants"] = "{npc:266881}：僅限附魔師，殘渣要從妖術墜飾分解取得",
		["{npc:275657} stands on the shore east of {area:362}. The trident, banner and dagger lie on the beach around him."] = "{npc:275657}站在{area:362}東邊的岸上。三叉戟、旗幟和匕首散落在他周圍的海灘上。",
		["{npc:3102} hooves"] = "{npc:3102}的蹄子",
		["{npc:3142}, back in {area:362}"] = "{npc:3142}，回到{area:362}",
		["{npc:3142}: {npc:275666}, an elite sea giant"] = "{npc:3142}：{npc:275666}，一個精英海巨人",
		["{npc:3143} stands just inside the cave mouth; {npc:3159} at the back of the cave behind him."] = "{npc:3143}就站在洞口內；{npc:3159}在他身後的洞穴深處。",
		["{npc:3143} waits inside the Den, the building just west of {npc:10176}."] = "{npc:3143}在大獸穴裡等候，就是{npc:10176}西邊的那棟建築。",
		["{npc:3147}, in the watchtower"] = "{npc:3147}，在瞭望塔裡",
		["{npc:3153}, the warrior trainer beside the Den"] = "{npc:3153}，大獸穴旁的戰士訓練師",
		["{npc:3154}, the hunter trainer beside the Den"] = "{npc:3154}，大獸穴旁的獵人訓練師",
		["{npc:3155}, the rogue trainer in the Den"] = "{npc:3155}，大獸穴裡的盜賊訓練師",
		["{npc:3156}, the warlock trainer at the back of the cave"] = "{npc:3156}，洞穴深處的術士訓練師",
		["{npc:3157}, the shaman trainer beside the Den"] = "{npc:3157}，大獸穴旁的薩滿訓練師",
		["{npc:3287} lies wounded at the foot of the hills north-west of the Den."] = "{npc:3287}受傷躺在大獸穴西北方的山腳下。",
		["{npc:3294}, by the inn"] = "{npc:3294}，在旅店旁",
		["{npc:5875} stands in the {object:172960}, the canyon under the {object:172982}. Hand him the {item:6535}, then use the {item:7464} on the summoning circle beside him and defeat the voidwalker to bind it."] = "{npc:5875}站在{object:172960}，也就是{object:172982}下方的峽谷。把{item:6535}交給他，然後在他旁邊的召喚法陣使用{item:7464}，擊敗虛空行者以束縛它。",
		["{npc:5884}, the mage trainer, at the entrance to the Den"] = "{npc:5884}，法師訓練師，在大獸穴入口",
		["{npc:5887} stands outside the Den. {area:639} is the hill just south of it: drink the {item:6635} there to see the {npc:5891}, then take the {item:6656} back to {npc:5887}."] = "{npc:5887}站在大獸穴外。{area:639}就是它南邊的山丘：在那裡喝下{item:6635}以看見{npc:5891}，然後把{item:6656}帶回給{npc:5887}。",
		["{npc:5887}: {npc:5873} and your {item:5175}"] = "{npc:5887}：{npc:5873}和你的{item:5175}",
		["{npc:5891}, on {area:639}"] = "{npc:5891}，在{area:639}上",
		["{npc:6786} stands on the road at the valley's eastern exit."] = "{npc:6786}站在山谷東側出口的道路上。",
		["{npc:9796}, by the cooking fire"] = "{npc:9796}，在烹飪火堆旁",
		["{quest:828} camps on the hill west of the naga beach, south of {quest:827}."] = "{quest:828}在納迦海灘西邊的山丘上紮營，位於{quest:827}南邊。",
		["{zone:1454}'s main gate is just west of {area:817}. {npc:5875} stands in the {object:172960}, the canyon under the {object:172982}."] = "{zone:1454}的正門就在{area:817}西邊。{npc:5875}站在{object:172960}，就是{object:172982}下方的峽谷。",
} end)()
t.guides["forever/horde/skyborne/01-zephras-isle"] = (function() return {
		["/sit by {npc:263664}'s campfire until you get {spell:1229451}"] = "在{npc:263664}的營火旁 /sit，直到獲得{spell:1229451}",
		["Aanders and the fallen guards are just south-west of the tower. Take Raani's feather and the Shadowsong signet from the bodies."] = "天空祭司安德斯和陣亡的守衛就在塔的西南方不遠處。從屍體上取得菈妮的幸運羽毛和影歌家族徽記。",
		["Back at {quest:92529}: Stormcallers and {npc:251662} fill the village, the Supply Caches stand among the houses and {npc:251966} waits at its south-east end."] = "回到{quest:92529}：奧拉凱斯風暴召喚者和{npc:251662}遍布村莊，補給貯藏箱放在房屋之間，{npc:251966}在村莊東南端等著。",
		["Back to {area:16635}"] = "返回{area:16635}",
		["Back to {area:16638}"] = "返回{area:16638}",
		["Back to {npc:268592}. Wait for him to light the {npc:268762}, then carry the flame straight to the {npc:268679} beside {npc:252382} in {area:16638} before the timer runs out."] = "回去找{npc:268592}。等他點燃{npc:268762}，然後在計時結束前把火焰直接帶到{area:16638}中{npc:252382}身旁的{npc:268679}。",
		["Below ground"] = "地下",
		["Cast {spell:1259686} near the {object:460001}"] = "在{object:460001}附近施放{spell:1259686}",
		["Class trainer"] = "職業訓練師",
		["Find {npc:258130}"] = "找到{npc:258130}",
		["Follow the road south to {area:16624}, in the middle of the isle. {npc:251523} stands on its east side, {npc:251902} in the middle, {npc:254089} just north-west of her, {npc:263664} by the campfire on the west side. With a profession learned, {npc:263664} also offers its Camping 101: its trainer stands in the village."] = "沿道路向南前往島嶼中部的{area:16624}。{npc:251523}站在村莊東側，{npc:251902}在中央，{npc:254089}在她西北方不遠處，{npc:263664}在西側的營火旁。學會專業技能後，{npc:263664}也會提供對應的露營入門任務：該專業的訓練師就在村裡。",
		["Head north into {area:16631}; {npc:257944} camps at its southern edge."] = "向北進入{area:16631}；{npc:257944}在森林南緣紮營。",
		["Head south-west to the {area:17674}. {npc:252155} is at the top; the {item:254871} lies beside him."] = "向西南前往{area:17674}。{npc:252155}在塔頂；{item:254871}就在他身旁。",
		["Heal the injured druids in the Nightfang Den"] = "在Nightfang Den治療受傷的德魯伊",
		["Listen to {npc:252448}'s story"] = "聆聽{npc:252448}的故事",
		["Listen to {npc:256083}"] = "聆聽{npc:256083}",
		["Northern {zone:1412}"] = "{zone:1412}北部",
		["Pesky Cirrusflies and {npc:250873} roam the grove just south-east of the village."] = "討厭的捲雲蜂和{npc:250873}在村莊東南方的樹林中遊蕩。",
		["Raw Windstones"] = "原始風石",
		["Skyhoppers"] = "空躍者",
		["Skyhoppers hop about the fields just west of Valennia."] = "空躍者在維菈妮雅西邊不遠的田野中跳來跳去。",
		["Spread the {item:278078} off {area:1641}"] = "在{area:1641}撒下{item:278078}",
		["Stormapples and flutterfly dust lie all over the orchard; Hungry Bandits raid it. Galestriders graze in the fields east of it. The broken construct floats at the orchard's north edge."] = "熟透的風暴蘋果和振翼蝶粉末散落在果園各處；飢餓的強盜正在洗劫果園。逐風者在果園東邊的田野吃草。損壞的構造體漂浮在果園北緣。",
		["Tell {npc:252800} you're ready"] = "告訴{npc:252800}你準備好了",
		["The Al'Aketh camp"] = "奧拉凱斯營地",
		["The Raw Windstones are blue crystals on the slopes around the village."] = "原始風石是村莊周圍山坡上的藍色水晶。",
		["The orchard"] = "果園",
		["The queen hovers at the south-east end of the grove, on your way back from the stones."] = "蜂后在樹林的東南端盤旋，就在你從立石回來的路上。",
		["The standing stones"] = "立石",
		["The turncoat"] = "叛徒",
		["The {area:16629}"] = "{area:16629}",
		["The {area:16629} is north of {area:16638}. Fight through the guards up to {npc:253576} at its east side."] = "{area:16629}在{area:16638}北邊。一路殺穿守衛，前往東側的{npc:253576}。",
		["The {area:17674}"] = "{area:17674}",
		["The {area:17675}"] = "{area:17675}",
		["The {object:148418}"] = "{object:148418}",
		["To {zone:1454}"] = "前往{zone:1454}",
		["Upstairs"] = "樓上",
		["Use the {item:278078} at the ceremonial mat and burner on the south-facing cliff of {area:1641}."] = "在{area:1641}朝南的懸崖上，對儀式墊和香爐使用{item:278078}。",
		["You leave the isle for good. {npc:259119} waits where the airship lands."] = "你將永遠離開這座島。{npc:259119}在飛艇降落處等著。",
		["You wake in {area:16635}, in the north of the isle. {npc:251362} stands by the path, {npc:251361} at the village centre."] = "你在島嶼北部的{area:16635}醒來。{npc:251362}站在小徑旁，{npc:251361}在村莊中央。",
		["search the dead cultist in the house"] = "搜查房子裡死去的教徒",
		["search the wardrobe"] = "搜查衣櫃",
		["talk to {npc:251684}"] = "與{npc:251684}交談",
		["talk to {npc:251902}"] = "與{npc:251902}交談",
		["talk to {npc:251968}"] = "與{npc:251968}交談",
		["talk to {npc:252155}"] = "與{npc:252155}交談",
		["talk to {npc:252476}"] = "與{npc:252476}交談",
		["talk to {npc:253844}"] = "與{npc:253844}交談",
		["talk to {npc:257554}"] = "與{npc:257554}交談",
		["the bounty board"] = "懸賞告示板",
		["{area:16624} turn-ins"] = "{area:16624}繳交任務",
		["{area:16635} turn-ins"] = "{area:16635}繳交任務",
		["{area:16663} is west of {area:16638} along the coast road."] = "{area:16663}在{area:16638}西邊，沿海岸道路前往。",
		["{item:265105} grows around {npc:257944}'s camp and Shriekings fly over it. The Al'Aketh camp east of her holds the {item:265141}."] = "{item:265105}生長在{npc:257944}營地周圍，影風始祖鳥在上空飛翔。她東邊的奧拉凱斯營地裡有{item:265141}。",
		["{item:278079}, from {npc:3014}"] = "{item:278079}，向{npc:3014}購買",
		["{item:278080}, from {npc:3012}"] = "{item:278080}，向{npc:3012}購買",
		["{item:278081}, from {npc:3005}"] = "{item:278081}，向{npc:3005}購買",
		["{item:278083}, from {npc:3027}"] = "{item:278083}，向{npc:3027}購買",
		["{npc:249363} stands at the {area:17678}, east of the village. {npc:251143} and Al'Aketh Converts gather just north of her. The {object:460001} is just north-east of her: cast your {spell:1259686} racial ability next to it."] = "{npc:249363}站在村莊東邊的{area:17678}。{npc:251143}和奧拉凱斯皈依者聚集在她北邊不遠處。{object:460001}就在她的東北方：在它旁邊施放你的種族技能{spell:1259686}。",
		["{npc:251361}'s errands"] = "{npc:251361}的差事",
		["{npc:251361}: a note from your trainer"] = "{npc:251361}：訓練師留給你的字條",
		["{npc:251361}: examine the {item:282418}"] = "{npc:251361}：檢查{item:282418}",
		["{npc:251361}: read the {item:9547}"] = "{npc:251361}：閱讀{item:9547}",
		["{npc:251361}: the {item:4100}"] = "{npc:251361}：{item:4100}",
		["{npc:251373}, the druid trainer, on the ground floor of the tree behind {npc:251361}"] = "德魯伊訓練師{npc:251373}，在{npc:251361}身後那棵樹的底層",
		["{npc:251374}: {npc:5873} and your {item:5175}"] = "{npc:251374}：{npc:5873}和你的{item:5175}",
		["{npc:251389}, in the watchtower"] = "{npc:251389}，在瞭望塔內",
		["{npc:251964}, in the watchtower"] = "{npc:251964}，在瞭望塔內",
		["{npc:252382}: {npc:2523}, your {item:5176} and the {item:263412}"] = "{npc:252382}：{npc:2523}、你的{item:5176}和{item:263412}",
		["{npc:252448} and {npc:256083}"] = "{npc:252448}與{npc:256083}",
		["{npc:253622}, {npc:258130} and {npc:258134} are in the cult camp east of {npc:257944}. {npc:254151} stands at its edge. Haalien also drops a {quest:94490}: read it to start the next quest. For {quest:94489}, enter the Nightfang Den, heal 7 injured druids and find {npc:258130}."] = "{npc:253622}、{npc:258130}和{npc:258134}在{npc:257944}東邊的教派營地。{npc:254151}站在營地邊緣。哈利安也會掉落{quest:94490}：閱讀它以開始下一個任務。{quest:94489}：進入Nightfang Den，治療7名受傷的德魯伊並找到{npc:258130}。",
		["{npc:254589} lurks south of the village, among the Prideclaws. {npc:254589} is elite: grouping up is advised."] = "{npc:254589}潛伏在村莊南邊的群爪之間。{npc:254589}是精英：建議組隊。",
		["{npc:256083} stands in the {area:16626} just north-west of town."] = "{npc:256083}站在城鎮西北方不遠的{area:16626}。",
		["{npc:256247} waits on the road north of {area:16638}, towards the {area:16629}."] = "{npc:256247}在{area:16638}北邊、通往{area:16629}的路上等著。",
		["{npc:257196} holds the {item:263993} on the west side of the shrine."] = "{npc:257196}在神殿西側持有{item:263993}。",
		["{npc:257944} again"] = "再次找{npc:257944}",
		["{npc:257944}, last time"] = "最後一次找{npc:257944}",
		["{npc:259118}, by the landing: for {npc:3033} in {zone:1456}"] = "降落處旁的{npc:259118}：給{zone:1456}的{npc:3033}",
		["{npc:269068} wants tauren incense: buy its four parts from {npc:3014} the herbalist, {npc:3012} the enchanting supplier, {npc:3005} the leatherworking supplier and {npc:3027} the cooking supplier, then combine them into {item:278078}."] = "{npc:269068}想要牛頭人的薰香：向草藥商{npc:3014}、附魔供應商{npc:3012}、製皮供應商{npc:3005}和烹飪供應商{npc:3027}購買四種材料，然後合成{item:278078}。",
		["{quest:92529} lies south of Shen'dar. {npc:257065} meets you at its edge; search the wardrobe in the house behind him."] = "{quest:92529}在申德村南邊。{npc:257065}在村子邊緣與你會面；搜查他身後房子裡的衣櫃。",
} end)()
t.guides["forever/horde/tauren/01-mulgore"] = (function() return {
		["/sit by Kaga's campfire until you get {spell:1229451}"] = "在Kaga的營火旁 /sit，直到獲得{spell:1229451}",
		["Back east to {area:358}: the Bristleback Shamans stand among the quilboar there."] = "向東回到{area:358}：刺背薩滿站在那裡的野豬人之間。",
		["Back south-east to the {area:396}."] = "向東南回到{area:396}。",
		["Back to {npc:5888} in the camp. The {npc:5891} waits on the mesa east of the camp: drink the {item:6635} there to see it, then take the {item:6656} back to the Seer."] = "回到營地找{npc:5888}。{npc:5891}在營地東邊的平頂山上等著：在那裡喝下{item:6635}才能看見它，然後把{item:6656}帶回給先知。",
		["Back west to the camp."] = "向西回到營地。",
		["Battleboars graze north of the shrine; the Bristleback quilboar hold the ravine to the north-east. {npc:8554} stands at its eastern end, and the {object:3076} lies on the ground in the camp."] = "鬥豬在神殿北邊吃草；刺背野豬人佔據東北方的峽谷。{npc:8554}站在峽谷東端，{object:3076}就在營地的地上。",
		["Below ground"] = "地下",
		["Class trainer"] = "職業訓練師",
		["Cross north-west past {zone:1456} to the {area:398} in the far north of {zone:1412}."] = "向西北經過{zone:1456}，前往{zone:1412}最北邊的{area:398}。",
		["Follow the path south out of camp to the Seer's tent at the foot of the hills."] = "沿小徑向南出營地，前往山腳下灰舌先知的帳篷。",
		["Follow the road north out of {area:220}. {npc:265810} waits on the road just south of {area:222}; /sit by her campfire until you get {spell:1229451}. With a profession learned, Kaga also offers its Camping 101, which its trainer takes: in Bloodhoof or on the {zone:1456} stop."] = "沿道路從{area:220}向北走。{npc:265810}在{area:222}南邊不遠的路上等著；在她的營火旁 /sit，直到獲得{spell:1229451}。學會專業技能後，Kaga還會提供她的露營入門任務，交給該專業的訓練師：在血蹄村或{zone:1456}停留時繳交。",
		["Galak centaurs"] = "加拉克半人馬",
		["Head north to {area:225}, east of {zone:1456}. {npc:3233} stands at the foot of the rocks; the Bristleback Interlopers dig at the burial ground and the {npc:2994} waits on top."] = "向北前往{zone:1456}東邊的{area:225}。{npc:3233}站在岩石底部；刺背干涉者在墓地挖掘，{npc:2994}在頂上等著。",
		["Prairie Wolf Alphas roam among the wolves on the plains around {npc:275789} and the Galak camp to the east."] = "草原狼前鋒在{npc:275789}和東邊加拉克營地周圍的平原上，混在狼群之中遊蕩。",
		["Prairie Wolves and Adult Plainstriders roam the plains around the village."] = "草原狼和成年平原陸行鳥在村子周圍的平原遊蕩。",
		["Ride a lift up to the mesas. {npc:2995} keeps the wind riders on the central rise; {npc:3057} stands in the great tent there."] = "搭升降梯上到平頂山。{npc:2995}在中央高台照料雙足飛龍；{npc:3057}站在那裡的大帳篷裡。",
		["Spread the {item:278078} off {area:1641}"] = "在{area:1641}撒下{item:278078}",
		["Tame it with the {item:15908}"] = "用{item:15908}馴服牠",
		["The Palemane gnolls hold {area:818}, south of the digsite and west of Bloodhoof. {npc:272203} is held in their camp: lead him out."] = "白鬃豺狼人佔據{area:818}，位於挖掘場南邊、血蹄村西邊。{npc:272203}被關在他們的營地裡：帶他出來。",
		["The Windfury harpies hold {area:819}, north and west of the well."] = "風怒鷹身人佔據水井北邊和西邊的{area:819}。",
		["The dwarves of the {area:404} carry the Prospector's Picks. Smash them at the dwarves' forge in the digsite."] = "{area:404}的矮人身上帶著勘察員的鋤頭。在挖掘場裡矮人的熔爐砸毀它們。",
		["The goblins work the mine in the hills north-east of the well. {quest:765} stands in the back of the mine; his {item:281031} start {quest:98424}, and the other pages lie inside the mine."] = "哥布林在水井東北方丘陵的礦坑工作。{quest:765}站在礦坑深處；他的{item:281031}會開啟{quest:98424}，其他書頁在礦坑裡。",
		["The incense burns out in ten minutes: run straight east along the southern hills to the {object:660739}."] = "薰香十分鐘就會燒完：沿南邊的丘陵直接向東跑到{object:660739}。",
		["The shrine of An'she and Mu'sha"] = "安希與Mu'sha的神殿",
		["The stone stands in the pass out of {zone:1412}, on your way east. Use the {item:15710} there and defeat Lunaclaw."] = "石頭位於離開{zone:1412}的山口，就在你往東的路上。在那裡使用{item:15710}並擊敗月爪梟獸。",
		["The wrecked caravan lies north-west of the centaurs, east of the road to {zone:1456}."] = "失事的商隊在半人馬西北方、通往{zone:1456}的道路東邊。",
		["The {object:177525}"] = "{object:177525}",
		["To {zone:1454}"] = "前往{zone:1454}",
		["Use the {item:278078} at the ceremonial mat and burner on the south-facing cliff of {area:1641}."] = "在{area:1641}朝南的懸崖上，對儀式墊和香爐使用{item:278078}。",
		["You start on the mesa of {area:221}. {npc:2980} and the chief stand by the big tent in the middle."] = "你從{area:221}的平頂山開始。{npc:2980}和鷹風酋長站在中央的大帳篷旁。",
		["{item:278079}, from {npc:3014}"] = "{item:278079}，向{npc:3014}購買",
		["{item:278080}, from {npc:3012}"] = "{item:278080}，向{npc:3012}購買",
		["{item:278081}, from {npc:3005}"] = "{item:278081}，向{npc:3005}購買",
		["{item:278083}, from {npc:3027}"] = "{item:278083}，向{npc:3027}購買",
		["{item:4703}, at the digsite forge"] = "{item:4703}，在挖掘場的熔爐旁",
		["{item:5203}: Flatland Prowlers roam the plains around {area:225}"] = "{item:5203}：平原徘徊者在{area:225}周圍的平原遊蕩",
		["{npc:265810}: for {npc:10278}"] = "{npc:265810}：給{npc:10278}",
		["{npc:265810}: for {npc:11047}"] = "{npc:265810}：給{npc:11047}",
		["{npc:265810}: for {npc:11051}"] = "{npc:265810}：給{npc:11051}",
		["{npc:265810}: for {npc:11071}"] = "{npc:265810}：給{npc:11071}",
		["{npc:265810}: for {npc:3001}"] = "{npc:265810}：給{npc:3001}",
		["{npc:265810}: for {npc:3013}"] = "{npc:265810}：給{npc:3013}",
		["{npc:265810}: for {npc:3069}"] = "{npc:265810}：給{npc:3069}",
		["{npc:265810}: for {npc:5938}"] = "{npc:265810}：給{npc:5938}",
		["{npc:265810}: for {npc:5939}"] = "{npc:265810}：給{npc:5939}",
		["{npc:265810}: for {npc:6290}"] = "{npc:265810}：給{npc:6290}",
		["{npc:269068} wants tauren incense: buy its four parts from {npc:3014} the herbalist, {npc:3012} the enchanting supplier, {npc:3005} the leatherworking supplier and {npc:3027} the cooking supplier, then combine them into {item:278078}."] = "{npc:269068}想要牛頭人的薰香：向草藥商{npc:3014}、附魔供應商{npc:3012}、製皮供應商{npc:3005}和烹飪供應商{npc:3027}購買四種材料，然後合成{item:278078}。",
		["{npc:277182} stands at the north edge of the village. Kyle wants {item:287505} from plainstriders."] = "{npc:277182}站在村子北緣。Kyle想要從平原陸行鳥取得的{item:287505}。",
		["{npc:277182}, at the north end of the village"] = "{npc:277182}，在村子北端",
		["{npc:2948}, for Hamuul in {zone:1456}"] = "{npc:2948}，給{zone:1456}的大德魯伊哈繆爾·符文圖騰",
		["{npc:2984} stands at the edge of the {area:404}, south of the well."] = "{npc:2984}站在{area:404}邊緣，水井南邊。",
		["{npc:2991} sits by the tent on the camp's eastern edge; the {object:2907} stands next to her."] = "{npc:2991}坐在營地東緣的帳篷旁；{object:2907}就在她旁邊。",
		["{npc:2993}, for {npc:3057} in {zone:1456}"] = "{npc:2993}，給{zone:1456}的{npc:3057}",
		["{npc:3060}, the druid trainer beside him"] = "他旁邊的德魯伊訓練師{npc:3060}",
		["{npc:3061}, the hunter trainer"] = "獵人訓練師{npc:3061}",
		["{npc:3062}, the shaman trainer in camp"] = "營地裡的薩滿訓練師{npc:3062}",
		["{npc:3063}'s quest: beat three Novice Warriors (or players in duels) next to him."] = "{npc:3063}的任務：在他旁邊擊敗三名新戰士（或在決鬥中擊敗玩家）。",
		["{npc:3069}, beside {npc:3067}: {quest:97934}"] = "{npc:3069}，在{npc:3067}旁邊：{quest:97934}",
		["{npc:3418} stands at {area:378}, where the road from {zone:1412} meets the {area:458} north to the Crossroads."] = "{npc:3418}站在{area:378}，也就是{zone:1412}來的道路與向北通往十字路口的{area:458}交會之處。",
		["{npc:3418}: for {npc:3429} at the Crossroads"] = "{npc:3418}：給十字路口的{npc:3429}",
		["{npc:3429}, by the wind rider tower"] = "{npc:3429}，在雙足飛龍塔旁",
		["{npc:3615}, the wind rider master"] = "雙足飛龍管理員{npc:3615}",
		["{npc:5888} stands in {area:221}. {quest:1516} needs level 4, which you reach with the turn-ins here."] = "{npc:5888}站在{area:221}。{quest:1516}需要4級，在這裡繳交任務就能達到。",
		["{npc:5888}: {npc:5873} and your {item:5175}"] = "{npc:5888}：{npc:5873}和你的{item:5175}",
		["{npc:6290}, beside {npc:3067}: {quest:97936}"] = "{npc:6290}，在{npc:3067}旁邊：{quest:97936}",
		["{npc:6775} stands at the west end of the camp, at the north-west corner of the hills where the Mountain Cougars prowl: take his quest, hunt the cougars from there south and east, then come back up to {npc:2980}."] = "{npc:6775}站在營地西端，山獅出沒的丘陵西北角：接他的任務，從那裡往南和往東獵殺山獅，然後回到{npc:2980}那裡。",
		["{quest:96130}, a lone wolf, prowls the plains west of the village. Prairie Stalkers and Flatland Cougars roam the plains north and west of it."] = "孤狼{quest:96130}在村子西邊的平原徘徊。草原捕食者和平原獅在村子北邊和西邊的平原遊蕩。",
} end)()
t.guides["forever/horde/troll/01-durotar"] = (function() return {
		["Armored Scorpids crawl over the plains west of {area:362}. Tame one, then return to {npc:3171}."] = "硬甲蠍在{area:362}西邊的平原上爬行。馴服一隻，然後回到{npc:3171}那裡。",
		["Back to the Den"] = "回到大獸穴",
		["Back to {area:362}."] = "回到{area:362}。",
		["Below ground"] = "地下",
		["Burning Blade cultists hold the caves of {quest:827}; any of them drops a {item:4871}. {npc:3204}, a level 14 warlock, stands deep inside and drops the {item:4903}."] = "燃刃氏族的教徒佔據{quest:827}的洞穴；他們都會掉落{item:4871}。{npc:3204}是14級的術士，站在深處，會掉落{item:4903}。",
		["Class trainer"] = "職業訓練師",
		["Felstalkers roam the slope below the cave, on the valley's north side."] = "地獄捕獵者在洞穴下方的山坡上遊蕩，位於山谷北側。",
		["Follow the road east out of the valley to {area:367} on the coast."] = "沿著道路向東離開山谷，前往海岸邊的{area:367}。",
		["Free {npc:275811} and see her safely out of the crag"] = "釋放{npc:275811}，並護送她安全離開峭壁",
		["Heal and fortify {npc:12430}"] = "治療{npc:12430}並為她施放耐力",
		["Inside the cave, go straight on at the first split, then right and follow the stream on your left to the waterfall: the pick glows by the water, behind a column of rock."] = "進入洞穴後，在第一個岔路直走，然後往右，沿著左手邊的溪流走到瀑布：鎬在水邊發光，在一根石柱後面。",
		["Inside the cave, keep to the right wall all the way round, over the stream: {npc:3183} waits at the end."] = "進入洞穴後，一路沿著右側牆壁繞行，越過溪流：{npc:3183}在盡頭等著。",
		["Misha's hut stands south of the lizards. The crocolisks along the {area:814} to the west carry {item:4891}."] = "米莎的小屋在蜥蜴的南邊。西邊{area:814}沿岸的鱷魚身上帶著{item:4891}。",
		["Prickly pears"] = "仙人掌果",
		["Quilboars and scouts hold the huts west of town; dustrunners and battleguards hold the camps farther west."] = "鋼鬃野豬人和鋼鬃斥候佔據城鎮西邊的小屋；鋼鬃傳令兵和鋼鬃衛兵佔據更西邊的營地。",
		["Spitelash naga"] = "惡鞭納迦",
		["Tame it with the {item:15908}"] = "用{item:15908}馴服牠",
		["The keep stands on the coast south-east of {area:362}. The raiders' axe, bow and shield lie on its outskirts. Sailors and marines drop the {item:4870}. {npc:3192} waits at the top of the keep; his key opens the chest beside him, which holds the {item:4881}."] = "城堡位於{area:362}東南方的海岸上。襲擊者的斧頭、弓和盾牌在城堡外圍。庫爾提拉斯水手和水兵會掉落{item:4870}。{npc:3192}在城堡頂端等候；他的鑰匙可以打開他旁邊的箱子，裡面有{item:4881}。",
		["The prickly pears grow among the quilboar huts just west of town."] = "仙人掌果生長在城鎮西邊的野豬人小屋之間。",
		["The weapons lie around the Den and the training grounds; the Mottled Boars roam the whole valley floor."] = "武器散落在大獸穴和訓練場周圍；雜斑野豬在整個谷底遊蕩。",
		["The {object:58595} stands in {area:817}, among the cultists you just fought."] = "{object:58595}在{area:817}裡，就在你剛才打過的教徒之間。",
		["To {zone:1454}"] = "前往{zone:1454}",
		["Training weapons and boars"] = "訓練武器與野豬",
		["Upstairs"] = "樓上",
		["Wake {quest:5441} with the {item:16114}"] = "用{item:16114}叫醒{quest:5441}",
		["the {object:654925} on the ground beside her"] = "她旁邊地上的{object:654925}",
		["{area:366} lies west of Sen'jin. The three attack plans sit on the ground among the centaur tents. {npc:275811} is held at the crag as well."] = "{area:366}在森金村西邊。三份進攻計畫放在半人馬帳篷之間的地上。{npc:275811}也被關在峭壁那裡。",
		["{area:817}'s mouth"] = "{area:817}入口",
		["{npc:10176}, where you start"] = "{npc:10176}，在你的出生點",
		["{npc:12430} kneels behind the rocks just off the road south of {area:362}, on your way to the keep. Cast {spell:613} (Rank 2) on her, then {spell:1243}: Rank 1 of {spell:613} does not count."] = "{npc:12430}跪在{area:362}南邊道路旁的岩石後面，就在你前往城堡的路上。對她施放{spell:613}（等級2），然後施放{spell:1243}：等級1的{spell:613}不算數。",
		["{npc:265809} camps just south of {area:362}. Sit by his campfire (/sit) until the {spell:1229451} buff appears. With a profession learned, {npc:265809} also offers its Camping 101, which its trainer takes: in {area:362} or in {zone:1454} at the start of the next guide."] = "{npc:265809}在{area:362}南邊紮營。坐在他的營火旁（/sit），直到出現{spell:1229451}增益效果。學會專業技能後，{npc:265809}也會提供該專業的露營入門任務，交給該專業的訓練師：在{area:362}或在{zone:1454}（下一份指南的開頭）。",
		["{npc:265809}'s campfire"] = "{npc:265809}的營火",
		["{npc:265809}: for {npc:11025}"] = "{npc:265809}：交給{npc:11025}",
		["{npc:265809}: for {npc:11046}"] = "{npc:265809}：交給{npc:11046}",
		["{npc:265809}: for {npc:11066}"] = "{npc:265809}：交給{npc:11066}",
		["{npc:265809}: for {npc:2855}"] = "{npc:265809}：交給{npc:2855}",
		["{npc:265809}: for {npc:3175}"] = "{npc:265809}：交給{npc:3175}",
		["{npc:265809}: for {npc:3365}"] = "{npc:265809}：交給{npc:3365}",
		["{npc:265809}: for {npc:3404}"] = "{npc:265809}：交給{npc:3404}",
		["{npc:265809}: for {npc:5943}"] = "{npc:265809}：交給{npc:5943}",
		["{npc:265809}: for {npc:7088}"] = "{npc:265809}：交給{npc:7088}",
		["{npc:266881}: enchanters only, the residue is disenchanted from Hexed Pendants"] = "{npc:266881}：僅限附魔師，殘渣要從妖術墜飾分解取得",
		["{npc:275657} stands on the shore east of {area:362}. The trident, banner and dagger lie on the beach around him."] = "{npc:275657}站在{area:362}東邊的岸上。三叉戟、旗幟和匕首散落在他周圍的海灘上。",
		["{npc:3102} hooves"] = "{npc:3102}的蹄子",
		["{npc:3142}, back in {area:362}"] = "{npc:3142}，回到{area:362}",
		["{npc:3142}: {npc:275666}, an elite sea giant"] = "{npc:3142}：{npc:275666}，一個精英海巨人",
		["{npc:3143} stands just inside the cave mouth; {npc:3159} at the back of the cave behind him."] = "{npc:3143}就站在洞口內；{npc:3159}在他身後的洞穴深處。",
		["{npc:3143} waits inside the Den, the building just west of {npc:10176}."] = "{npc:3143}在大獸穴裡等候，就是{npc:10176}西邊的那棟建築。",
		["{npc:3147}, in the watchtower"] = "{npc:3147}，在瞭望塔裡",
		["{npc:3287} lies wounded at the foot of the hills north-west of the Den."] = "{npc:3287}受傷躺在大獸穴西北方的山腳下。",
		["{npc:3294}, by the inn"] = "{npc:3294}，在旅店旁",
		["{npc:3706}, beside {npc:266940}: the {item:16606}"] = "{npc:3706}，在{npc:266940}旁邊：{item:16606}",
		["{npc:3706}, for {npc:6018} in {zone:1454}: keep it"] = "{npc:3706}，交給{zone:1454}的{npc:6018}：保留此任務",
		["{npc:3706}, in the barracks beside {npc:266940}"] = "{npc:3706}，在{npc:266940}旁邊的兵營裡",
		["{npc:3707}, the priest trainer at the Den"] = "{npc:3707}，大獸穴的牧師訓練師",
		["{npc:3707}, the priest trainer at the Den: for {npc:3706} in {area:362}"] = "{npc:3707}，大獸穴的牧師訓練師：交給{area:362}的{npc:3706}",
		["{npc:5875} stands in the {object:172960}, the canyon under the {object:172982}. Hand him the {item:6535}, then use the {item:7464} on the summoning circle beside him and defeat the voidwalker to bind it."] = "{npc:5875}站在{object:172960}，也就是{object:172982}下方的峽谷。把{item:6535}交給他，然後在他旁邊的召喚法陣使用{item:7464}，擊敗虛空行者以束縛它。",
		["{npc:5887} stands outside the Den. {area:639} is the hill just south of it: drink the {item:6635} there to see the {npc:5891}, then take the {item:6656} back to {npc:5887}."] = "{npc:5887}站在大獸穴外。{area:639}就是它南邊的山丘：在那裡喝下{item:6635}以看見{npc:5891}，然後把{item:6656}帶回給{npc:5887}。",
		["{npc:5887}: {npc:5873} and your {item:5175}"] = "{npc:5887}：{npc:5873}和你的{item:5175}",
		["{npc:5891}, on {area:639}"] = "{npc:5891}，在{area:639}上",
		["{npc:6786} stands on the road at the valley's eastern exit."] = "{npc:6786}站在山谷東側出口的道路上。",
		["{npc:9796} stands just outside the Den's entrance."] = "{npc:9796}就站在大獸穴入口外。",
		["{npc:9796}, by the cooking fire"] = "{npc:9796}，在烹飪火堆旁",
		["{quest:828} camps on the hill west of the naga beach, south of {quest:827}."] = "{quest:828}在納迦海灘西邊的山丘上紮營，位於{quest:827}南邊。",
		["{zone:1454}'s main gate is just west of {area:817}. {npc:5875} stands in the {object:172960}, the canyon under the {object:172982}."] = "{zone:1454}的正門就在{area:817}西邊。{npc:5875}站在{object:172960}，就是{object:172982}下方的峽谷。",
} end)()
t.guides["forever/horde/undead/01-tirisfal-glades"] = (function() return {
